window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0075", [{"word":"conserve","ipa_uk":"/kənˈsɜːv/","ipa_us":"/kənˈsɜːrv/","definition_zh":"保存；保护；节约（资源）；把果子熬成蜜饯","definition_en":"to keep something in good condition and prevent it from being damaged, wasted or used up","core_image":"一间恒温恒湿的库房把老纸页锁在里面，门外是不断变化的天气，门内一切不变","scene":"Volunteers conserve the fragile manuscripts in a climate-controlled vault.","sceneCN":"这里 conserve 指「妥善保存，使易损物件不继续损坏」（第 1 个义项：把物件维持在稳定状态以免受损）；句意为志愿者把易损手稿放进恒温恒湿的库房保存。图中可辨识物件：恒温柜、平放的纸页、湿度表、白手套。","pos":[{"tag":"vt.","zh":"保存；保护；节约（资源、能量）"},{"tag":"n.","zh":"蜜饯；果脯（英式，指加糖熬煮的果酱）"}],"collocations":[{"phrase":"conserve energy","zh":"节约能源"},{"phrase":"conserve water","zh":"节约用水"},{"phrase":"conserve resources","zh":"保护资源"},{"phrase":"conserve wildlife","zh":"保护野生动物"},{"phrase":"conserve fuel","zh":"节省燃料"},{"phrase":"conserve strength","zh":"保存体力"}],"forms":[{"label":"三单（he/she/it）","form":"conserves"},{"label":"过去式","form":"conserved"},{"label":"过去分词","form":"conserved"},{"label":"现在分词","form":"conserving"},{"label":"名词（保存；保护）","form":"conservation"},{"label":"名词（保护区管理）","form":"conservancy"}],"derivatives":[{"word":"conservation","pos":"n.","zh":"保存；保护；资源管理"},{"word":"conservative","pos":"adj./n.","zh":"保守的 / 保守者"},{"word":"conservationist","pos":"n.","zh":"自然保护主义者"},{"word":"conservator","pos":"n.","zh":"文物修复师；管理者"},{"word":"conservancy","pos":"n.","zh":"保护区管理机构"}],"senses":[{"no":"01","title":"Keep an object from further damage","titleCN":"把物件维持在稳定环境以免继续损坏","definition":"to keep a fragile object in a stable condition so that it does not decay or break down","definitionCN":"把易损物件维持在稳定条件下，使其不再腐坏或破损","example":"Volunteers conserve the fragile manuscripts in a climate-controlled vault.","exampleCN":"志愿者把易损手稿保存在恒温恒湿的库房里。","why":"conserve is built from com- 'thoroughly' plus servare 'to keep safe', so the core reading is to keep something safe all round.","whyCN":"conserve 由 com-「彻底」加 servare「守住」构成，核心意思就是「把某物整个守住」。"},{"no":"02","title":"Protect a natural resource","titleCN":"保护自然资源，使其能长期存在","definition":"to use a natural resource carefully so that it survives for future use","definitionCN":"谨慎使用自然资源，使其能留存到未来","example":"Ranchers conserve grassland by rotating their herds.","exampleCN":"牧场主用轮牧的方式保护草地。","why":"the environmental sense grew out of the older one: a forest is kept safe by limiting how much is taken from it.","whyCN":"环保义由旧义延伸而来：限制取用量，就是让森林保持安全。"},{"no":"03","title":"Avoid wasting time or effort","titleCN":"节省体力、时间与燃料，不作无谓消耗","definition":"to avoid using up energy, time or strength unnecessarily","definitionCN":"避免无谓地消耗体力、时间或力量","example":"Runners conserve energy on the climb so they can sprint at the end.","exampleCN":"跑者在爬坡时保存体力，好在最后冲刺。","why":"keeping a supply safe and not drawing on it are the same idea seen from two sides, so conserve slid into the sense of saving.","whyCN":"把储备守住与不动用它，是同一件事的两面，因此 conserve 自然引申出「节省」。"},{"no":"04","title":"Cook fruit into a conserve","titleCN":"把水果加糖熬成蜜饯","definition":"to cook fruit with sugar so that it keeps for a long time","definitionCN":"把水果与糖一起熬煮，使其能长期存放","example":"They conserve plums with honey and a little lemon.","exampleCN":"他们把李子加蜂蜜和少许柠檬熬成蜜饯。","why":"from the sixteenth century the word was applied to food kept safe by sugar, since sugar does for fruit what a vault does for paper.","whyCN":"从 16 世纪起，这个词用于靠糖保住的食物：糖对果子做的事，正如库房对纸页做的事。"},{"no":"05","title":"A thick fruit jam","titleCN":"蜜饯；果脯（名词义）","definition":"a thick sweet preparation of fruit cooked with sugar","definitionCN":"水果加糖熬成的浓稠甜品","example":"A spoonful of apricot conserve went onto the warm bread.","exampleCN":"一勺杏子蜜饯抹在热面包上。","why":"the noun is simply the product of the verb, so English uses the same form for the act and for the jar.","whyCN":"名词只是动词的产物，因此英语用同一个词形既指动作也指罐中之物。"},{"no":"06","title":"Hold a quantity constant in physics","titleCN":"物理中保持某个量守恒","definition":"to remain constant through a physical process, as mass or charge does","definitionCN":"在物理过程中保持不变，如质量或电荷","example":"In an isolated system, charge is conserved through every reaction.","exampleCN":"在孤立系统中，电荷在每一次反应中都守恒。","why":"the older sense of keeping something intact was narrowed by physics into the rule that a total does not change.","whyCN":"「保持完整」的旧义被物理学收窄为一条规则：总量不发生变化。"},{"no":"07","title":"Keep a right or condition in force","titleCN":"使某项权利或状态继续有效","definition":"to keep a legal right or an arrangement valid rather than letting it lapse","definitionCN":"使法律权利或某种安排继续有效，而非任其失效","example":"The clause conserves the tenant's right to renew the lease.","exampleCN":"该条款保留了租客续租的权利。","why":"law borrowed the word because a right that is kept safe is a right that is not lost by silence or delay.","whyCN":"法律借用这个词，因为权利被守住就意味着不因沉默或拖延而丧失。"},{"no":"08","title":"Keep the essential character","titleCN":"抽象义：在变形中保住核心特征","definition":"to keep the essential character of something even when its outward form changes","definitionCN":"即使外在形式改变，也保住某物的核心特征","example":"The arranger conserved the melody while rewriting every harmony.","exampleCN":"编曲者改写了全部和声，却保住了旋律。","why":"the abstract sense generalizes the core: what is conserved is no longer a thing but the pattern that makes it what it is.","whyCN":"抽象义把核心一般化：被守住的不再是一件东西，而是使它成为它的那个格局。"}],"etymology":{"intro":{"en":"Conserve comes through Old French from Latin conservare 'to keep safe, maintain', built on com- 'together, thoroughly' and servare 'to keep, watch over'. Dates are approximate.","cn":"conserve 经古法语来自拉丁 conservare「保住、维持」，由 com-「共同、彻底」与 servare「看守、保存」构成。年代均为约数。"},"items":[{"era":"LATIN SERVARE","en":"Servare meant 'to keep, watch over, guard'. Its deeper origin is not established; the link sometimes suggested to servire 'to serve' is a hypothesis, not a demonstrated derivation.","cn":"servare 意为「看守、保存、守护」。其更深来源未得到证明；有人把它与 servire「服侍」联系起来，那只是假说，并非已证实的派生。"},{"era":"LATIN CONSERVARE","en":"Com- 'together, thoroughly' plus servare produced conservare 'to keep safe, to maintain, to preserve'.","cn":"com-「共同、彻底」加 servare 构成 conservare「保住、维持、保存」。"},{"era":"OLD FRENCH","en":"Old French conserver carried the verb into English in the fourteenth century, first in the sense of keeping health or a condition intact.","cn":"古法语 conserver 在 14 世纪把这个动词带入英语，最初指保持健康或某种状态不坏。"},{"era":"FOOD SENSE","en":"By the sixteenth century conserve was used for fruit cooked with sugar, and the noun for the product followed soon after.","cn":"到 16 世纪，conserve 已用于指加糖熬煮的水果，指成品的名词义随后出现。"},{"era":"RESOURCE SENSE","en":"From the nineteenth century the word was applied to forests, soil and wildlife, and this resource sense now dominates everyday use.","cn":"从 19 世纪起，这个词被用于森林、土壤与野生动物，这一资源义如今在日常使用中占主导。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): no exact first citation is recorded for the resource sense, and the pre-Latin origin of servare is unsettled, so any Indo-European form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：资源义没有确切的最早书证；servare 在拉丁语之前的来源亦无定论，凡为其给出的印欧形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds verbs built on the Latin -serve stock that are constantly confused; group two holds near neighbours with a different shade of keeping.","cn":"第一组是同出拉丁 -serve 词干、极易混淆的动词；第二组是语义相近但「保住」的侧重点不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"preserve","ipa":"/prɪˈzɜːv/","tag":"guard beforehand","definition":"Built on prae- 'before' plus servare, so it stresses protecting something before harm reaches it; it also names jam and a nature reserve.","definitionCN":"由 prae-「在前」加 servare 构成，强调在损害到来之前先护住；也指果酱与自然保护区。"},{"word":"reserve","ipa":"/rɪˈzɜːv/","tag":"keep back","definition":"Re- 'back' plus servare: to hold something back for later use, as in reserve a seat or oil reserves.","definitionCN":"re-「向后」加 servare：把某物留到以后用，如预订座位、石油储量。"},{"word":"deserve","ipa":"/dɪˈzɜːv/","tag":"different root","definition":"From de- 'fully' plus servire 'to serve', not servare: to have earned something by service, so it is not a relative of conserve at the root.","definitionCN":"来自 de-「完全」加 servire「服侍」，而非 servare：因服务而应得，因此词根上与 conserve 并非同族。"},{"word":"observe","ipa":"/əbˈzɜːv/","tag":"watch toward","definition":"Ob- 'toward' plus servare: to keep one's eyes on something, hence to watch, notice or obey a rule.","definitionCN":"ob-「朝向」加 servare：把目光守在事物上，因此指观察、注意或遵守规则。"}]},{"heading":"NEAR MEANING","entries":[{"word":"protect","ipa":"/prəˈtekt/","tag":"shield from harm","definition":"A general verb for shielding something from danger; it says nothing about careful use, which conserve adds.","definitionCN":"泛指使某物免受危险，不含「节制使用」的意思，而 conserve 带有这一层。"},{"word":"maintain","ipa":"/meɪnˈteɪn/","tag":"keep in working order","definition":"To keep something in its current working condition, as a road or a machine; conserve is closer to keeping it from loss.","definitionCN":"使某物保持现有的运转状态，如道路或机器；conserve 更偏向使之不致损失。"},{"word":"save","ipa":"/seɪv/","tag":"plain everyday word","definition":"The common verb for avoiding waste, as in save water; conserve is its formal and technical counterpart.","definitionCN":"指避免浪费的日常动词，如节约用水；conserve 是它正式、技术化的对应词。"},{"word":"retain","ipa":"/rɪˈteɪn/","tag":"hold on to","definition":"To continue to hold something already possessed, such as heat or a right; it does not imply active care.","definitionCN":"指继续保有已拥有之物，如热量或权利；不含主动照料之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"com- 'thoroughly' + servare 'keep safe': to keep something safe all round.","cn":"com-「彻底」+ servare「守住」：把某物整个护住。"},{"en":"The family runs conserve, conservation, conservative, conservationist, conservator, conservancy.","cn":"同族词包括 conserve、conservation、conservative、conservationist、conservator、conservancy。"},{"en":"Fixed phrases mark the resource sense: conserve energy, conserve water, conserve wildlife.","cn":"固定搭配标出资源义：节约能源、节约用水、保护野生动物。"},{"en":"The same root appears in preserve, reserve and observe, all through Latin servare.","cn":"同一词根出现在 preserve、reserve 与 observe 中，都经拉丁 servare。"},{"en":"Physics uses the passive form: charge is conserved, energy is conserved.","cn":"物理用被动式：电荷守恒、能量守恒。"}],"abstract":[{"en":"Picture a sealed jar that holds summer inside it while winter runs outside.","cn":"想象一只密封罐，里面装着夏天，外面正跑着冬天。"},{"en":"Picture a bank account nobody draws from, so the balance stays what it was.","cn":"想象一个没人取钱的账户，余额始终停在原处。"},{"en":"Picture a song rearranged into a new key but still recognizably itself.","cn":"想象一首歌被改写调性，却仍听得出是原来的歌。"}]},"examples":[{"en":"The trust conserves the wetland by buying the land around it.","cn":"该信托基金买下周边土地，以保护这片湿地。"},{"en":"Turning off unused lights conserves both energy and money.","cn":"关掉不用的灯既省能源也省钱。"},{"en":"In every chemical reaction, the total mass is conserved.","cn":"在每一个化学反应中，总质量守恒。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「con（共同）+ serve（服务/看守）」——大家一起守住资源 → 保存、保护、节约","word":"conserve"},"root":"拉丁 conservare「保住、维持」= com-（共同、彻底）+ servare「看守、保存」；servare 更深来源不确定，与 servire「服侍」的联系仅为假说。英语 conserve。","sensesIntro":{"en":"Eight senses follow one gesture: something valuable is closed off from decay, and that gesture is then applied to forests, fuel, fruit, physical totals, legal rights and finally to a pattern that survives a rewrite.","cn":"八个义项沿同一个动作展开：把有价值之物与腐坏隔开，这个动作再依次用于森林、燃料、果子、物理总量、法律权利，最后用于一个经改写仍存活的格局。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stable room holding something precious while the weather outside keeps changing.","cn":"核心意象：一间稳定的屋子守住贵重之物，屋外天气不断变化。"},"chain":["KEEP SAFE","KEEP INTACT","USE WISELY","AVOID WASTE","HOLD CONSTANT","SEALED FRUIT"],"branches":[{"senses":"S1 · S7","en":"KEEP-SAFE OBJECT: whether paper or a lease, the point is that nothing is lost.","cn":"守住对象：无论纸页还是租约，要点都是不让它失去。"},{"senses":"S2 · S3","en":"WISE USE: a supply is kept safe by drawing on it slowly.","cn":"善用：慢慢取用，储备才得以安全。"},{"senses":"S4 · S5","en":"SEALED FRUIT: sugar does for fruit what a vault does for paper.","cn":"封住的果子：糖对果子做的事，正如库房对纸页做的事。"},{"senses":"S6","en":"CONSTANT TOTAL: physics narrows keeping intact to a number that never changes.","cn":"总量不变：物理学把「保持完整」收窄为一个永不改变的数。"},{"senses":"S8","en":"SURVIVING PATTERN: what is kept is no longer a thing but the shape that makes it itself.","cn":"存活的格局：被守住的不再是实体，而是使它成为它的形态。"}]},"affixes":{"intro":{"en":"Conserve is a Latin verb made of a prefix and a root that also build several other English words, so the whole family can be read morpheme by morpheme.","cn":"conserve 是一个由前缀与词根构成的拉丁动词，这两部分还构成若干英语词，因此整个词族可以按语素逐个读出。"},"latinIntro":{"en":"Latin servare gives conserve, preserve, reserve, observe and servitude; com- adds the sense of doing something thoroughly or together.","cn":"拉丁 servare 衍生 conserve、preserve、reserve、observe 与 servitude；com- 增添「彻底、共同」的意思。"},"items":[{"word":"con-","structure":"com- (Latin prefix, 'together, thoroughly')","meaning":"together; completely","meaningCN":"共同；彻底","example":"The prefix binds the action into a single whole.","exampleCN":"这个前缀把动作收束为一个整体。"},{"word":"servare","structure":"servare (Latin verb, first conjugation)","meaning":"to keep, watch over, guard","meaningCN":"看守；保存；守护","example":"The root carries the idea of keeping watch.","exampleCN":"这个词根带着「看守」的意思。"},{"word":"conserve","structure":"con- + servare","meaning":"to keep safe","meaningCN":"保住；保存","example":"Volunteers conserve the fragile manuscripts.","exampleCN":"志愿者保存易损手稿。"},{"word":"conservation","structure":"conserve + -ation (action or result)","meaning":"the act or result of keeping safe","meaningCN":"保存（动作或结果）","example":"Soil conservation slowed the erosion.","exampleCN":"土壤保护减缓了侵蚀。"},{"word":"conservative","structure":"conserve + -ative (tending to)","meaning":"tending to keep things as they are","meaningCN":"倾向维持原状的；保守的","example":"She took a conservative estimate of the cost.","exampleCN":"她对成本做了保守的估计。"},{"word":"conservationist","structure":"conservation + -ist (person who does)","meaning":"a person who works to protect nature","meaningCN":"从事自然保护的人","example":"The conservationist mapped the last old-growth stands.","exampleCN":"这位自然保护者标出了最后几片原始林。"},{"word":"conservator","structure":"conserve + -or (one who acts)","meaning":"a person who repairs and maintains objects","meaningCN":"修复并维护物件的人","example":"The conservator cleaned the painting layer by layer.","exampleCN":"修复师一层层地清理这幅画。"},{"word":"conservancy","structure":"conserve + -ancy (state or body)","meaning":"an organization or area that manages protection","meaningCN":"保护管理机构或保护区","example":"The river conservancy patrols the banks.","exampleCN":"河流保护机构巡护两岸。"},{"word":"conservable","structure":"conserve + -able (can be)","meaning":"able to be kept safe","meaningCN":"可保存的","example":"Only a conservable portion of the archive survived.","exampleCN":"档案中只有可保存的一部分留了下来。"}],"latinEntries":[{"word":"servare","structure":"servare, servavi, servatum (verb, first conjugation)","meaning":"to keep, guard, preserve","meaningCN":"看守；守护；保存"},{"word":"conservare","structure":"conservare, conservavi, conservatum (verb, first conjugation)","meaning":"to keep safe, maintain","meaningCN":"保住；维持"},{"word":"conservatio","structure":"conservatio, conservationis (f., third declension)","meaning":"a preserving, keeping","meaningCN":"保存；保全"},{"word":"conservator","structure":"conservator, conservatoris (m., third declension)","meaning":"one who preserves","meaningCN":"保存者；维护者"}]}},{"word":"preserve","ipa_uk":"/prɪˈzɜːv/","ipa_us":"/prɪˈzɜːrv/","definition_zh":"保存；保护；维持；果酱；自然保护区；专属领域","definition_en":"to keep something in its original state, or to protect it from harm or change","core_image":"一排玻璃罐把夏天的果子封在糖水里，罐外的果园已经落光了叶子","scene":"Glass jars preserve the summer harvest long after the orchard is bare.","sceneCN":"这里 preserve 指「用糖或盐把食物处理过，使其长期不坏」（第 5 个义项：以糖渍、腌渍等方式保存食物）；句意为果园早已光秃，玻璃罐仍封着夏天的收成。图中可辨识物件：玻璃罐、糖汁、果块、贴着手写日期的标签。","pos":[{"tag":"vt.","zh":"保存；保护；维持；腌制（食物）"},{"tag":"n.","zh":"蜜饯；果酱（常用复数）；自然保护区；专属领域"}],"collocations":[{"phrase":"preserve food","zh":"保存食物"},{"phrase":"preserve a tradition","zh":"保留传统"},{"phrase":"preserve order","zh":"维持秩序"},{"phrase":"nature preserve","zh":"自然保护区"},{"phrase":"fruit preserves","zh":"果酱；蜜饯"},{"phrase":"preserve the peace","zh":"维护和平"},{"phrase":"a male preserve","zh":"男性的专属领域"}],"forms":[{"label":"三单（he/she/it）","form":"preserves"},{"label":"过去式","form":"preserved"},{"label":"过去分词","form":"preserved"},{"label":"现在分词","form":"preserving"},{"label":"名词（保存；保护）","form":"preservation"},{"label":"名词（防腐剂）","form":"preservative"}],"derivatives":[{"word":"preservation","pos":"n.","zh":"保存；保护；维护"},{"word":"preservative","pos":"n./adj.","zh":"防腐剂 / 防腐的"},{"word":"preserver","pos":"n.","zh":"保存者；救生用具"},{"word":"preservable","pos":"adj.","zh":"可保存的"},{"word":"preservationist","pos":"n.","zh":"文物保护主义者"}],"senses":[{"no":"01","title":"Keep something from decaying","titleCN":"使某物不腐坏、不变质","definition":"to treat or store something so that it does not decay","definitionCN":"通过处理或存放使某物不腐坏","example":"Salt and smoke preserve meat through the winter.","exampleCN":"盐与烟熏能让肉在整个冬天不坏。","why":"prae- 'before' plus servare 'keep' gives 'keep beforehand', and keeping food before it spoils is the oldest use of the word.","whyCN":"prae-「在前」加 servare「守住」得到「提前守住」，在食物变坏之前先护住，正是这个词最古老的用法。"},{"no":"02","title":"Protect a place from destruction","titleCN":"保护地点、建筑不遭破坏或改造","definition":"to protect a building, place or object from being destroyed or altered","definitionCN":"保护建筑、地点或物件不被摧毁或改动","example":"The trust preserves the medieval bridge exactly as it stands.","exampleCN":"该信托机构让这座中世纪桥原样留存。","why":"the object sense keeps the core meaning untouched: what is preserved is not repaired into something new but kept as it was.","whyCN":"物件义保持了核心含义：被 preserve 的不是被修成新东西，而是按原样留住。"},{"no":"03","title":"Keep a state or quality in being","titleCN":"维持某种状态或品质继续存在","definition":"to keep a condition, quality or state continuing","definitionCN":"使某种状况、品质或状态持续下去","example":"Officers preserved order while the crowd pushed forward.","exampleCN":"人群向前涌时，警员维持着秩序。","why":"order is something that disappears unless it is actively kept, so the verb is used for conditions that need guarding.","whyCN":"秩序若不主动守住就会消失，因此这个词也用于需要守护的状态。"},{"no":"04","title":"Keep something for later generations","titleCN":"为后世留存记录或实物","definition":"to keep records, objects or knowledge so that people in the future can still use them","definitionCN":"保存记录、实物或知识，使后人仍能使用","example":"Archivists preserve recordings of dialects that no longer have young speakers.","exampleCN":"档案人员保存那些已无年轻使用者的方言录音。","why":"here the word looks forward: what is kept now is kept for a time the keeper will never see.","whyCN":"这里这个词朝向未来：此刻守住的东西，是为守者永远看不到的时代而留。"},{"no":"05","title":"Prepare fruit or meat with sugar or brine","titleCN":"用糖渍、盐腌等方式加工食物","definition":"to prepare fruit or other food with sugar, salt or vinegar so that it keeps","definitionCN":"用糖、盐或醋处理水果等食物以延长保存期","example":"Glass jars preserve the summer harvest long after the orchard is bare.","exampleCN":"果园早已光秃，玻璃罐仍封着夏天的收成。","why":"the cooking sense specializes the general one: sugar and salt are the agents that do the guarding.","whyCN":"烹调用法是一般义的具体化：糖与盐就是执行「守住」的媒介。"},{"no":"06","title":"A protected area of land","titleCN":"自然保护区（名词义）","definition":"an area of land set aside so that its wildlife or landscape is protected","definitionCN":"为保护野生生物或景观而划出的土地","example":"The marsh is a private preserve where hunting is banned.","exampleCN":"这片沼泽是私人保护区，禁止狩猎。","why":"the noun turns the act into a place: land where protection happens all the time.","whyCN":"名词义把动作变成地点：持续进行保护的那片土地。"},{"no":"07","title":"Fruit jam in a jar","titleCN":"果酱、蜜饯（美式常用复数）","definition":"fruit cooked with sugar and stored in jars","definitionCN":"加糖熬煮后装罐的水果制品","example":"She opened a jar of strawberry preserves for the toast.","exampleCN":"她开了一罐草莓酱配吐司。","why":"the product noun is inherited straight from the verb, and American English prefers the plural for the jars on the shelf.","whyCN":"成品名词直接承自动词，美式英语更常用复数指架上的那些罐子。"},{"no":"08","title":"An activity reserved for one group","titleCN":"某一群体独占的领域或活动","definition":"an activity or area that one group keeps for itself and others are shut out of","definitionCN":"某一群体留给自己、他人不得进入的活动或领域","example":"Editing the paper is no longer a male preserve.","exampleCN":"编辑这家报纸不再是男性的专属领域。","why":"the idea of keeping something safe for oneself shades easily into keeping others out, which is how this social sense arose.","whyCN":"把某物为自己守住，很容易滑向把别人挡在外面，这个社会义就是这样产生的。"}],"etymology":{"intro":{"en":"Preserve comes through Old French from Latin praeservare, built on prae- 'before' and servare 'to keep'. It shares its root with conserve but not its prefix. Dates are approximate.","cn":"preserve 经古法语来自拉丁 praeservare，由 prae-「在前」与 servare「守住」构成。它与 conserve 共享词根，但前缀不同。年代均为约数。"},"items":[{"era":"LATIN PRAE-","en":"Prae- meant 'before, in front of', and in compounds it often adds the idea of doing something in advance.","cn":"prae- 意为「在前、在……之前」，在复合词中常添「预先」的意思。"},{"era":"LATIN PRAESERVARE","en":"Praeservare meant 'to keep or guard beforehand', a combination of the prefix with servare 'to keep safe'.","cn":"praeservare 意为「提前看守、预先保住」，是前缀与 servare「守住」的组合。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French preserver brought the word into English in the fourteenth century, and the spelling settled as preserve.","cn":"古法语 preserver 在 14 世纪把词带入英语，拼写最终固定为 preserve。"},{"era":"FOOD AND PLACES","en":"The food sense is recorded from the sixteenth century; the sense of land set aside for wildlife developed in the nineteenth, when the first large reserves were mapped.","cn":"食物义在 16 世纪有记录；为野生生物划出土地的意思在 19 世纪形成，当时最早的几处大型保护区被勘定。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest citation for the jam noun and for the nature-reserve sense is not precisely recorded, and the pre-Latin origin of servare remains unsettled.","cn":"来源不确定（首见年代）：果酱名词义与自然保护区义的最早书证没有确切记录；servare 在拉丁语之前的来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds verbs that share the Latin -serve stock and are easily mistaken; group two holds words that also mean keeping something safe but differ in emphasis.","cn":"第一组是共享拉丁 -serve 词干、容易认错的动词；第二组同样表示「保住」，但侧重点不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conserve","ipa":"/kənˈsɜːv/","tag":"same root, different prefix","definition":"Com- plus servare stresses keeping a resource from being used up; preserve stresses keeping something from changing or spoiling.","definitionCN":"com- 加 servare 强调不让资源被用尽；preserve 强调不让某物改变或变坏。"},{"word":"reserve","ipa":"/rɪˈzɜːv/","tag":"keep back for later","definition":"Re- 'back' plus servare: to set something aside instead of using it now, as in reserve a table.","definitionCN":"re-「向后」加 servare：把某物留到以后再用，如预订餐桌。"},{"word":"observe","ipa":"/əbˈzɜːv/","tag":"keep the eyes on","definition":"Ob- 'toward' plus servare: to watch, notice, or follow a rule; nothing is being stored.","definitionCN":"ob-「朝向」加 servare：观看、察觉或遵守规则；并不涉及储存。"},{"word":"deserve","ipa":"/dɪˈzɜːv/","tag":"not from servare","definition":"De- 'fully' plus servire 'to serve': to have earned something. Same look, different root.","definitionCN":"de-「完全」加 servire「服侍」：因服务而应得。形似而词根不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"protect","ipa":"/prəˈtekt/","tag":"shield from danger","definition":"To keep something safe from active harm; it says nothing about keeping it unchanged.","definitionCN":"使某物免受主动伤害；不涉及保持原样。"},{"word":"retain","ipa":"/rɪˈteɪn/","tag":"continue to hold","definition":"To keep something one already has, such as heat or a right, without the idea of guarding it.","definitionCN":"指继续保有已拥有之物，如热量或权利，不含守护之意。"},{"word":"conserve","ipa":"/kənˈsɜːv/","tag":"use without waste","definition":"To use a resource sparingly so that it lasts; its focus is quantity, not condition.","definitionCN":"节制使用资源使其持久；关注的是数量而非状态。"},{"word":"maintain","ipa":"/meɪnˈteɪn/","tag":"keep in repair","definition":"To keep something working by servicing it, as a machine; preserve does not imply repair.","definitionCN":"通过保养使某物继续运转，如机器；preserve 不含修理之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"prae- 'before' + servare 'keep': guard it before harm arrives.","cn":"prae-「在前」+ servare「守住」：在伤害到来之前先护住。"},{"en":"The family runs preserve, preservation, preservative, preserver, preservationist.","cn":"同族词包括 preserve、preservation、preservative、preserver、preservationist。"},{"en":"Fixed phrases mark the senses: preserve food, preserve order, nature preserve, fruit preserves.","cn":"固定搭配标出各义项：保存食物、维持秩序、自然保护区、果酱。"},{"en":"The root is shared with conserve and reserve, but the prefixes do the dividing.","cn":"词根与 conserve、reserve 共享，靠前缀区分。"},{"en":"American English says preserves for jam, British English often says jam.","cn":"美式英语用 preserves 指果酱，英式英语常用 jam。"}],"abstract":[{"en":"Picture a jar of summer standing on a shelf in January.","cn":"想象一月的架子上摆着一罐夏天。"},{"en":"Picture a bridge left exactly as it was, weeds and all.","cn":"想象一座桥连杂草都原样留着。"},{"en":"Picture a fence that keeps a meadow for animals and people out of it.","cn":"想象一道篱笆把草场留给动物，把人挡在外面。"}]},"examples":[{"en":"The museum preserves the letters in acid-free boxes.","cn":"博物馆把信件放在无酸盒中保存。"},{"en":"Freezing preserves the flavour far better than drying.","cn":"冷冻保存风味远胜于干燥。"},{"en":"The old quarter is preserved as a living neighbourhood, not a museum.","cn":"这片老城区是作为活着的社区被保护，而不是当成博物馆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pre（提前）+ serve（守住）」——在坏掉之前先护住 → 保存、保护、维持","word":"preserve"},"root":"拉丁 praeservare「提前守住」= prae-（在前）+ servare「看守、保存」；与 conserve 共享 servare 词根，靠前缀区分。英语 preserve。","sensesIntro":{"en":"Eight senses follow one movement: something is guarded before harm reaches it, and that guard is then applied to food, buildings, order, records, land, jam and finally to a social boundary.","cn":"八个义项沿同一个动作展开：在损害到达之前先护住某物，这道防护再依次用于食物、建筑、秩序、记录、土地、果酱，最后用于一条社会边界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a jar and a fence, both keeping something whole against time.","cn":"核心意象：一只罐与一道篱笆，都在对抗时间地把某物完整留住。"},"chain":["GUARD BEFORE","STOP DECAY","HOLD A STATE","KEEP FOR LATER","SUGAR OR SALT","SET-ASIDE LAND"],"branches":[{"senses":"S1 · S5","en":"STOP DECAY: sugar, salt and smoke are the guard, whether in a pot or a jar.","cn":"止住腐坏：糖、盐与烟就是那道防护，无论在锅里还是罐里。"},{"senses":"S2","en":"UNCHANGED OBJECT: a building is kept as it stands, not restored into something new.","cn":"原样的物件：建筑按现状留住，而不是修成新东西。"},{"senses":"S3 · S4","en":"STATE AND RECORD: order and archives both vanish unless someone keeps them.","cn":"状态与记录：秩序与档案若无人守护都会消失。"},{"senses":"S6 · S7","en":"SET ASIDE: the act becomes a place, and the product becomes a jar.","cn":"留出：动作变成一片地，成品变成一罐酱。"},{"senses":"S8","en":"KEPT FOR SOME: guarding something for oneself ends by shutting others out.","cn":"为某些人留住：为自己守住，最终把别人挡在外面。"}]},"affixes":{"intro":{"en":"Preserve is a Latin verb of prefix plus root; the same two parts build conserve, reserve and observe, so the family is best read morpheme by morpheme.","cn":"preserve 是由前缀加词根构成的拉丁动词；同样的两部分也构成 conserve、reserve 与 observe，因此这个词族最好按语素逐个读出。"},"latinIntro":{"en":"Latin prae- 'before' and servare 'to keep' give praeservare; English draws preserve, preservation, preservative and preserver from it.","cn":"拉丁 prae-「在前」与 servare「守住」构成 praeservare；英语由此得到 preserve、preservation、preservative 与 preserver。"},"items":[{"word":"prae-","structure":"prae- (Latin prefix, 'before, in front')","meaning":"before; in advance","meaningCN":"在前；预先","example":"The prefix marks action taken ahead of time.","exampleCN":"这个前缀标记提前采取的行动。"},{"word":"servare","structure":"servare (Latin verb, first conjugation)","meaning":"to keep, guard","meaningCN":"看守；保存","example":"The root supplies the idea of guarding.","exampleCN":"词根提供「守护」的意思。"},{"word":"preserve","structure":"prae- + servare","meaning":"to keep safe beforehand","meaningCN":"提前保住","example":"Salt preserves the fish before it spoils.","exampleCN":"盐在鱼变坏之前先把它保住。"},{"word":"preservation","structure":"preserve + -ation (action or result)","meaning":"the act of keeping safe","meaningCN":"保存（动作或结果）","example":"Cold storage aids the preservation of vaccines.","exampleCN":"冷藏有助于疫苗的保存。"},{"word":"preservative","structure":"preserve + -ative (agent)","meaning":"a substance that keeps food from spoiling","meaningCN":"防止食物变坏的添加物","example":"The label lists no preservatives.","exampleCN":"标签上未列出任何防腐剂。"},{"word":"preserver","structure":"preserve + -er (one who acts)","meaning":"a person or thing that preserves","meaningCN":"保存者；保存用具","example":"He was a preserver of local songs.","exampleCN":"他是当地歌谣的保存者。"},{"word":"preservable","structure":"preserve + -able (can be)","meaning":"able to be kept","meaningCN":"可保存的","example":"Dried grain is preservable for years.","exampleCN":"干燥的谷物可保存多年。"},{"word":"preservationist","structure":"preservation + -ist (person who does)","meaning":"an advocate of protecting old buildings or land","meaningCN":"主张保护老建筑或土地的人","example":"Preservationists fought the demolition.","exampleCN":"保护主义者反对这次拆除。"},{"word":"reserve","structure":"re- (back) + servare","meaning":"to keep back for later","meaningCN":"留到以后","example":"They reserved two rooms for the wedding.","exampleCN":"他们为婚礼留了两间房。"}],"latinEntries":[{"word":"servare","structure":"servare, servavi, servatum (verb, first conjugation)","meaning":"to keep, guard, preserve","meaningCN":"看守；守护；保存"},{"word":"praeservare","structure":"praeservare, praeservavi, praeservatum (verb, first conjugation)","meaning":"to keep beforehand, protect in advance","meaningCN":"预先保住"},{"word":"praeservatio","structure":"praeservatio, praeservationis (f., third declension)","meaning":"a guarding beforehand","meaningCN":"预先防护"},{"word":"conservare","structure":"conservare (verb, first conjugation)","meaning":"to keep safe, maintain","meaningCN":"保住；维持"}]}},{"word":"biodiversity loss","ipa_uk":"/ˌbaɪəʊdaɪˈvɜːsəti lɒs/","ipa_us":"/ˌbaɪoʊdaɪˈvɜːrsəti lɔːs/","definition_zh":"生物多样性丧失；生物多样性下降","definition_en":"the decline in the variety of living organisms, from genes and species to whole ecosystems","core_image":"一棵大树上原本挂满不同形状的叶子，如今叶子一片片掉落，枝头露出空白","scene":"Scientists warn that biodiversity loss is accelerating as forests are cleared.","sceneCN":"这里 biodiversity loss 指「生物多样性整体下降」（第 1 个义项：一个地区或全球范围内生物种类与差异性的减少）；句意为科学家警告，随着森林被砍伐，生物多样性丧失正在加速。图中可辨识物件：逐渐空掉的树冠、落下的不同形状叶片、被切开的林地边缘。","pos":[{"tag":"n.","zh":"生物多样性丧失（不可数；指局部多次事件时偶用复数 biodiversity losses）"}],"collocations":[{"phrase":"global biodiversity loss","zh":"全球生物多样性丧失"},{"phrase":"biodiversity loss rate","zh":"生物多样性丧失速率"},{"phrase":"halt biodiversity loss","zh":"遏止生物多样性丧失"},{"phrase":"biodiversity loss and climate change","zh":"生物多样性丧失与气候变化"},{"phrase":"driver of biodiversity loss","zh":"生物多样性丧失的驱动因素"},{"phrase":"biodiversity loss hotspot","zh":"生物多样性丧失热点区"},{"phrase":"reverse biodiversity loss","zh":"扭转生物多样性丧失"}],"forms":[{"label":"复数（少见，指多次局部事件）","form":"biodiversity losses"},{"label":"相关名词","form":"biodiversity（生物多样性）"},{"label":"同义学术说法","form":"biological diversity loss（生物多样性丧失）"},{"label":"相关形容词","form":"diverse（多样的）"},{"label":"反义说法","form":"biodiversity gain（生物多样性增加）"}],"derivatives":[{"word":"biodiversity","pos":"n.","zh":"生物多样性"},{"word":"biological","pos":"adj.","zh":"生物的；生物学的"},{"word":"diversity","pos":"n.","zh":"多样性；差异"},{"word":"diverse","pos":"adj.","zh":"多样的；不同的"},{"word":"loss","pos":"n.","zh":"丧失；损失"},{"word":"lose","pos":"v.","zh":"失去；丧失"}],"senses":[{"no":"01","title":"The shrinking variety of life","titleCN":"生物多样性整体下降","definition":"the decrease in the variety of living organisms in a place or on the planet","definitionCN":"一个地区或全球范围内生物种类与差异性的减少","example":"Scientists warn that biodiversity loss is accelerating as forests are cleared.","exampleCN":"科学家警告，随着森林被砍伐，生物多样性丧失正在加速。","why":"biodiversity names the variety itself, and loss names its going away, so the phrase reads literally as variety slipping out of existence.","whyCN":"biodiversity 指多样性本身，loss 指它消失，因此这个短语字面上就是「多样性正在消失」。"},{"no":"02","title":"Species richness falling","titleCN":"物种丰富度下降（可测量义）","definition":"the measured drop in the number of species present in a habitat","definitionCN":"某一生境中出现的物种数量可测的减少","example":"Repeated surveys recorded biodiversity loss of nearly a third.","exampleCN":"重复调查记录到近三分之一的生物多样性丧失。","why":"once ecologists began counting species, the phrase acquired a number, and this countable reading is the one used in field reports.","whyCN":"当生态学家开始统计物种数量，这个短语就有了数字，野外报告用的正是这一可测量的读法。"},{"no":"03","title":"Genetic variety eroded","titleCN":"遗传多样性流失","definition":"the loss of genetic variation within a species, which leaves it less able to adapt","definitionCN":"某一物种内部遗传变异减少，使其适应能力下降","example":"Isolated herds suffer biodiversity loss at the level of genes.","exampleCN":"隔离的兽群在基因层面遭受生物多样性丧失。","why":"variety exists below the species level too, so the phrase extends downward from species to alleles.","whyCN":"多样性也存在于物种层级之下，因此这个短语从物种向下延伸到等位基因。"},{"no":"04","title":"Habitats and ecosystems disappearing","titleCN":"生态系统与生境类型的减少","definition":"the loss of different kinds of habitat or ecosystem across a region","definitionCN":"一个区域内不同生境或生态系统类型的消失","example":"Draining the marshes meant biodiversity loss at the scale of whole habitats.","exampleCN":"排干沼泽意味着整个生境层面的生物多样性丧失。","why":"ecologists count variety at three scales, and the largest scale is the ecosystem, so the phrase covers vanished habitat types as well.","whyCN":"生态学家在三个尺度上统计多样性，最大尺度是生态系统，因此这个短语也涵盖消失的生境类型。"},{"no":"05","title":"A slide toward mass extinction","titleCN":"全球尺度：滑向大灭绝","definition":"the worldwide decline of life measured against the background rate of extinction","definitionCN":"以背景灭绝速率为参照衡量的全球生命衰退","example":"The living planet index is one way to track global biodiversity loss.","exampleCN":"地球生命力指数是追踪全球生物多样性丧失的一种方式。","why":"when losses outpace new species, the phrase stops describing a place and starts describing a trajectory for the whole planet.","whyCN":"当丧失速度超过新物种形成，这个短语就不再描述某地，而是描述整个行星的走向。"},{"no":"06","title":"The process driven by land conversion","titleCN":"由开垦与占用驱动的过程义","definition":"the process by which farming, logging and settlement reduce the variety of life","definitionCN":"农业、伐木与聚居使生命多样性下降的过程","example":"Agriculture is the leading driver of biodiversity loss worldwide.","exampleCN":"农业是全球生物多样性丧失的首要驱动因素。","why":"policy writing turns the state into an agent-driven process, so the phrase names what humans do as much as what disappears.","whyCN":"政策文本把状态写成由主体驱动的过程，因此这个短语既指消失的东西，也指人所做的事。"},{"no":"07","title":"A term fixed by treaty","titleCN":"条约与法律中的固定术语","definition":"the formal term used in treaties and statutes for the decline that states agree to stop","definitionCN":"条约与法规中用来指各国同意遏止的下降的正式术语","example":"The 1992 convention put biodiversity loss on the legal agenda.","exampleCN":"1992 年的公约把生物多样性丧失列入法律议程。","why":"a phrase becomes a term when a treaty needs a stable label for an obligation, and this is that label.","whyCN":"当条约需要给一项义务一个稳定的名称，短语就变成术语，而这就是那个名称。"},{"no":"08","title":"Any measurable loss of variety","titleCN":"抽象义：任何系统中多样性的减少","definition":"any measurable loss of variety in a system, not only in biology","definitionCN":"任何系统中可测量的多样性减少，不限于生物","example":"Consolidating suppliers caused biodiversity loss in the supply chain.","exampleCN":"供应商合并导致供应链出现「生物多样性」式流失。","why":"the phrase is borrowed whenever a system is valued for its variety, so it can describe suppliers, dialects or crops.","whyCN":"只要一个系统的价值在于其多样，这个短语就会被借用，因此可形容供应商、方言或作物。"}],"etymology":{"intro":{"en":"Biodiversity joins Greek bios 'life' to Latin diversus 'turned different ways', and was coined in the 1980s; loss is native English. The phrase itself is recent. Dates are approximate.","cn":"biodiversity 把希腊 bios「生命」与拉丁 diversus「转向不同方向」并置，于 1980 年代被造出；loss 是英语本族词。整个短语出现很晚。年代均为约数。"},"items":[{"era":"GREEK BIOS","en":"Greek bios meant 'life, way of life'. It entered modern scientific compounds through bio-, as in biology and biosphere.","cn":"希腊 bios 意为「生命、生活方式」，经 bio- 进入现代科学复合词，如 biology 与 biosphere。"},{"era":"LATIN DIVERSUS","en":"Diversus, the past participle of divertere 'to turn in different directions', gave English diverse and diversity.","cn":"diversus 是 divertere「转向不同方向」的过去分词，衍生英语 diverse 与 diversity。"},{"era":"COINAGE OF BIODIVERSITY","en":"The noun biodiversity is generally dated to the mid 1980s and is widely attributed to Walter G. Rosen; its spread followed a 1988 symposium volume edited by E. O. Wilson.","cn":"名词 biodiversity 一般认为是 1980 年代中期所造，广泛归功于 Walter G. Rosen；它的流行始于 1988 年由 E. O. Wilson 主编的会议文集。"},{"era":"OLD ENGLISH LOSS","en":"Loss descends from Old English los 'destruction, loss', related to the verb lose; it is native Germanic stock, not Latin.","cn":"loss 承自古英语 los「毁坏、丧失」，与动词 lose 相关，属本族日耳曼词，并非拉丁来源。"},{"era":"THE PHRASE","en":"Biodiversity loss became a standard collocation in the 1990s, once the 1992 Convention on Biological Diversity made the decline a reporting obligation.","cn":"1990 年代，1992 年《生物多样性公约》把这一下降列为报告义务之后，biodiversity loss 成为标准搭配。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the exact first printed use of the full phrase is not recorded, the coinage date of biodiversity has minor competing accounts, and the deeper origin of Latin diversus is a reconstruction.","cn":"来源不确定（首见年代）：完整短语的最早印刷记录不明；biodiversity 的造词年代存在小的分歧说法；拉丁 diversus 的更深来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds terms built on the same bio- or diversity stock that are easily swapped; group two holds the neighbouring ideas that measure or describe the same decline.","cn":"第一组是同出 bio- 或 diversity 词干、容易被替换的术语；第二组是测量或描述同一衰退的邻近概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"biodiversity","ipa":"/ˌbaɪəʊdaɪˈvɜːsəti/","tag":"the variety, not its loss","definition":"The variety itself. Biodiversity loss names what is happening to that variety, so the two cannot be swapped.","definitionCN":"指多样性本身；biodiversity loss 指这种多样性正在遭遇什么，两者不能互换。"},{"word":"biological diversity","ipa":"/ˌbaɪəˈlɒdʒɪkl daɪˈvɜːsəti/","tag":"older synonym","definition":"The longer academic wording for the same idea, older than biodiversity; it appears in treaty titles rather than in running text.","definitionCN":"同一概念的较长学术说法，早于 biodiversity；多出现在条约标题中，而不用于行文。"},{"word":"habitat loss","ipa":"/ˈhæbɪtæt lɒs/","tag":"cause, not result","definition":"The disappearance of habitat; it is one driver of biodiversity loss, not the loss of variety itself.","definitionCN":"指生境消失；它是生物多样性丧失的驱动因素之一，而非多样性本身的减少。"},{"word":"extinction","ipa":"/ɪkˈstɪŋkʃn/","tag":"one endpoint","definition":"The total disappearance of a species. Biodiversity loss is the broader decline that may end in extinctions.","definitionCN":"指一个物种彻底消失；生物多样性丧失是可能以灭绝收场的那一更大范围衰退。"}]},{"heading":"NEAR MEANING","entries":[{"word":"species decline","ipa":"/ˈspiːʃiːz dɪˈklaɪn/","tag":"counted per species","definition":"A drop in the numbers of one species; it does not by itself say anything about variety.","definitionCN":"指单一物种数量的下降；本身不涉及多样性。"},{"word":"ecosystem degradation","ipa":"/ˈiːkəʊsɪstəm ˌdeɡrəˈdeɪʃn/","tag":"quality falling","definition":"The weakening of an ecosystem's structure and function; biodiversity loss can follow from it.","definitionCN":"指生态系统结构与功能退化；生物多样性丧失可能随之而来。"},{"word":"defaunation","ipa":"/ˌdiːfɔːˈneɪʃn/","tag":"animal side only","definition":"The loss of animal populations specifically; it leaves plants and microbes out of the count.","definitionCN":"特指动物种群的丧失，不计植物与微生物。"},{"word":"biotic impoverishment","ipa":"/baɪˈɒtɪk ɪmˈpɒvərɪʃmənt/","tag":"a framing, not a measure","definition":"A rhetorical term for life becoming poorer and fewer; it carries judgement that biodiversity loss as a metric does not.","definitionCN":"指生命变得贫乏稀少的修辞说法；带有评价色彩，而作为指标的生物多样性丧失不带。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bio- 'life' + diversity 'turned apart': the many kinds of life.","cn":"bio-「生命」+ diversity「转向不同」：生命种类的繁多。"},{"en":"The family runs biodiversity, biological, diversity, diverse, loss, lose.","cn":"同族词包括 biodiversity、biological、diversity、diverse、loss、lose。"},{"en":"Fixed phrases mark the policy sense: halt biodiversity loss, reverse biodiversity loss, global biodiversity loss.","cn":"固定搭配标出政策义：遏止生物多样性丧失、扭转生物多样性丧失、全球生物多样性丧失。"},{"en":"The phrase scales three ways: genes, species, ecosystems.","cn":"这个短语有三个尺度：基因、物种、生态系统。"},{"en":"Its usual drivers are habitat loss, overexploitation, invasive species, pollution and climate change.","cn":"它的常见驱动因素是生境丧失、过度开发、入侵物种、污染与气候变化。"}],"abstract":[{"en":"Picture a tree losing its leaves one shape at a time until the branches are bare.","cn":"想象一棵树一种形状一种形状地掉叶子，直到枝条光秃。"},{"en":"Picture a choir where voices drop out until only one line is left singing.","cn":"想象一个合唱团，声部一个个退出，最后只剩一条声线在唱。"},{"en":"Picture a library whose shelves empty by category, not by accident.","cn":"想象一座图书馆，书架按类别被清空，而非偶然散失。"}]},"examples":[{"en":"Biodiversity loss weakens the services that ecosystems provide to farms.","cn":"生物多样性丧失削弱了生态系统为农田提供的服务。"},{"en":"The report links biodiversity loss to the spread of new diseases.","cn":"该报告把生物多样性丧失与新疾病的传播联系起来。"},{"en":"Restoring hedgerows can slow local biodiversity loss.","cn":"恢复树篱可以减缓局部的生物多样性丧失。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「bio（生命）+ diversity（多样）+ loss（丢失）」——生命种类的多样在流失 → 生物多样性丧失","word":"biodiversity loss"},"root":"希腊 bios「生命」（经 bio-）+ 拉丁 diversus「转向不同方向」（来自 divertere）+ 古英语 los「丧失」；biodiversity 为 1980 年代新造词，loss 为本族词。","sensesIntro":{"en":"Eight senses follow one decline: variety goes missing, and the phrase is then scaled down to genes, up to ecosystems, out to the planet, and finally borrowed for any system valued for its variety.","cn":"八个义项沿同一场衰退展开：多样性消失，这个短语再向下到基因、向上到生态系统、向外到整个行星，最后被借用于任何以多样为价值的系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tree whose leaves fall one shape at a time until the branches show gaps.","cn":"核心意象：一棵树的叶子一种形状一种形状地落，枝头露出空缺。"},"chain":["MANY KINDS","FEWER KINDS","COUNTED DROP","GENES ERODED","HABITATS GONE","GLOBAL DECLINE"],"branches":[{"senses":"S1","en":"GENERAL DECLINE: the plain reading, variety simply becoming less.","cn":"总体下降：最朴素的读法，多样性就是变少了。"},{"senses":"S2 · S3","en":"COUNTED AND GENETIC: the drop is measured in species first, then inside the gene pool.","cn":"可数层面与基因层面：先按物种计数，再深入基因库。"},{"senses":"S4 · S6","en":"HABITAT SCALE AND CAUSE: whole habitat types vanish, and land conversion is named as the driver.","cn":"生境尺度与成因：整个生境类型消失，并把土地开垦列为驱动因素。"},{"senses":"S5","en":"PLANETARY TRAJECTORY: local losses add up to a slide toward mass extinction.","cn":"行星走向：局部丧失累积成滑向大灭绝的趋势。"},{"senses":"S7 · S8","en":"TERM AND METAPHOR: treaty language fixes the label, and other systems borrow it.","cn":"术语与隐喻：条约语言固定了名称，其他系统则借用它。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek life-prefix to a Latin noun of difference, then adds a native English noun of losing; it is a compound of free forms, not a root with suffixes.","cn":"这个短语把希腊语的生命前缀接在拉丁语表示差异的名词上，再加一个英语本族表示丧失的名词；它是自由词形的复合，而非词根加后缀。"},"latinIntro":{"en":"Latin divertere gives diversity, diverse and divert; Greek bios supplies bio-, and Old English los supplies loss.","cn":"拉丁 divertere 衍生 diversity、diverse 与 divert；希腊 bios 提供 bio-，古英语 los 提供 loss。"},"items":[{"word":"bio-","structure":"Greek bios (life) used as a combining form","meaning":"life; living things","meaningCN":"生命；生物","example":"Biology and biosphere both begin with this element.","exampleCN":"biology 与 biosphere 都以这个成分开头。"},{"word":"diversity","structure":"Latin diversus + -ity (state of)","meaning":"the state of being varied","meaningCN":"多样的状态","example":"The reef's diversity supports a huge food web.","exampleCN":"珊瑚礁的多样性支撑起庞大的食物网。"},{"word":"diverse","structure":"Latin diversus (turned different ways)","meaning":"varied; of many kinds","meaningCN":"多样的；多种的","example":"The plot holds diverse grasses.","exampleCN":"这块地里有多种草。"},{"word":"divert","structure":"dis- (apart) + vertere (to turn)","meaning":"to turn aside","meaningCN":"使转向","example":"The channel diverts flood water.","exampleCN":"这条渠道把洪水引开。"},{"word":"biodiversity","structure":"bio- + diversity","meaning":"the variety of life","meaningCN":"生物多样性","example":"Biodiversity is highest near the equator.","exampleCN":"生物多样性在赤道附近最高。"},{"word":"biodiversity loss","structure":"biodiversity + loss","meaning":"the decline of that variety","meaningCN":"生物多样性的下降","example":"Biodiversity loss is accelerating as forests are cleared.","exampleCN":"随着森林被砍伐，生物多样性丧失正在加速。"},{"word":"loss","structure":"Old English los (destruction, loss)","meaning":"the fact of losing something","meaningCN":"丧失；损失","example":"The loss of the marsh took a decade.","exampleCN":"这片沼泽的消失用了十年。"},{"word":"lose","structure":"Old English losian (to be lost)","meaning":"to no longer have something","meaningCN":"失去；丧失","example":"The island lost half its birds.","exampleCN":"这座岛失去了一半的鸟类。"},{"word":"lossy","structure":"loss + -y (having the quality of)","meaning":"involving data loss","meaningCN":"有损的（数据压缩）","example":"A lossy format throws away some detail.","exampleCN":"有损格式会丢掉一部分细节。"}],"latinEntries":[{"word":"diversus","structure":"diversus, diversa, diversum (adjective)","meaning":"turned different ways; varied","meaningCN":"转向不同方向的；多样的"},{"word":"divertere","structure":"divertere, diverti, diversum (verb, third conjugation)","meaning":"to turn apart, separate","meaningCN":"使分开；使转向"},{"word":"vertere","structure":"vertere, verti, versum (verb, third conjugation)","meaning":"to turn","meaningCN":"转动"}]}},{"word":"extinction","ipa_uk":"/ɪkˈstɪŋkʃn/","ipa_us":"/ɪkˈstɪŋkʃən/","definition_zh":"灭绝；消亡；（权利、债务的）消灭；（星光）消光","definition_en":"the dying out of a species or the ending of something altogether","core_image":"一排灯原本一盏接一盏亮着，最后一盏也熄掉，整排陷入黑暗","scene":"The extinction of the passenger pigeon became a warning for conservationists.","sceneCN":"这里 extinction 指「一个物种彻底消失」（第 1 个义项：某物种的最后个体死亡，种群不再延续）；句意为旅鸽的灭绝成了自然保护者的警钟。图中可辨识物件：空荡的树枝、褪色的鸟形轮廓、标本柜、记录的日期。","pos":[{"tag":"n.","zh":"灭绝；消亡；消灭（可数，复数 extinctions）"}],"collocations":[{"phrase":"mass extinction","zh":"大灭绝"},{"phrase":"extinction event","zh":"灭绝事件"},{"phrase":"extinction rate","zh":"灭绝速率"},{"phrase":"brink of extinction","zh":"灭绝边缘"},{"phrase":"extinction risk","zh":"灭绝风险"},{"phrase":"drive to extinction","zh":"使……灭绝"},{"phrase":"local extinction","zh":"局部灭绝"}],"forms":[{"label":"复数","form":"extinctions"},{"label":"形容词（已灭绝的）","form":"extinct（灭绝的；熄灭的）"},{"label":"动词（使熄灭；消灭）","form":"extinguish（扑灭；消灭）"},{"label":"形容词（可消灭的）","form":"extinguishable（可扑灭的）"},{"label":"名词（灭火器）","form":"extinguisher（灭火器）"}],"derivatives":[{"word":"extinct","pos":"adj.","zh":"灭绝的；熄灭的"},{"word":"extinguish","pos":"v.","zh":"扑灭；消灭"},{"word":"extinguisher","pos":"n.","zh":"灭火器"},{"word":"extinctive","pos":"adj.","zh":"导致消灭的"},{"word":"extinguishment","pos":"n.","zh":"消灭；清偿"}],"senses":[{"no":"01","title":"A species dying out completely","titleCN":"物种完全灭绝","definition":"the death of the last members of a species, so that it no longer exists","definitionCN":"某物种最后个体死亡，从此不再存在","example":"The extinction of the passenger pigeon became a warning for conservationists.","exampleCN":"旅鸽的灭绝成了自然保护者的警钟。","why":"extinction is the noun of extinguishing: a flame goes out and nothing of it is left, which is exactly the image used for a species.","whyCN":"extinction 是「熄灭」的名词：火苗灭掉后什么也不剩，物种灭绝用的正是这个意象。"},{"no":"02","title":"The process of dying out","titleCN":"走向消亡的过程","definition":"the process by which the last members of a group decline and disappear","definitionCN":"某类群最后的成员逐渐减少并消失的过程","example":"The extinction of the dodo unfolded over less than a century.","exampleCN":"渡鸦的灭绝在不到一个世纪内展开。","why":"the noun names both the endpoint and the road to it, and the process reading is the one used in ecology.","whyCN":"这个名词既指终点也指通往终点的路，生态学用的是过程这一读法。"},{"no":"03","title":"Local extinction, or extirpation","titleCN":"局部灭绝：某地消失但别处尚有","definition":"the disappearance of a species from one region while it survives elsewhere","definitionCN":"某物种在一个地区消失，但在别处仍然存在","example":"Wolves faced local extinction in the lowlands but held on in the mountains.","exampleCN":"狼在低地遭遇局部灭绝，但在山区存续下来。","why":"because a species can vanish locally without vanishing globally, the noun takes a qualifier to mark the smaller scale.","whyCN":"因为物种可以在本地消失而不在全球消失，这个名词需要限定语来标记较小的尺度。"},{"no":"04","title":"A mass extinction","titleCN":"大灭绝：短时间内大量物种消失","definition":"an event in which a large share of all species disappears in a short span of geological time","definitionCN":"在地质时间的短促跨度内，大比例物种消失的事件","example":"The end-Permian mass extinction removed most marine families.","exampleCN":"二叠纪末大灭绝抹去了大多数海洋科。","why":"mass marks the scale, and extinction supplies the verb-derived idea of everything going out at once.","whyCN":"mass 标记规模，extinction 提供「一齐熄灭」的动词意象。"},{"no":"05","title":"A language or culture dying out","titleCN":"语言或文化的消亡","definition":"the disappearance of a language or way of life when its last speakers or practitioners die","definitionCN":"语言或生活方式因最后使用者的离世而消失","example":"Linguists race to record languages facing extinction.","exampleCN":"语言学家争相记录面临消亡的语言。","why":"the metaphor transfers the biological sense to anything whose carriers can die out, which is why languages are said to go extinct.","whyCN":"这一隐喻把生物学含义移到任何「承载者会消亡」的事物上，因此语言也被说成灭绝。"},{"no":"06","title":"Dimming of starlight by dust","titleCN":"天文学义：星际尘埃导致的星光消光","definition":"the absorption and scattering of starlight by interstellar matter","definitionCN":"星际物质对星光的吸收与散射","example":"Interstellar dust causes the extinction of light from distant stars.","exampleCN":"星际尘埃使远处恒星的光发生消光。","why":"astronomers borrowed the word because light is literally put out along the way, in the same sense as a flame.","whyCN":"天文学家借用这个词，因为光确实在途中被「熄灭」，与火苗同理。"},{"no":"07","title":"A right or debt extinguished","titleCN":"法律义：权利或债务的消灭","definition":"the ending of a legal right or obligation, as when a debt is paid off","definitionCN":"某项法律权利或义务的终止，如债务清偿后消灭","example":"Payment produced the extinction of the debt.","exampleCN":"付款使该债务归于消灭。","why":"law uses the word for anything that ceases to exist in the eyes of the law, keeping the core idea of being put out.","whyCN":"法律用它指在法律眼中不复存在的事物，保留了「被熄灭」的核心。"},{"no":"08","title":"A conditioned response dying out","titleCN":"行为心理学义：条件反应消退","definition":"the weakening and disappearance of a learned response when it is no longer reinforced","definitionCN":"学习得来的反应因不再被强化而减弱并消失","example":"Extinction of the conditioned response followed repeated non-reinforcement.","exampleCN":"在反复不予强化之后，条件反应出现了消退。","why":"psychology borrowed it for a response that fades away, treating the behaviour as the flame that goes out.","whyCN":"心理学借它指逐渐消失的反应，把行为当作被熄灭的火。"}],"etymology":{"intro":{"en":"Extinction comes from Latin exstinctio, built on exstinguere 'to quench, put out', from ex- 'out' and stinguere 'to prick, quench'. Dates are approximate.","cn":"extinction 来自拉丁 exstinctio，基于 exstinguere「熄灭、扑灭」，由 ex-「向外」与 stinguere「刺、熄灭」构成。年代均为约数。"},"items":[{"era":"LATIN STINGUERE","en":"Stinguere meant 'to prick or quench'. its deeper origin is uncertain; a link to a root meaning 'to stick, prick' is a reconstruction rather than a demonstrated fact.","cn":"stinguere 意为「刺、熄灭」。其更深来源不确定；把它连到表示「刺、扎」的词根只是重构，并非已证事实。"},{"era":"LATIN EXSTINGUERE","en":"Ex- 'out' plus stinguere gave exstinguere 'to put out, quench, destroy', used of fires, lights and, figuratively, of families.","cn":"ex-「向外」加 stinguere 得 exstinguere「扑灭、熄灭、毁掉」，用于火与光，也比喻家族断绝。"},{"era":"LATIN EXSTINCTIO","en":"The noun exstinctio named a quenching or a putting out; English took it as extinction in the fifteenth century.","cn":"名词 exstinctio 指熄灭或扑灭；英语于 15 世纪以 extinction 吸收。"},{"era":"BIOLOGICAL SENSE","en":"The sense of a species dying out is recorded from the nineteenth century, as naturalists assembled the fossil record of vanished forms.","cn":"物种灭绝的意思在 19 世纪有记录，当时博物学家整理已消失类型的化石记录。"},{"era":"MODERN USES","en":"The twentieth century added the astronomical sense of light extinction and the psychological sense of response extinction.","cn":"20 世纪又增添了天文学的「消光」义与心理学的「反应消退」义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates and deeper root): the exact first citation of the biological sense is not fixed, and the pre-Latin origin of stinguere remains unsettled.","cn":"来源不确定（首见年代与更深词根）：生物义的最早书证没有确定；stinguere 在拉丁语之前的来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds words built on the same stinguere stock that look alike; group two holds words for things ending, which differ in scope.","cn":"第一组是同出 stinguere 词干、形似的词；第二组表示「终结」，范围不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"extinct","ipa":"/ɪkˈstɪŋkt/","tag":"adjective, not the event","definition":"The state of having died out; extinction is the event or process that produces that state.","definitionCN":"指已灭绝的状态；extinction 是造成该状态的事件或过程。"},{"word":"extinguish","ipa":"/ɪkˈstɪŋɡwɪʃ/","tag":"the verb","definition":"To put out a fire or light, or to wipe out a right; the noun extinction is its result.","definitionCN":"扑灭火或光，或使权利消灭；名词 extinction 是其结果。"},{"word":"distinguish","ipa":"/dɪˈstɪŋɡwɪʃ/","tag":"same root, different prefix","definition":"Dis- 'apart' plus stinguere: to mark things apart, hence to tell them apart. It has nothing to do with dying out.","definitionCN":"dis-「分开」加 stinguere：把事物区分开，因此指辨别。与灭绝无关。"},{"word":"instinct","ipa":"/ˈɪnstɪŋkt/","tag":"pricked from within","definition":"In- 'in' plus stinguere, literally 'pricked on': an inborn drive. The same root, a very different path.","definitionCN":"in-「在内」加 stinguere，字面为「被内在刺动」：天生的驱力。同根而走向完全不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"extirpation","ipa":"/ˌekstəˈpeɪʃn/","tag":"local only","definition":"The removal of a species from one area while it survives elsewhere; extinction means the species is gone everywhere.","definitionCN":"指某物种在一地被清除而别处仍存；extinction 指该物种处处不见。"},{"word":"die-off","ipa":"/ˈdaɪɒf/","tag":"a sudden loss of numbers","definition":"A sharp local loss of many individuals; it need not end the species.","definitionCN":"指一地大量个体骤然死亡；未必导致物种终结。"},{"word":"elimination","ipa":"/ɪˌlɪmɪˈneɪʃn/","tag":"general removal","definition":"A broad word for removing something, from rivals to waste; it lacks the biological finality of extinction.","definitionCN":"泛指去除，从对手到废物；不含 extinction 那种生物学上的终结性。"},{"word":"disappearance","ipa":"/ˌdɪsəˈpɪərəns/","tag":"could be temporary","definition":"The fact of no longer being seen; a species may disappear from a survey and still return.","definitionCN":"指不再被看见；物种可能从调查中消失却仍然回来。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ex- 'out' + stinguere 'quench': the flame is put right out.","cn":"ex-「向外」+ stinguere「熄灭」：火被彻底弄灭。"},{"en":"The family runs extinction, extinct, extinguish, extinguisher, extinguishment.","cn":"同族词包括 extinction、extinct、extinguish、extinguisher、extinguishment。"},{"en":"Fixed phrases mark the scale: mass extinction, extinction event, brink of extinction.","cn":"固定搭配标出规模：大灭绝、灭绝事件、灭绝边缘。"},{"en":"The same root shows in distinguish and instinct, both with different prefixes.","cn":"同一词根出现在 distinguish 与 instinct 中，前缀都不同。"},{"en":"Ecology counts local extinction separately from global extinction.","cn":"生态学把局部灭绝与全球灭绝分开计数。"}],"abstract":[{"en":"Picture the last candle in a row going out, and the room going dark.","cn":"想象一排蜡烛的最后一支熄灭，房间陷入黑暗。"},{"en":"Picture a language with one elderly speaker left, and then none.","cn":"想象一门语言只剩一位老人会说，然后一个也不剩。"},{"en":"Picture a star whose light is eaten by dust before it reaches a telescope.","cn":"想象一颗星的光在到达望远镜前被尘埃吃掉。"}]},"examples":[{"en":"Habitat loss is the leading cause of extinction today.","cn":"生境丧失是当今灭绝的首要原因。"},{"en":"The extinction rate is now far above the fossil background.","cn":"当前的灭绝速率远高于化石记录的背景值。"},{"en":"The debt's extinction must be recorded in the ledger.","cn":"债务的消灭必须记入账簿。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ex（出）+ tinct（熄灭）」——火苗彻底熄掉，什么也不剩 → 灭绝、消亡","word":"extinction"},"root":"拉丁 exstinctio「熄灭」来自 exstinguere（ex-「向外」+ stinguere「刺、熄灭」）；stinguere 更深来源不确定，与 distinguish、instinct 同根不同前缀。英语 extinction。","sensesIntro":{"en":"Eight senses follow one image: something is put out, and the putting-out is then read as a species, a process, a local loss, a mass event, a language, a beam of starlight, a legal right and a learned response.","cn":"八个义项沿一个意象展开：某物被熄灭，这个「熄灭」再被读成物种、过程、局部丧失、大规模事件、语言、一束星光、法律权利与习得反应。"},"semanticMap":{"core":{"en":"CORE IMAGE: the last flame of a row is put out and the row goes dark.","cn":"核心意象：一排火的最后一支被弄灭，整排陷入黑暗。"},"chain":["PUT OUT","NOTHING LEFT","SPECIES GONE","LOCAL LOSS","MASS EVENT","BORROWED ENDINGS"],"branches":[{"senses":"S1 · S2","en":"SPECIES AND PROCESS: either the final state or the road that leads to it.","cn":"物种与过程：或指终局状态，或指通向终局的路。"},{"senses":"S3 · S4","en":"SCALE MARKERS: a loss can be local, or vast enough to count as mass.","cn":"尺度标记：丧失可以是局部的，也可以大到算作大灭绝。"},{"senses":"S5","en":"CARRIERS DIE OUT: languages and customs are treated as if they had last speakers.","cn":"承载者消亡：语言与习俗被当作有「最后使用者」的事物。"},{"senses":"S6","en":"LIGHT PUT OUT: dust quenches starlight along the path.","cn":"光被熄灭：尘埃在途中把星光弄灭。"},{"senses":"S7 · S8","en":"OTHER ENDINGS: rights and learned responses also cease to exist.","cn":"其他终结：权利与习得反应同样不复存在。"}]},"affixes":{"intro":{"en":"Extinction is a Latin noun of prefix plus root; ex- carries the sense of 'out', and the root also builds extinguish, distinguish and instinct.","cn":"extinction 是前缀加词根的拉丁名词；ex- 带「向外」的意思，同一词根还构成 extinguish、distinguish 与 instinct。"},"latinIntro":{"en":"Latin exstinguere gives extinction, extinct and extinguish; dis- and in- versions of the same root give distinguish and instinct.","cn":"拉丁 exstinguere 衍生 extinction、extinct 与 extinguish；同一词根的 dis- 与 in- 版本给出 distinguish 与 instinct。"},"items":[{"word":"ex-","structure":"ex- (Latin prefix, 'out of, away')","meaning":"out; away","meaningCN":"向外；离开","example":"The prefix marks the flame being driven out.","exampleCN":"前缀标记火被赶出去。"},{"word":"stinguere","structure":"stinguere (Latin verb, third conjugation)","meaning":"to prick, quench","meaningCN":"刺；熄灭","example":"The root supplies the quenching image.","exampleCN":"词根提供「熄灭」的意象。"},{"word":"extinction","structure":"exstinctio (Latin noun) -> extinction","meaning":"a putting out","meaningCN":"熄灭；消灭","example":"Mass extinction removed most marine families.","exampleCN":"大灭绝抹去了大多数海洋科。"},{"word":"extinct","structure":"exstinctus (past participle) -> extinct","meaning":"put out; died out","meaningCN":"已熄灭的；已灭绝的","example":"The volcano is extinct.","exampleCN":"这座火山已经熄灭。"},{"word":"extinguish","structure":"ex- + stinguere","meaning":"to put out","meaningCN":"扑灭","example":"Crews extinguished the fire within an hour.","exampleCN":"消防队在小时内扑灭了火。"},{"word":"extinguisher","structure":"extinguish + -er (agent)","meaning":"a device for putting out fires","meaningCN":"灭火器","example":"The extinguisher sits by the door.","exampleCN":"灭火器放在门边。"},{"word":"distinguish","structure":"dis- (apart) + stinguere","meaning":"to mark apart; to tell apart","meaningCN":"区分；辨别","example":"The stripes distinguish the two species.","exampleCN":"条纹把这两个物种区分开。"},{"word":"instinct","structure":"in- (in) + stinguere (prick)","meaning":"an inborn drive","meaningCN":"本能","example":"The bird finds the route by instinct.","exampleCN":"这种鸟靠本能找到路线。"},{"word":"extinctive","structure":"extinct + -ive (tending to)","meaning":"tending to put out or end","meaningCN":"导致消灭的","example":"The extinctive clause ended the easement.","exampleCN":"那条消灭条款终止了地役权。"}],"latinEntries":[{"word":"stinguere","structure":"stinguere, stinxi, stinctum (verb, third conjugation)","meaning":"to prick, quench, put out","meaningCN":"刺；熄灭"},{"word":"exstinguere","structure":"exstinguere, exstinxi, exstinctum (verb, third conjugation)","meaning":"to put out, destroy","meaningCN":"扑灭；毁掉"},{"word":"exstinctio","structure":"exstinctio, exstinctionis (f., third declension)","meaning":"a quenching, extinction","meaningCN":"熄灭；消灭"},{"word":"exstinctus","structure":"exstinctus, exstincta, exstinctum (past participle used as adjective)","meaning":"put out; extinguished","meaningCN":"已熄灭的；已消灭的"}]}},{"word":"extinct","ipa_uk":"/ɪkˈstɪŋkt/","ipa_us":"/ɪkˈstɪŋkt/","definition_zh":"灭绝的；绝种的；（火山）熄灭的；（语言、习俗）已消亡的","definition_en":"no longer existing as a living species, or no longer active, spoken or in use","core_image":"一座火山口安静地积着雨水，山坡长满树，看不出这里曾经喷发","scene":"The volcano has been extinct for ten thousand years, its crater now a lake.","sceneCN":"这里 extinct 指「火山已停止活动、不会再喷发」（第 2 个义项：火山进入休眠终止状态）；句意为这座火山已熄灭一万年，火山口如今成了湖。图中可辨识物件：积水火山口、覆满植被的山坡、岩层剖面、远处无烟的天际。","pos":[{"tag":"adj.","zh":"灭绝的；绝种的；（火山）熄灭的；（语言、习俗）已消亡的"}],"collocations":[{"phrase":"extinct species","zh":"已灭绝的物种"},{"phrase":"become extinct","zh":"走向灭绝"},{"phrase":"extinct volcano","zh":"死火山"},{"phrase":"extinct language","zh":"消亡的语言"},{"phrase":"go extinct","zh":"灭绝；绝迹"},{"phrase":"extinct in the wild","zh":"野外灭绝"}],"forms":[{"label":"比较级","form":"无（绝对形容词，通常不与 more、most 连用）"},{"label":"名词（灭绝）","form":"extinction"},{"label":"动词（扑灭；消灭）","form":"extinguish"},{"label":"动词短语（灭绝）","form":"go extinct（灭绝）"},{"label":"现在分词作定语（正在消失的）","form":"going extinct（正走向灭绝的）"}],"derivatives":[{"word":"extinction","pos":"n.","zh":"灭绝；消亡"},{"word":"extinguish","pos":"v.","zh":"扑灭；消灭"},{"word":"extinguisher","pos":"n.","zh":"灭火器"},{"word":"extinctive","pos":"adj.","zh":"导致消灭的"},{"word":"extinctively","pos":"adv.","zh":"以消灭的方式"}],"senses":[{"no":"01","title":"No longer living as a species","titleCN":"物种已灭绝","definition":"no longer existing as a living species anywhere on earth","definitionCN":"地球上不再有任何活着的个体","example":"The passenger pigeon is extinct, though its skins fill museum drawers.","exampleCN":"旅鸽已经灭绝，尽管它的皮毛还塞满博物馆的抽屉。","why":"extinct is the past participle of a verb meaning to put out, so a species described this way is one whose flame has gone out.","whyCN":"extinct 是「弄灭」这个动词的过去分词，因此被这样描述的物种，就是火已熄灭的那一个。"},{"no":"02","title":"A volcano that will not erupt again","titleCN":"死火山：不再活动的火山","definition":"no longer capable of erupting, said of a volcano whose magma supply is cut off","definitionCN":"指火山不再喷发，岩浆供给已切断","example":"The volcano has been extinct for ten thousand years.","exampleCN":"这座火山已熄灭一万年。","why":"the image of a quenched fire fits a volcano exactly: the fire is out and the mountain is only a shape.","whyCN":"「火被弄灭」的意象正合火山：火已熄，山只剩下一个形状。"},{"no":"03","title":"A language with no native speakers","titleCN":"已消亡的语言","definition":"no longer spoken as a mother tongue by any community","definitionCN":"不再有任何社群把它当作母语使用","example":"The language went extinct when its last fluent speaker died in 1987.","exampleCN":"最后一位流利使用者于 1987 年离世后，这门语言就消亡了。","why":"a language is kept alive by its speakers, so when the last one goes the word for a quenched flame applies.","whyCN":"语言靠使用者维持生命，最后一人离去，便可以用「火已熄灭」来形容。"},{"no":"04","title":"A family line that has died out","titleCN":"家族世系断绝","definition":"having no living descendants, said of a family or lineage","definitionCN":"指家族或世系已无在世后代","example":"The male line became extinct in the fifteenth century.","exampleCN":"这一支男系在 15 世纪断绝。","why":"Latin used the verb of a family whose last member died, and English kept that figurative use intact.","whyCN":"拉丁语就用这个动词指家族最后一人死去，英语完整保留了这一比喻用法。"},{"no":"05","title":"A fire or light put out","titleCN":"（书面语）火或光已熄灭","definition":"no longer burning or shining, used in literary and older prose","definitionCN":"不再燃烧或发光，用于文学与较早的书面语","example":"By midnight every lamp in the hall was extinct.","exampleCN":"到午夜，大厅里每一盏灯都熄了。","why":"this is the literal sense from which all the others were cut, and it survives in elevated writing.","whyCN":"这是所有其他义项所由切出的字面义，仍存活于较庄重的文字中。"},{"no":"06","title":"A custom no longer practised","titleCN":"习俗已不再实行","definition":"no longer existing in practice, said of a custom, craft or usage","definitionCN":"指习俗、手艺或用法已不再实际存在","example":"The craft of hand-setting type is nearly extinct.","exampleCN":"手工排字这门手艺已近乎消亡。","why":"a practice lives only while people perform it, so it goes out like a flame when the last practitioners stop.","whyCN":"一种做法只在人们实践时存在，最后一批人停手，它便像火一样熄灭。"},{"no":"07","title":"A right no longer in force","titleCN":"法律义：权利已消灭","definition":"no longer legally valid, said of a right, claim or obligation","definitionCN":"指权利、主张或义务在法律上已失效","example":"The easement is extinct once the dominant estate is sold.","exampleCN":"需役地被出售后，这项地役权即归消灭。","why":"law borrows the word for anything that has ceased to exist in law, keeping the sense of being put out.","whyCN":"法律借这个词指在法律上不复存在之物，保留「被弄灭」的意思。"},{"no":"08","title":"Gone from the wild, kept in captivity","titleCN":"野外灭绝：仅存于人工饲养","definition":"no longer surviving in the wild but still kept in zoos or collections","definitionCN":"野外已无存活个体，但动物园或收藏机构仍有饲养","example":"The antelope is extinct in the wild but breeds in captivity.","exampleCN":"这种羚羊在野外已灭绝，但在人工饲养下仍能繁殖。","why":"conservation needed a label in between living and lost, and the fixed phrase extinct in the wild supplies it.","whyCN":"保护工作需要「既未全活也未全失」的状态标签，固定说法「野外灭绝」正好补上这个位置。"}],"etymology":{"intro":{"en":"Extinct is the past participle of Latin exstinguere 'to put out, quench', used in English as an adjective from the sixteenth century. Dates are approximate.","cn":"extinct 是拉丁 exstinguere「熄灭、扑灭」的过去分词，自 16 世纪起在英语中作形容词使用。年代均为约数。"},"items":[{"era":"LATIN EXSTINGUERE","en":"Exstinguere combined ex- 'out' with stinguere 'to prick, quench'; its past participle exstinctus meant 'put out, quenched'.","cn":"exstinguere 把 ex-「向外」与 stinguere「刺、熄灭」结合，其过去分词 exstinctus 意为「已熄灭的」。"},{"era":"ADJECTIVE IN ENGLISH","en":"English adopted exstinctus as extinct in the sixteenth century, first of fires, lights and family lines.","cn":"英语在 16 世纪把 exstinctus 吸收为 extinct，最初用于火、光与家族世系。"},{"era":"VOLCANO SENSE","en":"The geological use for a volcano that will not erupt again is recorded from the seventeenth century, as naturalists classified mountains as active or quiet.","cn":"指不会再喷发的火山这一地质用法在 17 世纪有记录，当时博物学家把山分为活动与安静两类。"},{"era":"BIOLOGICAL SENSE","en":"The sense of a species having died out spread in the eighteenth and nineteenth centuries with the fossil record and with Cuvier's work on vanished animals.","cn":"物种已灭绝的意思在 18 至 19 世纪随化石记录与居维叶对消失动物的研究而扩散。"},{"era":"CONSERVATION PHRASE","en":"The fixed phrase extinct in the wild was adopted in the twentieth century to mark species surviving only in captivity.","cn":"固定说法「野外灭绝」于 20 世纪被采用，用来标记仅存于人工饲养的物种。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): early citations for the volcano and species senses are not precisely fixed, and the pre-Latin origin of stinguere remains unsettled.","cn":"来源不确定（首见年代）：火山义与物种义的最早书证没有精确定论；stinguere 在拉丁语之前的来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds words of the same stinguere stock that look almost identical; group two holds adjectives for things no longer present.","cn":"第一组是同出 stinguere 词干、外形几乎相同的词；第二组表示「已不存在」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"extinction","ipa":"/ɪkˈstɪŋkʃn/","tag":"the noun","definition":"The event or process of dying out; extinct describes the resulting state.","definitionCN":"指灭绝的事件或过程；extinct 描述由此形成的状态。"},{"word":"extinguish","ipa":"/ɪkˈstɪŋɡwɪʃ/","tag":"the verb","definition":"To put out a fire or wipe out something; extinct is what remains after the act.","definitionCN":"扑灭火或抹去某物；extinct 是行为之后留下的状态。"},{"word":"distinct","ipa":"/dɪˈstɪŋkt/","tag":"clearly separate","definition":"Dis- 'apart' plus stinguere: marked off, hence clear and separate. It has no trace of dying out.","definitionCN":"dis-「分开」加 stinguere：被划分开，因此指清楚、分明。毫无「消亡」之意。"},{"word":"instinct","ipa":"/ˈɪnstɪŋkt/","tag":"inborn drive","definition":"In- 'in' plus stinguere, 'pricked from within': the word names an inborn impulse, not an ending.","definitionCN":"in-「在内」加 stinguere，「被内在刺动」：指天生冲动，不指终结。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vanished","ipa":"/ˈvænɪʃt/","tag":"out of sight","definition":"Gone from view or existence, often used loosely; a vanished custom may return, an extinct species cannot.","definitionCN":"指从视野或存在中消失，用法较宽；消失的习俗可能回来，灭绝的物种不能。"},{"word":"defunct","ipa":"/dɪˈfʌŋkt/","tag":"no longer operating","definition":"Said of organizations, laws or machines that have stopped working; it is not used of species.","definitionCN":"用于停止运作的机构、法律或机器；不用于物种。"},{"word":"dormant","ipa":"/ˈdɔːmənt/","tag":"sleeping, not dead","definition":"Inactive but able to revive, as a dormant volcano or seed; extinct means there is no revival.","definitionCN":"指暂不活动但仍可能复活，如休眠火山或种子；extinct 指再无复活可能。"},{"word":"obsolete","ipa":"/əˈbsəliːt/","tag":"out of use","definition":"No longer used because something better replaced it, said of words or tools; it implies replacement, not death.","definitionCN":"因被更好的东西取代而不再使用，用于词或工具；含「被取代」而非「死亡」之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ex- 'out' + stinguere 'quench': the flame has been put out.","cn":"ex-「向外」+ stinguere「熄灭」：火已被弄灭。"},{"en":"The family runs extinct, extinction, extinguish, extinguisher, extinctive.","cn":"同族词包括 extinct、extinction、extinguish、extinguisher、extinctive。"},{"en":"Fixed phrases mark the senses: extinct species, extinct volcano, extinct language, extinct in the wild.","cn":"固定搭配标出各义项：已灭绝物种、死火山、消亡语言、野外灭绝。"},{"en":"It is an absolute adjective, so grammar prefers go extinct to more extinct.","cn":"它是绝对形容词，因此语法上更常说 go extinct 而不是 more extinct。"},{"en":"The same root appears in distinct and instinct with different prefixes.","cn":"同一词根出现在 distinct 与 instinct 中，前缀不同。"}],"abstract":[{"en":"Picture a crater full of rainwater where fire used to be.","cn":"想象一个积满雨水的火山口，那里曾经是火。"},{"en":"Picture a museum drawer of skins that are the last of their kind.","cn":"想象博物馆抽屉里的皮毛，是它们那类最后的遗存。"},{"en":"Picture a lamp with no oil left, however polished the brass.","cn":"想象一盏没有油可点的灯，黄铜再亮也无用。"}]},"examples":[{"en":"The species was declared extinct after three years without a sighting.","cn":"连续三年没有观测记录后，该物种被宣布灭绝。"},{"en":"An extinct volcano can still host hot springs.","cn":"死火山仍可能有温泉。"},{"en":"The dialect is not extinct yet, but no children speak it.","cn":"这种方言尚未消亡，但已没有孩子会说。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ex（出）+ tinct（熄灭）」——火灭得干干净净 → 灭绝的、熄灭的","word":"extinct"},"root":"拉丁 exstinctus（exstinguere「熄灭」的过去分词）= ex-「向外」+ stinguere「刺、熄灭」；英语 extinct。与 extinction、extinguish 同族，与 distinct、instinct 同根不同前缀。","sensesIntro":{"en":"Eight senses follow one state: a fire is out, and that outness is then read as a species, a volcano, a language, a lineage, a lamp, a craft, a legal right and a species that survives only in cages.","cn":"八个义项沿同一个状态展开：火已灭，这个「灭」再被读成物种、火山、语言、世系、灯、手艺、法律权利，以及只活在笼中的物种。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crater holding rainwater where fire once was.","cn":"核心意象：火山口积着雨水，那里曾经是火。"},"chain":["FIRE OUT","NO LONGER ACTIVE","SPECIES GONE","LINE ENDED","LANGUAGE SILENT","PRACTICE STOPPED"],"branches":[{"senses":"S1 · S4","en":"LIVING LINE ENDED: species and family lines both reach a last member.","cn":"活的世系终止：物种与家族都走到最后一位成员。"},{"senses":"S2","en":"MOUNTAIN QUIET: a quenched fire explains an unerupting volcano.","cn":"山的安静：熄灭的火解释了不再喷发的火山。"},{"senses":"S3 · S6","en":"CARRIERS SILENT: a language and a craft last only while someone performs them.","cn":"承载者沉默：语言与手艺只在有人实践时存在。"},{"senses":"S5","en":"LITERAL LAMP: the oldest sense, kept for elevated prose.","cn":"字面的灯：最古老的义项，保留在庄重文字里。"},{"senses":"S7 · S8","en":"LEGAL AND CAPTIVE ENDS: a right can be extinguished, and a species can be extinct in the wild only.","cn":"法律与圈养两端：权利可被消灭，物种也可只在野外灭绝。"}]},"affixes":{"intro":{"en":"Extinct is a Latin participle used as an adjective; ex- supplies 'out' and stinguere supplies the quenching, both visible across its word family.","cn":"extinct 是作形容词用的拉丁分词；ex- 提供「向外」，stinguere 提供「熄灭」，两者在整个词族中都看得见。"},"latinIntro":{"en":"Exstinguere yields extinct, extinction and extinguish; the same root with other prefixes yields distinct, instinct and distinguish.","cn":"exstinguere 衍生 extinct、extinction 与 extinguish；同一词根换前缀则得 distinct、instinct 与 distinguish。"},"items":[{"word":"ex-","structure":"ex- (Latin prefix, 'out, away')","meaning":"out; away","meaningCN":"向外；离开","example":"The prefix marks the driving out of the flame.","exampleCN":"前缀标记火被驱出。"},{"word":"stinguere","structure":"stinguere (Latin verb, third conjugation)","meaning":"to prick, quench","meaningCN":"刺；熄灭","example":"The root carries the quenching image.","exampleCN":"词根带着熄灭的意象。"},{"word":"extinct","structure":"exstinctus (past participle) -> extinct","meaning":"put out; died out","meaningCN":"已熄灭的；已灭绝的","example":"The volcano is extinct.","exampleCN":"这座火山已熄灭。"},{"word":"extinction","structure":"extinct + -ion (state or event)","meaning":"the state or event of dying out","meaningCN":"灭绝的状态或事件","example":"Extinction followed the draining of the marsh.","exampleCN":"沼泽排干之后出现了灭绝。"},{"word":"extinguish","structure":"ex- + stinguere (verb form)","meaning":"to put out","meaningCN":"扑灭","example":"They extinguished the last embers.","exampleCN":"他们扑灭了最后的余烬。"},{"word":"extinctive","structure":"extinct + -ive (tending to)","meaning":"tending to end or abolish","meaningCN":"导致终结的","example":"An extinctive condition ended the licence.","exampleCN":"一条消灭条件终止了许可。"},{"word":"distinct","structure":"dis- (apart) + stinguere","meaning":"clearly separated","meaningCN":"分明的；截然不同的","example":"Two distinct calls mark the two species.","exampleCN":"两种不同的鸣声标记着两个物种。"},{"word":"instinct","structure":"in- (in) + stinguere (prick)","meaning":"an inborn drive","meaningCN":"本能","example":"Salmon return by instinct.","exampleCN":"鲑鱼靠本能洄游。"},{"word":"extinguisher","structure":"extinguish + -er (agent)","meaning":"a fire-suppressing device","meaningCN":"灭火器","example":"The extinguisher was empty.","exampleCN":"灭火器是空的。"}],"latinEntries":[{"word":"stinguere","structure":"stinguere, stinxi, stinctum (verb, third conjugation)","meaning":"to prick, quench","meaningCN":"刺；熄灭"},{"word":"exstinguere","structure":"exstinguere, exstinxi, exstinctum (verb, third conjugation)","meaning":"to put out, destroy","meaningCN":"扑灭；毁掉"},{"word":"exstinctus","structure":"exstinctus, exstincta, exstinctum (past participle)","meaning":"put out; quenched","meaningCN":"已熄灭的"},{"word":"exstinctio","structure":"exstinctio, exstinctionis (f., third declension)","meaning":"a quenching","meaningCN":"熄灭；消灭"}]}},{"word":"endangered","ipa_uk":"/ɪnˈdeɪndʒəd/","ipa_us":"/ɪnˈdeɪndʒərd/","definition_zh":"濒危的；有灭绝危险的；受到威胁的","definition_en":"in danger of dying out completely, especially of a species whose numbers have fallen dangerously low","core_image":"一只动物站在不断缩小的一块浮冰上，四周的水面一步步逼近","scene":"The last wild population is endangered by poaching and habitat loss.","sceneCN":"这里 endangered 指「有灭绝危险的」（第 1 个义项：种群数量降到危险低位，随时可能彻底消失）；句意为最后的野生种群正受盗猎与生境丧失的威胁。图中可辨识物件：缩小的浮冰、逼近的水面、远处的枪影、被砍倒的树线。","pos":[{"tag":"adj.","zh":"濒危的；有灭绝危险的；受到威胁的"},{"tag":"v.","zh":"endanger 的过去式与过去分词：使……陷入危险"}],"collocations":[{"phrase":"endangered species","zh":"濒危物种"},{"phrase":"critically endangered","zh":"极危的"},{"phrase":"endangered language","zh":"濒危语言"},{"phrase":"endangered habitat","zh":"受威胁的生境"},{"phrase":"legally endangered","zh":"被法律列为濒危的"},{"phrase":"endangered by","zh":"受到……的威胁"},{"phrase":"endangered population","zh":"濒危种群"}],"forms":[{"label":"比较级","form":"more endangered（更濒危的）"},{"label":"最高级","form":"most endangered（最濒危的）"},{"label":"原形动词","form":"endanger（使陷入危险）"},{"label":"名词（濒危状态）","form":"endangerment（濒危；危害）"},{"label":"三单","form":"endangers"}],"derivatives":[{"word":"endanger","pos":"v.","zh":"使……陷入危险；危及"},{"word":"endangerment","pos":"n.","zh":"濒危状态；危害"},{"word":"danger","pos":"n.","zh":"危险"},{"word":"dangerous","pos":"adj.","zh":"危险的"},{"word":"endangered","pos":"adj.","zh":"濒危的"}],"senses":[{"no":"01","title":"A species at risk of dying out","titleCN":"物种有灭绝危险","definition":"having so few individuals left that the species may soon disappear","definitionCN":"剩余个体太少，该物种可能很快消失","example":"The last wild population is endangered by poaching and habitat loss.","exampleCN":"最后的野生种群正受盗猎与生境丧失的威胁。","why":"endanger means to put into danger, and the adjective simply says the danger is now upon the species.","whyCN":"endanger 意为「使陷入危险」，形容词就是说明危险已经落到该物种头上。"},{"no":"02","title":"A legal listing status","titleCN":"法律上的濒危名录身份","definition":"formally listed by a government as a species in danger of extinction, with protection attached","definitionCN":"被政府正式列入有灭绝危险的物种名录，并附带保护措施","example":"The fish was declared endangered under the act in 1985.","exampleCN":"这种鱼在 1985 年依据该法被列为濒危。","why":"a statute cannot protect a vague condition, so the adjective became a formal status that a government can list, fund and enforce.","whyCN":"法律无法保护一种模糊的状况，因此这个形容词变成政府可以列名、拨款与执行的正式身份。"},{"no":"03","title":"The middle rung of a ranking","titleCN":"受威胁等级中的一档（低于极危）","definition":"the category between vulnerable and critically endangered on a conservation ranking","definitionCN":"保护等级排序中介于易危与极危之间的一档","example":"The species moved from vulnerable to endangered last year.","exampleCN":"该物种去年从易危升为濒危。","why":"once conservationists ranked risk, the word became a rung on the ladder rather than a vague alarm.","whyCN":"当保护工作者给风险排序，这个词就成了阶梯上的一档，而不再是模糊的警报。"},{"no":"04","title":"A habitat or ecosystem under threat","titleCN":"受威胁的生境或生态系统","definition":"said of a habitat or ecosystem whose existence is threatened","definitionCN":"指生存受到威胁的生境或生态系统","example":"The endangered wetland supports three rare orchids.","exampleCN":"这片受威胁的湿地养着三种稀有兰花。","why":"a place can be at risk just as a species can, so the adjective attaches to the ground itself when the ground may disappear.","whyCN":"地点也像物种一样会陷入危险，因此当地面本身可能消失时，这个形容词就落到土地上。"},{"no":"05","title":"A language losing its speakers","titleCN":"使用人数锐减、可能消亡的语言","definition":"said of a language whose speakers are falling and may stop using it altogether","definitionCN":"指使用者不断减少、可能彻底停用的语言","example":"The endangered dialect survives in two villages.","exampleCN":"这门濒危方言只在两个村子里留存。","why":"a language is carried by speakers, so the same adjective fits when the number of carriers falls sharply.","whyCN":"语言由使用者承载，因此当承载者数量骤减时，同一个形容词同样适用。"},{"no":"06","title":"A craft or tradition at risk","titleCN":"濒临失传的手艺或传统","definition":"said of a practice that few people still perform and that may vanish","definitionCN":"指已少有人实践、可能消失的做法","example":"Copper engraving is an endangered craft in this region.","exampleCN":"铜版雕刻在这一带是濒临失传的手艺。","why":"a craft exists only while hands practise it, so it can be endangered in exactly the way a species is.","whyCN":"手艺只在有人动手实践时存在，因此它可以像物种一样濒危。"},{"no":"07","title":"Simply in danger","titleCN":"泛指处于危险之中（旧义）","definition":"in danger generally, of a person, reputation or plan, as in older usage","definitionCN":"泛指人或名誉、计划处于危险，属较早用法","example":"His reputation, endangered by the rumour, needed a public answer.","exampleCN":"受流言所危的名誉需要一次公开回应。","why":"the general sense came first, and the species sense is the specialization that took over in the twentieth century.","whyCN":"一般义先出现，物种义是 20 世纪接管主导的特殊化用法。"},{"no":"08","title":"Threatened by a named agent","titleCN":"由某个具体威胁因子所危及","definition":"put at risk by a stated cause, which the passive construction usually names","definitionCN":"由句中明说的原因置于险境，被动结构通常点出该原因","example":"The colony is endangered by rising sea temperatures.","exampleCN":"该群落正受海温上升的威胁。","why":"the verb-like frame endangered by keeps the original verbal force visible inside the adjective.","whyCN":"endangered by 这一结构让原本的动词力量在形容词里仍然可见。"}],"etymology":{"intro":{"en":"Endangered is en- plus danger plus -ed. Danger comes through Old French from Vulgar Latin dominiarium 'power of a lord', from dominus 'lord'. Dates are approximate.","cn":"endangered 由 en- 加 danger 再加 -ed 构成。danger 经古法语来自通俗拉丁 dominiarium「领主的权力」，源自 dominus「领主」。年代均为约数。"},"items":[{"era":"VULGAR LATIN DOMINIARIUM","en":"Dominus 'lord, master' produced Vulgar Latin dominiarium 'power to command', which Old French shortened to dangier.","cn":"dominus「领主、主人」产生通俗拉丁 dominiarium「支配之权」，古法语把它压缩为 dangier。"},{"era":"OLD FRENCH DANGIER","en":"In Old French dangier meant 'dominion, power over someone', and only later 'risk, peril'; English took the later sense.","cn":"古法语 dangier 意为「支配、对某人的权力」，较晚才转为「风险、危险」；英语吸收的是较晚的义项。"},{"era":"ENGLISH DANGER","en":"English danger is recorded from the thirteenth century, and by the fourteenth it meant peril rather than power.","cn":"英语 danger 在 13 世纪有记录，到 14 世纪已指危险而非权力。"},{"era":"ENDANGER AND ENDANGERED","en":"The verb endanger is recorded in the fifteenth century and the adjective endangered in the seventeenth, both meaning 'put or be in peril'.","cn":"动词 endanger 在 15 世纪有记录，形容词 endangered 在 17 世纪，二者都表示「使／处于危险中」。"},{"era":"SPECIES SENSE","en":"The conservation sense dates from the mid twentieth century; the United States passed an Endangered Species Preservation Act in 1966 and a stronger Endangered Species Act in 1973.","cn":"保护义始于 20 世纪中期；美国 1966 年通过《濒危物种保存法》，1973 年通过更强的《濒危物种法》。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest citation for endangered applied to a species is not precisely recorded, and the shift of dangier from 'power' to 'peril' has competing explanations.","cn":"来源不确定（首见年代）：endangered 用于物种的最早书证没有确切记录；dangier 从「权力」转向「危险」的过程存在多种解释。"}]},"similar":{"note":{"en":"Group one holds forms of the same danger family that are easily confused; group two holds the risk labels that conservation uses in a fixed order.","cn":"第一组是同出 danger 词族、容易混淆的形式；第二组是保护工作按固定次序使用的风险等级标签。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dangerous","ipa":"/ˈdeɪndʒərəs/","tag":"causes danger","definition":"Describes something that can harm others, such as a dangerous road. Endangered describes something that may be harmed.","definitionCN":"描述会伤害他者的事物，如危险的道路；endangered 描述可能受到伤害的对象。"},{"word":"endanger","ipa":"/ɪnˈdeɪndʒə/","tag":"the verb","definition":"To put something at risk; endangered is the resulting state, and endangered by names the agent.","definitionCN":"使某物陷入危险；endangered 是结果状态，endangered by 点出施害者。"},{"word":"endangerment","ipa":"/ɪnˈdeɪndʒəmənt/","tag":"the noun","definition":"The state of being at risk, or the act of putting something at risk; it is used in law and in language studies.","definitionCN":"指处于风险的状态或使之陷入风险的行为；用于法律与语言研究。"},{"word":"danger","ipa":"/ˈdeɪndʒə/","tag":"the base noun","definition":"The peril itself; endangered says that this peril has attached to a particular species or thing.","definitionCN":"指危险本身；endangered 说明这种危险已落到某个物种或事物上。"}]},{"heading":"NEAR MEANING","entries":[{"word":"threatened","ipa":"/ˈθretənd/","tag":"one rung lower in law","definition":"In United States law, a species likely to become endangered soon; it sits below endangered in severity.","definitionCN":"在美国法律中指很可能在近期变为濒危的物种；严重程度低于 endangered。"},{"word":"vulnerable","ipa":"/ˈvʌlnərəbl/","tag":"exposed, not yet doomed","definition":"Likely to be harmed because of weakness or exposure; in conservation it is a milder category than endangered.","definitionCN":"因脆弱或暴露而容易受损；在保护等级中比 endangered 轻。"},{"word":"imperilled","ipa":"/ɪmˈperəld/","tag":"in peril","definition":"A formal synonym for put in danger; it appears in conservation writing but carries no legal listing.","definitionCN":"「陷入危险」的正式同义词；见于保护写作，但不带法律名录含义。"},{"word":"at risk","ipa":"/æt rɪsk/","tag":"plain phrase","definition":"The everyday phrase for exposure to harm; endangered is its technical, species-specific counterpart.","definitionCN":"指暴露于伤害的日常说法；endangered 是它在物种语境中的技术化对应词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"en- 'in' + danger + -ed: danger has been put into the species.","cn":"en-「进入」+ danger + -ed：危险已被放进这个物种身上。"},{"en":"The family runs endanger, endangered, endangerment, danger, dangerous.","cn":"同族词包括 endanger、endangered、endangerment、danger、dangerous。"},{"en":"Fixed phrases mark the senses: endangered species, critically endangered, endangered language.","cn":"固定搭配标出各义项：濒危物种、极危、濒危语言。"},{"en":"The conservation ladder runs least concern, near threatened, vulnerable, endangered, critically endangered.","cn":"保护等级阶梯依次为无危、近危、易危、濒危、极危。"},{"en":"Danger itself came from a word for a lord's power, not from a word for harm.","cn":"danger 本身来自表示领主权力的词，而非表示伤害的词。"}],"abstract":[{"en":"Picture an animal on ice that melts a little every day.","cn":"想象一只动物站在每天缩小一点的冰上。"},{"en":"Picture a language with two old speakers and no children listening.","cn":"想象一门语言只剩两位老人会说，没有孩子在听。"},{"en":"Picture a craft kept alive by one pair of hands.","cn":"想象一门手艺只靠一双手维持。"}]},"examples":[{"en":"The orchid is endangered because its pollinator has vanished.","cn":"这种兰花因传粉者消失而濒危。"},{"en":"Endangered species receive legal protection on both land and water.","cn":"濒危物种在陆地与水域都受到法律保护。"},{"en":"The endangered language is taught in one village school.","cn":"这门濒危语言在一所村校里教授。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「en（放进）+ danger（危险）+ ed」——危险已经落在它头上 → 濒危的、受威胁的","word":"endangered"},"root":"en-（使进入）+ danger（危险，经古法语 dangier 来自通俗拉丁 dominiarium「领主之权」，源自 dominus「领主」）+ -ed。英语 endangered。","sensesIntro":{"en":"Eight senses follow one situation: danger is placed on something, and that situation is then read as a species, a legal listing, a rank, a habitat, a language, a craft, a reputation and a named cause.","cn":"八个义项沿同一个处境展开：危险被放到某物身上，这个处境再被读成物种、法律名录、等级、生境、语言、手艺、名誉与一个被点名的成因。"},"semanticMap":{"core":{"en":"CORE IMAGE: an animal on a shrinking floe while the water closes in.","cn":"核心意象：动物站在缩小的浮冰上，水面步步逼近。"},"chain":["DANGER ENTERS","NUMBERS FALL","LISTED BY LAW","RANKED BY RISK","HABITAT AT RISK","CARRIERS FADE"],"branches":[{"senses":"S1 · S7","en":"DANGER ATTACHED: from a species to an old reputation, the peril is real and present.","cn":"危险附着：从物种到旧式名誉，危险都真实而当下。"},{"senses":"S2 · S3","en":"INSTITUTIONAL LABELS: law lists it, and rankings place it on a ladder.","cn":"制度标签：法律把它列名，等级把它放上阶梯。"},{"senses":"S4","en":"PLACE AT RISK: a habitat can be endangered as well as its inhabitants.","cn":"地点受危：生境本身也会濒危，不只有其中的生物。"},{"senses":"S5 · S6","en":"PRACTICE FADING: languages and crafts lose their carriers.","cn":"实践式微：语言与手艺失去承载者。"},{"senses":"S8","en":"NAMED CAUSE: the passive frame asks who or what is doing the endangering.","cn":"点明成因：被动结构追问是谁或什么在施加危险。"}]},"affixes":{"intro":{"en":"Endangered is a native English construction of prefix plus noun plus suffix, built on a French borrowing rather than on a Latin root.","cn":"endangered 是英语本族的前缀加名词再加后缀的构造，基底是法语借词，而非拉丁词根。"},"latinIntro":{"en":"The Latin base is dominus 'lord', which gives dominiarium, then Old French dangier, then English danger; en- and -ed are English affixes.","cn":"其拉丁基底是 dominus「领主」，由此得 dominiarium，再经古法语 dangier 得英语 danger；en- 与 -ed 是英语词缀。"},"items":[{"word":"en-","structure":"en- (English prefix, 'in, into', from Latin in-)","meaning":"into; put into a state","meaningCN":"进入；使处于某状态","example":"The prefix turns a noun into a verb of putting.","exampleCN":"这个前缀把名词变成「使进入」的动词。"},{"word":"danger","structure":"Old French dangier, from Vulgar Latin dominiarium","meaning":"peril; risk","meaningCN":"危险；风险","example":"The danger passed by morning.","exampleCN":"危险到早上就过去了。"},{"word":"endanger","structure":"en- + danger","meaning":"to put at risk","meaningCN":"使陷入危险","example":"Dams endanger the fish runs.","exampleCN":"水坝危及鱼的洄游。"},{"word":"endangered","structure":"endanger + -ed (past participle)","meaning":"put at risk","meaningCN":"受到威胁的","example":"The last wild population is endangered by poaching.","exampleCN":"最后的野生种群受盗猎威胁。"},{"word":"endangerment","structure":"endanger + -ment (state or act)","meaning":"the state of being at risk","meaningCN":"濒危状态；危害行为","example":"The charge was endangerment of a listed species.","exampleCN":"指控是危害名录物种。"},{"word":"dangerous","structure":"danger + -ous (full of)","meaning":"full of danger; likely to harm","meaningCN":"充满危险的；会伤人的","example":"The current is dangerous in spring.","exampleCN":"春季水流很危险。"},{"word":"dominus","structure":"dominus, domini (m., second declension)","meaning":"lord, master","meaningCN":"领主；主人","example":"The Latin word named a master's authority.","exampleCN":"这个拉丁词指主人的权威。"},{"word":"dominion","structure":"dominium (Latin) -> dominion","meaning":"territory or power of a lord","meaningCN":"领地；支配权","example":"The crown held dominion over the coast.","exampleCN":"王权对这片海岸拥有支配权。"}],"latinEntries":[{"word":"dominus","structure":"dominus, domini (m., second declension)","meaning":"lord, master","meaningCN":"领主；主人"},{"word":"dominium","structure":"dominium, domini (n., second declension)","meaning":"ownership, dominion","meaningCN":"所有权；领地"},{"word":"dominiarium","structure":"dominiarium, dominiarii (n., second declension, Vulgar Latin)","meaning":"power to command","meaningCN":"支配之权"}]}},{"word":"endangered species","ipa_uk":"/ɪnˈdeɪndʒəd ˈspiːʃiːz/","ipa_us":"/ɪnˈdeɪndʒərd ˈspiːʃiːz/","definition_zh":"濒危物种；有灭绝危险的物种","definition_en":"a species whose numbers have fallen so low that it is in danger of dying out","core_image":"一份名录上排着一行行名字，每一行旁边都空出一个位置，像候诊室里一个个空椅子","scene":"Every endangered species on the list receives a recovery plan.","sceneCN":"这里 endangered species 指「被认定有灭绝危险、因而需要干预的物种」（第 2 个义项：依法列名并附带恢复义务的物种）；句意为名录上的每个濒危物种都配有一份恢复计划。图中可辨识物件：名录纸页、逐行名字、空出的位置、恢复计划表格。","pos":[{"tag":"n.","zh":"濒危物种（可数；单复数同形，species 本身单复数同形）"}],"collocations":[{"phrase":"protect endangered species","zh":"保护濒危物种"},{"phrase":"endangered species list","zh":"濒危物种名录"},{"phrase":"critically endangered species","zh":"极危物种"},{"phrase":"endangered species recovery","zh":"濒危物种恢复"},{"phrase":"endangered species status","zh":"濒危物种地位"},{"phrase":"endangered species act","zh":"濒危物种法"},{"phrase":"trade in endangered species","zh":"濒危物种贸易"}],"forms":[{"label":"复数（同形）","form":"endangered species"},{"label":"形容词（濒危的）","form":"endangered（濒危的）"},{"label":"名词（物种）","form":"species（物种，单复数同形）"},{"label":"相关动词","form":"endanger（使濒危）"},{"label":"相关名词","form":"endangerment（濒危状态）"}],"derivatives":[{"word":"endangered","pos":"adj.","zh":"濒危的"},{"word":"species","pos":"n.","zh":"物种（单复数同形）"},{"word":"endanger","pos":"v.","zh":"危及；使濒危"},{"word":"endangerment","pos":"n.","zh":"濒危状态"},{"word":"speciation","pos":"n.","zh":"物种形成"}],"senses":[{"no":"01","title":"A species at risk of dying out","titleCN":"有灭绝危险的物种","definition":"a species whose remaining numbers are too low to be safe in the long run","definitionCN":"剩余数量过低、长期难以存续的物种","example":"Every endangered species on the list receives a recovery plan.","exampleCN":"名录上的每个濒危物种都配有一份恢复计划。","why":"the phrase simply joins the adjective of risk to the noun for a kind of living thing, and the risk is the whole point.","whyCN":"这个短语只是把表示风险的形容词接到表示生物种类的名词上，而风险正是它的全部要点。"},{"no":"02","title":"A species listed by statute","titleCN":"依法列名的物种","definition":"a species formally placed on a legal list, which brings protection and recovery duties","definitionCN":"被正式列入法律名录的物种，随之附带保护与恢复义务","example":"The snail became an endangered species under federal law.","exampleCN":"这种蜗牛依据联邦法律成为濒危物种。","why":"law needs a countable, listable unit, and this phrase supplies one, turning a condition into a status.","whyCN":"法律需要一个可数、可列名的单位，这个短语正好提供，把一种状况变成一种身份。"},{"no":"03","title":"One rung of a ranking","titleCN":"受威胁等级中的一档","definition":"the category between vulnerable and critically endangered in conservation rankings","definitionCN":"保护等级排序中介于易危与极危的一档","example":"The cat is officially an endangered species, not yet critically so.","exampleCN":"这种猫正式列为濒危物种，尚未到极危。","why":"a ranked scale needs names for each step, and this phrase became the step that sits one above vulnerable.","whyCN":"分级尺度需要为每一档命名，这个短语就成了高于易危的那一档。"},{"no":"04","title":"A species in rapid decline","titleCN":"数量快速下滑的物种","definition":"a species whose population is falling fast even if it is still numerous","definitionCN":"指数量虽仍多但下滑迅速的物种","example":"The shark is an endangered species despite large catches still being reported.","exampleCN":"尽管仍报告大量渔获，这种鲨鱼已是濒危物种。","why":"what matters is the direction of the curve, not the current height, so a still-numerous species can carry the label.","whyCN":"关键在于曲线的方向而非当下的高度，因此数量仍多的物种也能带这个标签。"},{"no":"05","title":"A flagship on a campaign poster","titleCN":"作为宣传旗舰的濒危物种","definition":"a species used in campaigns because its plight attracts attention and money","definitionCN":"因处境引人注意、能带来关注与资金的宣传用物种","example":"The panda became the endangered species on every poster.","exampleCN":"熊猫成了每张海报上的濒危物种。","why":"campaigns need a face rather than a list, so one species stands in for the category.","whyCN":"宣传活动需要一张脸而非一份清单，因此由某个物种代表整个类别。"},{"no":"06","title":"Protection as policy and budget","titleCN":"作为政策与预算的保护对象","definition":"the object of laws, budgets and recovery programmes rather than a single animal","definitionCN":"指法律、预算与恢复计划的对象，而非单个动物","example":"Spending on endangered species has risen every year since the act passed.","exampleCN":"自该法通过以来，濒危物种相关支出逐年上升。","why":"a category that can be funded becomes a budget line, and the phrase shifts from animals to programmes.","whyCN":"可拨款的类别会变成预算条目，短语便从动物转向计划。"},{"no":"07","title":"A vanishing kind of anything","titleCN":"比喻义：正在消失的一类人或物","definition":"a group or type of thing that is becoming rare and may disappear, used figuratively","definitionCN":"比喻指日益稀少、可能消失的一类人或事物","example":"The corner bookshop is an endangered species in this city.","exampleCN":"街角书店在这座城市里已是濒危物种。","why":"once the phrase is familiar, it can be borrowed for any type that is being pushed out of existence.","whyCN":"短语一旦为人熟悉，就可借用于任何正被挤出存在的类型。"},{"no":"08","title":"The term inside a statute","titleCN":"法律条文内的固定用语","definition":"the exact wording used by statutes and treaties to define what counts as protected","definitionCN":"法规与条约用来界定受保护对象的固定措辞","example":"The definition of endangered species in the act runs to three pages.","exampleCN":"该法对濒危物种的界定有三页之长。","why":"law cannot leave a key term vague, so the everyday phrase is given a precise statutory wording.","whyCN":"法律不能让关键术语含糊，因此给这个日常短语配上了精确的法定措辞。"}],"etymology":{"intro":{"en":"The phrase pairs an English adjective built on danger with Latin species 'kind, appearance'. Species comes from specere 'to look'. Dates are approximate.","cn":"这个短语把基于 danger 的英语形容词与拉丁 species「种类、外观」并列。species 出自 specere「看」。年代均为约数。"},"items":[{"era":"LATIN SPECIES","en":"Species in Latin meant 'a look, an appearance, a kind'; it was a fifth-declension noun and already covered both singular and plural uses.","cn":"拉丁 species 意为「外观、样子、种类」，属第五变格法名词，当时已兼有单数与复数用法。"},{"era":"SPECERE","en":"The noun rests on specere 'to look, to see', the same root that gives spectacle, inspect and specimen.","cn":"这个名词基于 specere「看、观察」，同一词根也给出 spectacle、inspect 与 specimen。"},{"era":"ENGLISH SPECIES","en":"English adopted species in the sixteenth century, and its biological sense was fixed by Linnaeus in the eighteenth.","cn":"英语于 16 世纪吸收 species，其生物学义由林奈在 18 世纪固定。"},{"era":"THE LEGAL PHRASE","en":"The fixed phrase emerged in the 1960s; the United States passed an Endangered Species Preservation Act in 1966 and the Endangered Species Act in 1973.","cn":"这一固定短语在 1960 年代出现；美国 1966 年通过《濒危物种保存法》，1973 年通过《濒危物种法》。"},{"era":"GLOBAL USE","en":"The Convention on International Trade in Endangered Species of Wild Fauna and Flora, signed in 1973, carried the phrase into international law.","cn":"1973 年签署的《濒危野生动植物种国际贸易公约》把这个短语带入国际法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest printed use of the full phrase is not precisely recorded, and the deeper origin of Latin specere is a reconstruction.","cn":"来源不确定（首见年代）：完整短语的最早印刷记录没有确切定论；拉丁 specere 的更深来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds the risk labels that are stacked in a fixed order and constantly swapped; group two holds ways of naming rarity or protection.","cn":"第一组是按固定次序叠放、常被替换的风险标签；第二组是命名稀有或受保护的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"threatened species","ipa":"/ˈθretənd ˈspiːʃiːz/","tag":"one rung below","definition":"In United States law, a species likely to become endangered in the near future; it is less severe than endangered.","definitionCN":"在美国法律中指很可能在近期变为濒危的物种；严重程度低于 endangered。"},{"word":"vulnerable species","ipa":"/ˈvʌlnərəbl ˈspiːʃiːz/","tag":"milder rung","definition":"A species at risk because of small numbers or narrow range, but not yet in danger of imminent extinction.","definitionCN":"因数量少或分布窄而受威胁、但尚未面临迫近灭绝的物种。"},{"word":"critically endangered species","ipa":"/krɪˈtɪkli ɪnˈdeɪndʒəd ˈspiːʃiːz/","tag":"top rung","definition":"A species facing an extremely high risk of extinction in the wild immediately; it sits above endangered.","definitionCN":"指在野外面临极高、迫近灭绝风险的物种；等级高于 endangered。"},{"word":"extinct species","ipa":"/ɪkˈstɪŋkt ˈspiːʃiːz/","tag":"already gone","definition":"A species with no living members; it has passed beyond the endangered stage altogether.","definitionCN":"指已无存活个体的物种；已完全越过濒危阶段。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rare species","ipa":"/reə ˈspiːʃiːz/","tag":"few, not necessarily falling","definition":"A species with few individuals or a small range; rarity alone does not make it endangered.","definitionCN":"指个体少或分布窄的物种；仅稀有并不等于濒危。"},{"word":"protected species","ipa":"/prəˈtektɪd ˈspiːʃiːz/","tag":"legal shield","definition":"A species covered by protective law; the protection may exist for reasons other than extinction risk.","definitionCN":"指受保护法覆盖的物种；保护理由未必是灭绝风险。"},{"word":"at-risk species","ipa":"/æt rɪsk ˈspiːʃiːz/","tag":"broad umbrella","definition":"An informal cover term for any species in trouble, including those not yet formally listed.","definitionCN":"泛指任何处境不佳的物种，包括尚未正式列名者。"},{"word":"flagship species","ipa":"/ˈflæɡʃɪp ˈspiːʃiːz/","tag":"chosen to attract","definition":"A species picked for campaigns because it draws public support; it need not itself be endangered.","definitionCN":"指为宣传而选出的物种，因其能带来公众支持；本身未必濒危。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"endangered 'in danger' + species 'kind': a kind that is in danger of ending.","cn":"endangered「处于危险」+ species「种类」：一种面临终结危险的生物。"},{"en":"The family runs endanger, endangered, endangerment, species, speciation.","cn":"同族词包括 endanger、endangered、endangerment、species、speciation。"},{"en":"Fixed phrases mark the legal sense: endangered species list, endangered species act, trade in endangered species.","cn":"固定搭配标出法律义：濒危物种名录、濒危物种法、濒危物种贸易。"},{"en":"Species is both singular and plural, so the phrase never becomes endangered speciess.","cn":"species 单复数同形，因此这个短语绝不会写成 endangered speciess。"},{"en":"The ladder runs vulnerable, endangered, critically endangered, extinct in the wild, extinct.","cn":"等级阶梯依次为易危、濒危、极危、野外灭绝、灭绝。"}],"abstract":[{"en":"Picture a list where each name has an empty chair beside it.","cn":"想象一份名录，每个名字旁边都有一把空椅子。"},{"en":"Picture a poster animal that stands in for a thousand unnamed others.","cn":"想象一只海报上的动物，替千千万万无名者出场。"},{"en":"Picture a bookshop treated as a kind of animal that may vanish.","cn":"想象一家书店被当成可能消失的一种动物。"}]},"examples":[{"en":"Endangered species are often concentrated in a few small habitats.","cn":"濒危物种往往集中在少数狭小的生境里。"},{"en":"The act requires a plan for every endangered species it lists.","cn":"该法要求为每一个列名的濒危物种制定计划。"},{"en":"Smuggling endangered species is treated as a serious crime.","cn":"走私濒危物种被视为重罪。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「endangered（身处危险）+ species（物种）」——面临消失的物种 → 濒危物种","word":"endangered species"},"root":"endangered（en- + danger + -ed，danger 经古法语 dangier 源自通俗拉丁 dominiarium「领主之权」）+ 拉丁 species「种类、外观」（出自 specere「看」）。英语 endangered species。","sensesIntro":{"en":"Eight senses follow one label: a kind of living thing is marked as at risk, and the label is then read as a warning, a legal status, a rank, a trend, a poster, a budget line and finally a metaphor for anything vanishing.","cn":"八个义项沿同一个标签展开：某一类生物被标记为有风险，这个标签再被读成警告、法律身份、等级、趋势、海报、预算条目，最后成为任何「正在消失之物」的隐喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a list of names, each with an empty chair beside it.","cn":"核心意象：一份名字清单，每个名字旁都有一把空椅子。"},"chain":["KIND AT RISK","NUMBERS LOW","LISTED BY LAW","RANKED BY RISK","FUNDED FOR RECOVERY","BORROWED LABEL"],"branches":[{"senses":"S1 · S4","en":"DECLINE ITSELF: whether already few or still many but falling, the risk is the defining feature.","cn":"下降本身：无论已经很少还是仍多但在下滑，风险都是界定特征。"},{"senses":"S2 · S8","en":"LEGAL STATUS: a condition becomes a listable status with duties attached.","cn":"法律身份：一种状况变成可列名的身份，并附带义务。"},{"senses":"S3 · S5","en":"RANK AND POSTER: the label is both a rung on a ladder and a face on a campaign.","cn":"等级与海报：这个标签既是阶梯上的一档，也是宣传中的一张脸。"},{"senses":"S6","en":"POLICY OBJECT: money and programmes are attached to the category, not to one animal.","cn":"政策对象：资金与计划附着在这一类别，而非某一只动物。"},{"senses":"S7","en":"BORROWED METAPHOR: any vanishing type can be called an endangered species.","cn":"借用的隐喻：任何正在消失的类型都可被称为濒危物种。"}]},"affixes":{"intro":{"en":"The phrase joins an English adjective of risk to a Latin noun of kind; the two halves come from different language families and keep their own histories.","cn":"这个短语把表示风险的英语形容词接到表示种类的拉丁名词上；两半来自不同语系，各自保留自己的历史。"},"latinIntro":{"en":"Latin species yields English species, speciation and specimen, while the adjective half comes through French from Latin dominus 'lord'.","cn":"拉丁 species 衍生英语 species、speciation 与 specimen；形容词那一半则经法语来自拉丁 dominus「领主」。"},"items":[{"word":"en-","structure":"en- (English prefix, 'in, into')","meaning":"put into a state","meaningCN":"使进入某状态","example":"The prefix makes a verb of putting.","exampleCN":"这个前缀造出「使进入」的动词。"},{"word":"danger","structure":"Old French dangier, from dominiarium","meaning":"peril","meaningCN":"危险","example":"The danger was past by dawn.","exampleCN":"天亮时危险已过。"},{"word":"endangered","structure":"en- + danger + -ed","meaning":"put at risk","meaningCN":"受到威胁的","example":"The colony is endangered by warming water.","exampleCN":"该群落受水温上升威胁。"},{"word":"species","structure":"species (Latin noun, fifth declension)","meaning":"a kind, an appearance","meaningCN":"种类；外观","example":"Two species share the lake.","exampleCN":"两个物种共享这个湖。"},{"word":"endangered species","structure":"endangered + species","meaning":"a kind at risk of ending","meaningCN":"面临消失危险的种类","example":"Every endangered species on the list has a plan.","exampleCN":"名录上的每个濒危物种都有计划。"},{"word":"speciation","structure":"species + -ation (process)","meaning":"the forming of new species","meaningCN":"物种形成","example":"Speciation followed the river's change of course.","exampleCN":"河流改道之后出现了物种形成。"},{"word":"specimen","structure":"specere (to look) + -men (result)","meaning":"a sample for looking at","meaningCN":"标本","example":"The specimen was pressed and labelled.","exampleCN":"标本被压平并贴了标签。"},{"word":"endangerment","structure":"endanger + -ment (state)","meaning":"the state of being at risk","meaningCN":"濒危状态","example":"Endangerment of the species was documented in 1990.","exampleCN":"该物种的濒危状态在 1990 年被记录。"},{"word":"specious","structure":"species (appearance) + -ous","meaning":"seeming right but false","meaningCN":"似是而非的","example":"A specious argument looks sound and is not.","exampleCN":"似是而非的论证看起来成立，其实不然。"}],"latinEntries":[{"word":"species","structure":"species, speciei (f., fifth declension)","meaning":"a look, appearance, kind","meaningCN":"外观；种类"},{"word":"specere","structure":"specere, spexi, spectum (verb, third conjugation)","meaning":"to look, observe","meaningCN":"看；观察"},{"word":"dominus","structure":"dominus, domini (m., second declension)","meaning":"lord, master","meaningCN":"领主；主人"}]}},{"word":"vulnerable","ipa_uk":"/ˈvʌlnərəbl/","ipa_us":"/ˈvʌlnərəbəl/","definition_zh":"易受伤害的；脆弱的；易受攻击的；（物种）易危的","definition_en":"easily harmed, attacked or affected because of weakness or lack of protection","core_image":"一只薄壳小船停在开阔水面，任何一道浪都能把水灌进船里","scene":"The island's small population is vulnerable to a single storm.","sceneCN":"这里 vulnerable 指「因规模小、抵抗力弱而容易受损」（第 3 个义项：种群小而分布窄，一次灾害即可重创）；句意为岛上人口稀少，一场风暴就能造成重创。图中可辨识物件：孤立小岛、单间房屋、登陆风暴云、没有任何防波设施的海岸。","pos":[{"tag":"adj.","zh":"易受伤害的；脆弱的；易受攻击的；（物种）易危的"}],"collocations":[{"phrase":"vulnerable to","zh":"易受……影响；易遭……攻击"},{"phrase":"vulnerable group","zh":"弱势群体"},{"phrase":"vulnerable adult","zh":"易受伤害的成年人（法律用语）"},{"phrase":"vulnerable species","zh":"易危物种"},{"phrase":"vulnerable population","zh":"脆弱人群"},{"phrase":"economically vulnerable","zh":"经济上脆弱的"},{"phrase":"vulnerable position","zh":"易受攻击的处境"}],"forms":[{"label":"比较级","form":"more vulnerable（更易受伤害的）"},{"label":"最高级","form":"most vulnerable（最易受伤害的）"},{"label":"名词","form":"vulnerability（脆弱性；易损性）"},{"label":"副词","form":"vulnerably（易受伤害地）"},{"label":"反义形容词","form":"invulnerable（不会受伤的）"}],"derivatives":[{"word":"vulnerability","pos":"n.","zh":"脆弱性；易损性；漏洞"},{"word":"vulnerably","pos":"adv.","zh":"易受伤害地"},{"word":"invulnerable","pos":"adj.","zh":"不会受伤的；无懈可击的"},{"word":"vulnerary","pos":"adj./n.","zh":"治伤的 / 伤药"},{"word":"vulnerabilities","pos":"n.","zh":"脆弱点（复数）"}],"senses":[{"no":"01","title":"Easily hurt in body","titleCN":"身体上容易受伤","definition":"easily injured because the body or its defences are weak","definitionCN":"因身体或防御能力弱而易受伤","example":"A thin shell makes the young turtle vulnerable to gulls.","exampleCN":"薄壳让幼龟容易被海鸥伤害。","why":"vulnerable comes from the Latin word for a wound, so the core idea is being open to being wounded.","whyCN":"vulnerable 出自拉丁语「伤口」一词，核心意思就是「敞开而可能被伤到」。"},{"no":"02","title":"Open to attack or criticism","titleCN":"易受攻击或指责","definition":"easy to attack, criticize or defeat because no defence is in place","definitionCN":"因无防备而容易被攻击、指责或击败","example":"The claim left the minister vulnerable to ridicule.","exampleCN":"这一说法让部长容易成为笑柄。","why":"the wound image transfers from the body to reputation and position, where words do the cutting.","whyCN":"「受伤」的意象从身体移到名誉与地位，在那里动刀的是言语。"},{"no":"03","title":"Ecologically fragile","titleCN":"生态上的脆弱：种群小而分布窄","definition":"said of a species or population that a single event could wipe out","definitionCN":"指一次事件就能摧毁的物种或种群","example":"The island's small population is vulnerable to a single storm.","exampleCN":"岛上人口稀少，一场风暴就能造成重创。","why":"small size and narrow range are the ecological form of having no armour.","whyCN":"规模小、分布窄，正是「没有甲壳」在生态上的形态。"},{"no":"04","title":"Legally exposed to harm","titleCN":"法律意义上的弱势易伤者","definition":"said of a person who cannot protect themselves and may be exploited, as in vulnerable adult","definitionCN":"指无法自我保护、可能被利用的人，如法律上的易受伤害成年人","example":"The statute protects vulnerable adults from financial abuse.","exampleCN":"该法保护易受伤害的成年人免遭经济剥削。","why":"the law adopted the word because it describes a condition rather than an insult, which makes it usable in statutes.","whyCN":"法律采用这个词，因为它描述一种处境而非贬称，因此可用于法条。"},{"no":"05","title":"Susceptible to disease","titleCN":"容易感染疾病","definition":"more likely to catch an illness because immunity or resistance is low","definitionCN":"因免疫或抵抗力低而更可能患病","example":"Malnourished children are vulnerable to infection.","exampleCN":"营养不良的儿童容易感染。","why":"a body with weak defences is wounded easily by pathogens, which is the medical version of the same image.","whyCN":"防御弱的身体容易被病原「伤到」，这是同一意象的医学版本。"},{"no":"06","title":"Economically or socially exposed","titleCN":"经济或社会处境脆弱","definition":"likely to suffer badly from a price change, a job loss or a shock","definitionCN":"指遇价格变化、失业或冲击时更容易受重创","example":"Households with one income are vulnerable to layoffs.","exampleCN":"单一收入家庭在裁员面前很脆弱。","why":"economics borrowed the word for exposure without reserves, where a shock cuts deeper than on a cushioned household.","whyCN":"经济学借它指没有储备的暴露状态：冲击在没有缓冲的家庭里切得更深。"},{"no":"07","title":"A conservation ranking","titleCN":"保护等级中的「易危」一档","definition":"the category above near threatened and below endangered on a conservation scale","definitionCN":"保护等级中高于近危、低于濒危的一档","example":"The orchid is listed as vulnerable, not yet endangered.","exampleCN":"这种兰花列为易危，尚未到濒危。","why":"a ranking needs a lower rung than endangered, and vulnerable already meant open to harm, so it was adopted for that step.","whyCN":"分级需要一个低于濒危的档位，而 vulnerable 本就表示易受伤害，于是被采用为这一档。"},{"no":"08","title":"Emotionally open and exposed","titleCN":"情感上敞开的、肯示弱的","definition":"willing to show feelings and weakness rather than staying guarded","definitionCN":"愿意显露情感与弱点，而非一直设防","example":"Being vulnerable with a friend can deepen trust.","exampleCN":"对朋友示弱可以加深信任。","why":"the negative sense of exposure was turned positive in psychology: to be without armour is also to be capable of closeness.","whyCN":"心理学把「暴露」的负面义转为正面：不披甲，也意味着有能力亲近。"}],"etymology":{"intro":{"en":"Vulnerable comes from Latin vulnerabilis 'wounding', built on vulnerare 'to wound' and vulnus 'wound'. Dates are approximate.","cn":"vulnerable 来自拉丁 vulnerabilis「能伤人的、易受伤的」，基于 vulnerare「使受伤」与 vulnus「伤口」。年代均为约数。"},"items":[{"era":"LATIN VULNUS","en":"Vulnus meant 'a wound', with the stem vulner-; its own origin is uncertain, and the connections sometimes proposed to other Indo-European roots are reconstructions.","cn":"vulnus 意为「伤口」，词干为 vulner-；它自身的来源不确定，被提出的其他印欧词根关联均属重构。"},{"era":"LATIN VULNERARE","en":"Vulnerare 'to wound' was formed on that stem, and vulnerabilis described what can be wounded.","cn":"vulnerare「使受伤」由该词干构成，vulnerabilis 则描述「能被伤到的」。"},{"era":"ENGLISH ARRIVAL","en":"English took vulnerable in the seventeenth century, at first in the literal sense of able to be wounded.","cn":"英语在 17 世纪吸收 vulnerable，最初用其「能被伤到」的字面义。"},{"era":"FIGURATIVE SPREAD","en":"By the eighteenth century it was applied to reputations, arguments and positions that could be attacked.","cn":"到 18 世纪，它已用于可被攻击的名誉、论点与处境。"},{"era":"MODERN CATEGORIES","en":"The twentieth century added the conservation rank, the legal sense of vulnerable adults, and the software sense of a vulnerability.","cn":"20 世纪又增添了保护等级、法律上的易受伤害者，以及软件「漏洞」义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates and deeper root): the earliest citation for the figurative sense is not exactly fixed, and the origin of vulnus before Latin is unsettled.","cn":"来源不确定（首见年代与更深词根）：比喻义的最早书证没有精确确定；vulnus 在拉丁语之前的来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds forms of the same vulner- stock that are easily mixed; group two holds adjectives of weakness and exposure.","cn":"第一组是同出 vulner- 词干、容易混用的形式；第二组是表示脆弱与暴露的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"vulnerability","ipa":"/ˌvʌlnərəˈbɪləti/","tag":"the noun","definition":"The state or a specific point of weakness; vulnerable is the adjective that describes the thing itself.","definitionCN":"指脆弱的状态或具体弱点；vulnerable 是描述事物本身的形容词。"},{"word":"invulnerable","ipa":"/ɪnˈvʌlnərəbl/","tag":"negated","definition":"In- 'not' plus vulnerable: unable to be wounded. It is absolute and rarely compared.","definitionCN":"in-「不」加 vulnerable：不会受伤的。属绝对形容词，很少用比较级。"},{"word":"vulnerably","ipa":"/ˈvʌlnərəbli/","tag":"the adverb","definition":"In a manner that is open to harm, as in speaking vulnerably; it modifies an action, not a thing.","definitionCN":"以易受伤害的方式，如坦诚示弱地说话；修饰动作，而非事物。"},{"word":"vulnerary","ipa":"/ˈvʌlnərəri/","tag":"healing, not harming","definition":"From the same wound root but means good for healing wounds, as a vulnerary herb.","definitionCN":"同出「伤口」词根，但意为「治伤的」，如伤药草。"}]},{"heading":"NEAR MEANING","entries":[{"word":"susceptible","ipa":"/səˈseptəbl/","tag":"easy to affect","definition":"Likely to be influenced or infected; it stresses receptiveness rather than weakness.","definitionCN":"指容易受影响或受感染；强调易接受，而非软弱。"},{"word":"fragile","ipa":"/ˈfrædʒaɪl/","tag":"breaks easily","definition":"Easily broken or damaged by handling; it describes the object's make, not its exposure to attack.","definitionCN":"指经不起触碰、容易破碎；描述构造，而非暴露于攻击。"},{"word":"exposed","ipa":"/ɪkˈspəʊzd/","tag":"no cover","definition":"Left without shelter or protection; it says why something is vulnerable rather than that it is.","definitionCN":"指没有遮蔽或保护；说明脆弱的原因，而非脆弱本身。"},{"word":"defenceless","ipa":"/dɪˈfensləs/","tag":"no means to fight back","definition":"Having no way to resist; a defenceless thing is vulnerable, but a vulnerable thing may still have some defence.","definitionCN":"指无力抵抗；无防御者必脆弱，但脆弱者仍可能有一定防御。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"vulnus 'wound' + -able 'can be': able to be wounded.","cn":"vulnus「伤口」+ -able「能够被」：能被伤到的。"},{"en":"The family runs vulnerable, vulnerability, vulnerably, invulnerable, vulnerary.","cn":"同族词包括 vulnerable、vulnerability、vulnerably、invulnerable、vulnerary。"},{"en":"Fixed phrases mark the senses: vulnerable to, vulnerable group, vulnerable adult, vulnerable species.","cn":"固定搭配标出各义项：易受……影响、弱势群体、易受伤害的成年人、易危物种。"},{"en":"Software calls each weakness a vulnerability, the same wound image in code.","cn":"软件把每个弱点称作 vulnerability，仍是代码里的「伤口」意象。"},{"en":"In conservation it is a rank above near threatened and below endangered.","cn":"在保护等级中，它高于近危、低于濒危。"}],"abstract":[{"en":"Picture a thin-shelled boat on open water.","cn":"想象一只薄壳小船漂在开阔水面。"},{"en":"Picture a house with no sea wall and one storm on the way.","cn":"想象一间没有防波堤的房子，一场风暴正在路上。"},{"en":"Picture a person who says I am not sure, and means it.","cn":"想象一个人说出「我不确定」，而且当真如此。"}]},"examples":[{"en":"Coastal villages are vulnerable to storm surge.","cn":"沿海村庄易受风暴潮侵袭。"},{"en":"The argument is vulnerable on one point: its data.","cn":"这个论证有一处软肋：它的数据。"},{"en":"Small populations are genetically vulnerable.","cn":"小种群在遗传上是脆弱的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「vulnus（伤口）+ able（能够）」——随时可能被划开口子 → 易受伤害的、脆弱的","word":"vulnerable"},"root":"拉丁 vulnerabilis「能被伤到的」来自 vulnerare「使受伤」，词干 vulnus「伤口」；vulnus 更深来源不确定。英语 vulnerable。","sensesIntro":{"en":"Eight senses follow one condition: armour is missing, and that exposure is then read as a body, a reputation, a small population, a legal person, an immune system, a household, a conservation rank and an open heart.","cn":"八个义项沿同一个处境展开：缺少甲壳，这种暴露再被读成身体、名誉、小种群、法律上的个人、免疫系统、家庭、保护等级与敞开的心。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin-shelled boat on open water, one wave from filling.","cn":"核心意象：薄壳小船漂在开阔水面，一道浪就能灌满。"},"chain":["NO ARMOUR","CAN BE WOUNDED","CAN BE ATTACKED","FEW IN NUMBER","NO RESERVES","OPEN HEART"],"branches":[{"senses":"S1 · S5","en":"BODY OPEN: injury and infection both enter through a missing defence.","cn":"身体敞开：受伤与感染都从缺防处进入。"},{"senses":"S2","en":"REPUTATION OPEN: words cut where armour is absent.","cn":"名誉敞开：缺甲之处，言语就能割开。"},{"senses":"S3 · S7","en":"ECOLOGICAL SCALE: few individuals and a narrow range become a ranked category.","cn":"生态尺度：个体少、分布窄，进而成为等级中的一档。"},{"senses":"S4 · S6","en":"SOCIAL EXPOSURE: law and economics name people and households that cannot absorb a shock.","cn":"社会暴露：法律与经济学命名无法承受冲击的个人与家庭。"},{"senses":"S8","en":"POSITIVE EXPOSURE: psychology turns unarmoured into capable of closeness.","cn":"正面暴露：心理学把「不披甲」转为「能亲近」。"}]},"affixes":{"intro":{"en":"Vulnerable is a Latin adjective of root plus suffix; the wound root also builds the noun vulnerability and the healing word vulnerary.","cn":"vulnerable 是词根加后缀的拉丁形容词；「伤口」词根还构成名词 vulnerability 与表示疗伤的 vulnerary。"},"latinIntro":{"en":"Latin vulnus 'wound' and vulnerare 'to wound' give vulnerable, vulnerability and vulnerary; in- negates the first of these.","cn":"拉丁 vulnus「伤口」与 vulnerare「使受伤」衍生 vulnerable、vulnerability 与 vulnerary；in- 则对第一个词加以否定。"},"items":[{"word":"vulnus","structure":"vulnus, vulneris (n., third declension)","meaning":"a wound","meaningCN":"伤口","example":"The stem vulner- carries the wound image.","exampleCN":"词干 vulner- 带着伤口意象。"},{"word":"vulnerare","structure":"vulnerare (Latin verb, first conjugation)","meaning":"to wound","meaningCN":"使受伤","example":"The verb supplies the action behind the adjective.","exampleCN":"这个动词提供形容词背后的动作。"},{"word":"vulnerable","structure":"vulnerare + -abilis (can be)","meaning":"able to be wounded","meaningCN":"能被伤到的","example":"The shell makes the young turtle vulnerable.","exampleCN":"薄壳让幼龟容易受伤。"},{"word":"vulnerability","structure":"vulnerable + -ity (state)","meaning":"the state of being open to harm","meaningCN":"易受伤害的状态","example":"The audit found one serious vulnerability.","exampleCN":"审计发现一处严重漏洞。"},{"word":"vulnerably","structure":"vulnerable + -ly (manner)","meaning":"in an exposed manner","meaningCN":"以易受伤害的方式","example":"He spoke vulnerably about the failure.","exampleCN":"他坦诚地谈了自己的失败。"},{"word":"invulnerable","structure":"in- (not) + vulnerable","meaning":"unable to be wounded","meaningCN":"不会受伤的","example":"No position is invulnerable forever.","exampleCN":"没有哪个阵地能永远无懈可击。"},{"word":"vulnerary","structure":"vulnus + -ary (belonging to)","meaning":"good for healing wounds","meaningCN":"治伤的","example":"The leaf was used as a vulnerary.","exampleCN":"这种叶子被用作伤药。"},{"word":"vulnerabilities","structure":"vulnerability + -es (plural)","meaning":"several points of weakness","meaningCN":"多处弱点","example":"The report lists three vulnerabilities.","exampleCN":"报告列出三处脆弱点。"},{"word":"invulnerability","structure":"invulnerable + -ity","meaning":"the state of being unassailable","meaningCN":"无懈可击的状态","example":"The myth of invulnerability cost them dearly.","exampleCN":"「无懈可击」的迷思让他们付出沉重代价。"}],"latinEntries":[{"word":"vulnus","structure":"vulnus, vulneris (n., third declension)","meaning":"a wound","meaningCN":"伤口"},{"word":"vulnerare","structure":"vulnerare, vulneravi, vulneratum (verb, first conjugation)","meaning":"to wound","meaningCN":"使受伤"},{"word":"vulnerabilis","structure":"vulnerabilis, vulnerabile (adjective)","meaning":"that can be wounded","meaningCN":"能被伤到的"}]}},{"word":"vulnerability","ipa_uk":"/ˌvʌlnərəˈbɪləti/","ipa_us":"/ˌvʌlnərəˈbɪləti/","definition_zh":"脆弱性；易受伤害性；弱点；漏洞","definition_en":"the state of being easily harmed, or a particular point where harm can get in","core_image":"一块木板上有一道细缝，水正从缝里一点点渗进来","scene":"A single weak password created a vulnerability that exposed the whole network.","sceneCN":"这里 vulnerability 指「系统中的一个弱点，可被利用而造成损害」（第 7 个义项：软件或网络中的安全漏洞）；句意为一个弱密码造成漏洞，使整个网络暴露。图中可辨识物件：带缝的板、渗入的水线、密码输入框、向外扩散的连线。","pos":[{"tag":"n.","zh":"脆弱性；易受伤害性；弱点；漏洞（可数或不可数，复数 vulnerabilities）"}],"collocations":[{"phrase":"vulnerability to","zh":"对……的脆弱性"},{"phrase":"vulnerability assessment","zh":"脆弱性评估"},{"phrase":"security vulnerability","zh":"安全漏洞"},{"phrase":"social vulnerability","zh":"社会脆弱性"},{"phrase":"climate vulnerability","zh":"气候脆弱性"},{"phrase":"reduce vulnerability","zh":"降低脆弱性"},{"phrase":"structural vulnerability","zh":"结构性脆弱"}],"forms":[{"label":"复数","form":"vulnerabilities"},{"label":"形容词","form":"vulnerable（易受伤害的）"},{"label":"副词","form":"vulnerably（易受伤害地）"},{"label":"反义名词","form":"invulnerability（无懈可击）"},{"label":"反义形容词","form":"invulnerable（不会受伤的）"}],"derivatives":[{"word":"vulnerable","pos":"adj.","zh":"易受伤害的；脆弱的"},{"word":"vulnerably","pos":"adv.","zh":"易受伤害地"},{"word":"invulnerable","pos":"adj.","zh":"不会受伤的"},{"word":"invulnerability","pos":"n.","zh":"无懈可击的状态"},{"word":"vulnerary","pos":"adj.","zh":"治伤的"}],"senses":[{"no":"01","title":"The state of being easily harmed","titleCN":"易受伤害的状态","definition":"the condition of being open to harm because of weakness or lack of protection","definitionCN":"因脆弱或缺少保护而处于可能受害的状态","example":"The storm exposed the vulnerability of the low-lying villages.","exampleCN":"这场风暴暴露了低洼村庄的脆弱。","why":"vulnerability is the noun of vulnerable, and both rest on the Latin word for a wound, so the state named is one of being woundable.","whyCN":"vulnerability 是 vulnerable 的名词，二者都基于拉丁语「伤口」一词，因此所命名的状态就是「可被伤到」。"},{"no":"02","title":"A specific weak point","titleCN":"具体的薄弱之处","definition":"a particular point in a system, plan or defence where harm can enter","definitionCN":"系统、计划或防御中可让损害进入的具体一点","example":"The report identified three vulnerabilities in the supply chain.","exampleCN":"报告指出供应链中的三处薄弱环节。","why":"a state can be counted once it is located, so the noun also names the individual gap rather than the general condition.","whyCN":"状态一旦能被定位便可计数，因此这个名词也指一个个具体的缺口，而非笼统的状况。"},{"no":"03","title":"Ecological vulnerability","titleCN":"生态脆弱性","definition":"the likelihood that an ecosystem or species will suffer from a disturbance","definitionCN":"生态系统或物种在受到干扰时受损的可能性","example":"Small range and slow breeding raise the bird's ecological vulnerability.","exampleCN":"分布窄、繁殖慢，提高了这种鸟的生态脆弱性。","why":"ecology turns the state into a probability, asking how much damage a given shock would do.","whyCN":"生态学把这个状态变成概率，追问一次冲击会造成多大损伤。"},{"no":"04","title":"Social vulnerability","titleCN":"社会脆弱性","definition":"the greater likelihood that some groups will be harmed by a hazard because of poverty, age or discrimination","definitionCN":"某些群体因贫困、年龄或歧视而更可能被灾害伤害","example":"Social vulnerability explains why the same flood hurt some neighbourhoods more.","exampleCN":"社会脆弱性解释了为何同一场洪水对某些街区伤害更重。","why":"a hazard is not shared equally, so the noun is attached to groups whose circumstances leave them more exposed.","whyCN":"同一灾害并非平均分配，因此这个名词被接到处境使其更暴露的群体上。"},{"no":"05","title":"Climate vulnerability","titleCN":"气候脆弱性","definition":"the degree to which a place or system can be hurt by climate hazards and cannot adapt","definitionCN":"某地或某系统受气候灾害影响且难以适应的程度","example":"The atlas maps climate vulnerability along the coast.","exampleCN":"这份图集标出了沿海的气候脆弱性。","why":"climate science needed a combined measure of exposure and inability to adapt, and this noun supplies it.","whyCN":"气候科学需要一个把暴露程度与无力适应合并起来的度量，这个名词正好提供。"},{"no":"06","title":"Emotional openness","titleCN":"情感上的易感与敞开","definition":"the willingness to let others see one's feelings and weaknesses","definitionCN":"愿意让他人看到自己的情感与弱点","example":"Her vulnerability in the interview made the story believable.","exampleCN":"她在访谈中的坦诚示弱让这个故事可信。","why":"psychology gave the same word a positive turn: letting the guard down is what allows trust to form.","whyCN":"心理学给同一个词加了正面转向：放下防备，信任才有可能形成。"},{"no":"07","title":"A flaw that can be exploited","titleCN":"可被利用的安全漏洞","definition":"a weakness in software or a network that an attacker can use to gain access","definitionCN":"软件或网络中可被攻击者利用以取得访问权的弱点","example":"A single weak password created a vulnerability that exposed the whole network.","exampleCN":"一个弱密码造成漏洞，使整个网络暴露。","why":"security borrowed the wound image literally: a flaw is an opening through which something hostile gets in.","whyCN":"安全领域字面借用了「伤口」意象：缺陷就是让敌意之物进入的开口。"},{"no":"08","title":"Legal exposure of a person","titleCN":"法律上个人的易受伤害状态","definition":"the condition of a person who cannot protect their own interests and may be exploited","definitionCN":"指无法维护自身利益、可能被利用的个人处境","example":"The court considered the vulnerability of the witness.","exampleCN":"法庭考虑了证人的易受伤害处境。","why":"law needs a neutral term for someone who cannot guard their own interests, and vulnerability supplies that description.","whyCN":"法律需要一个中性词来描述无法维护自身利益的人，vulnerability 正好提供这一描述。"}],"etymology":{"intro":{"en":"Vulnerability is Latin vulnerabilis plus the noun suffix -ity; the base is vulnus 'wound'. Dates are approximate.","cn":"vulnerability 是拉丁 vulnerabilis 加名词后缀 -ity；基底是 vulnus「伤口」。年代均为约数。"},"items":[{"era":"LATIN VULNUS","en":"Vulnus 'wound' supplies the stem vulner-; its own earlier origin is uncertain and the Indo-European links proposed for it are reconstructions.","cn":"vulnus「伤口」提供词干 vulner-；它更早的来源不确定，为其提出的印欧关联均属重构。"},{"era":"LATIN VULNERABILIS","en":"Vulnerabilis meant 'that can be wounded', formed with the suffix -abilis 'able to be'.","cn":"vulnerabilis 意为「能被伤到的」，由后缀 -abilis「能够被」构成。"},{"era":"ENGLISH NOUN","en":"The abstract noun vulnerability is recorded in English from the seventeenth century, at first in the literal sense of being woundable.","cn":"抽象名词 vulnerability 自 17 世纪在英语中有记录，最初用「可被伤到」的字面义。"},{"era":"SOCIAL AND ECOLOGICAL USE","en":"The twentieth century applied the noun to groups exposed to hazards and to ecosystems likely to be damaged.","cn":"20 世纪把这个名词用于暴露于灾害的群体，以及可能受损的生态系统。"},{"era":"COMPUTING SENSE","en":"The security sense of a weakness that can be exploited spread in the 1990s with networked computing and formal vulnerability databases.","cn":"指可被利用的弱点的安全义，在 1990 年代随网络计算与正式的漏洞数据库而扩散。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest citation for the social sense and the exact date of the computing sense are not precisely recorded, and the origin of vulnus remains unsettled.","cn":"来源不确定（首见年代）：社会义的最早书证与计算义的准确年代都没有精确记录；vulnus 的来源仍无定论。"}]},"similar":{"note":{"en":"Group one holds forms of the same vulner- family that are easily mixed; group two holds nouns for weakness and exposure.","cn":"第一组是同出 vulner- 词族、容易混用的形式；第二组是表示软弱与暴露的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"vulnerable","ipa":"/ˈvʌlnərəbl/","tag":"the adjective","definition":"Describes the thing that can be harmed; vulnerability names the state or the specific flaw.","definitionCN":"描述可能受损的事物本身；vulnerability 指状态或具体缺陷。"},{"word":"vulnerably","ipa":"/ˈvʌlnərəbli/","tag":"the adverb","definition":"Modifies how an action is done, as in speaking vulnerably; it cannot replace the noun.","definitionCN":"修饰动作的方式，如坦诚示弱地说话；不能替代名词。"},{"word":"invulnerability","ipa":"/ˌɪnvʌlnərəˈbɪləti/","tag":"the negation","definition":"In- 'not' plus vulnerability: the state of being impossible to harm. It is a claim, often a false one.","definitionCN":"in-「不」加 vulnerability：不可能受伤的状态。这种说法常属虚妄。"},{"word":"vulnerary","ipa":"/ˈvʌlnərəri/","tag":"healing, not harming","definition":"From the same wound stem but means a remedy for wounds, so it belongs to medicine rather than risk.","definitionCN":"同出「伤口」词干，但意为治伤的药物，属医学而非风险领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"weakness","ipa":"/ˈwiːknəs/","tag":"general flaw","definition":"Any lack of strength; vulnerability adds the idea that the weakness can be exploited or will be hit.","definitionCN":"泛指力量不足；vulnerability 添上「可被利用、会被击中」的意思。"},{"word":"exposure","ipa":"/ɪkˈspəʊʒə/","tag":"no cover","definition":"The state of being left open to something; it explains the source of a vulnerability.","definitionCN":"指处于毫无遮挡的状态；它解释脆弱性的来源。"},{"word":"susceptibility","ipa":"/səˌseptəˈbɪləti/","tag":"easy to influence","definition":"The likelihood of being affected, especially by disease; it stresses receptiveness.","definitionCN":"指容易受影响的可能性，尤指疾病；强调易接受。"},{"word":"fragility","ipa":"/fræˈdʒɪləti/","tag":"breaks easily","definition":"The quality of being easily broken; it concerns the object's make rather than an attacker.","definitionCN":"指容易破碎的性质；关注构造本身，而非外来攻击者。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"vulnerable 'woundable' + -ity 'state': the state of being woundable.","cn":"vulnerable「能被伤到」+ -ity「状态」：可被伤到的状态。"},{"en":"The family runs vulnerable, vulnerability, vulnerably, invulnerable, vulnerary.","cn":"同族词包括 vulnerable、vulnerability、vulnerably、invulnerable、vulnerary。"},{"en":"Fixed phrases mark the fields: social vulnerability, climate vulnerability, security vulnerability.","cn":"固定搭配标出各领域：社会脆弱性、气候脆弱性、安全漏洞。"},{"en":"In computing, a vulnerability is a door left unlocked, not a burglar.","cn":"在计算领域，漏洞是没锁的门，而不是贼。"},{"en":"The plural vulnerabilities is standard for a list of flaws.","cn":"列出一串缺陷时用复数 vulnerabilities。"}],"abstract":[{"en":"Picture water finding one thin crack in a plank.","cn":"想象水找到了木板上一道细缝。"},{"en":"Picture a chain that fails at its single weakest link.","cn":"想象一条链子从最弱的一环断开。"},{"en":"Picture a person saying I need help, and meaning it.","cn":"想象一个人说出「我需要帮助」，而且当真。"}]},"examples":[{"en":"The assessment ranks vulnerability by district and by income.","cn":"这项评估按地区与收入排列脆弱程度。"},{"en":"Patch the vulnerability before the server goes live.","cn":"在服务器上线之前修补这个漏洞。"},{"en":"Reducing vulnerability is cheaper than rebuilding after a flood.","cn":"降低脆弱性比洪水后重建更便宜。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「vulner（伤口）+ ability（能力）」——有「被划伤的能力」 → 脆弱性、弱点、漏洞","word":"vulnerability"},"root":"拉丁 vulnerabilis「能被伤到的」（vulnerare「使受伤」，词干 vulnus「伤口」）+ -ity（状态）；vulnus 更深来源不确定。英语 vulnerability。","sensesIntro":{"en":"Eight senses follow one condition: an opening exists, and it is then read as a general state, a located flaw, an ecosystem, a social group, a coastline, an open heart, a network and a witness in court.","cn":"八个义项沿同一个处境展开：存在一个开口，这个开口再被读成总体状态、被定位的缺陷、生态系统、社会群体、海岸线、敞开的心、网络与法庭上的证人。"},"semanticMap":{"core":{"en":"CORE IMAGE: water seeping through one thin crack in a plank.","cn":"核心意象：水从木板上一道细缝渗进来。"},"chain":["AN OPENING","BEING WOUNDABLE","A LOCATED FLAW","ECOLOGICAL RISK","SOCIAL RISK","EXPLOITABLE GAP"],"branches":[{"senses":"S1 · S2","en":"STATE AND POINT: the condition first, then the countable spot where it lives.","cn":"状态与点位：先是总体状况，再是可数的具体所在。"},{"senses":"S3 · S5","en":"ENVIRONMENTAL RISK: ecosystems and coastlines are scored by what a shock would do.","cn":"环境风险：生态系统与海岸线按一次冲击的破坏力计分。"},{"senses":"S4 · S8","en":"PEOPLE AT RISK: social groups and individual witnesses can be exposed.","cn":"人处于风险：社会群体与单个证人都可能暴露。"},{"senses":"S6","en":"OPEN HEART: showing weakness is the same opening, taken voluntarily.","cn":"敞开的心：显露弱点也是同一个开口，只是自愿打开。"},{"senses":"S7","en":"EXPLOITABLE GAP: a network flaw is an unlocked door.","cn":"可被利用的缺口：网络缺陷就是一扇没锁的门。"}]},"affixes":{"intro":{"en":"Vulnerability is root plus two suffixes; the same wound root appears across the family, and -ity turns the adjective into a countable or mass noun.","cn":"vulnerability 是词根加两个后缀；同一「伤口」词根贯通整个词族，-ity 把形容词变成可数或不可数名词。"},"latinIntro":{"en":"Latin vulnus and vulnerare give vulnerable, vulnerability and vulnerary; in- negates and -ity abstracts.","cn":"拉丁 vulnus 与 vulnerare 衍生 vulnerable、vulnerability 与 vulnerary；in- 表否定，-ity 表抽象。"},"items":[{"word":"vulnus","structure":"vulnus, vulneris (n., third declension)","meaning":"a wound","meaningCN":"伤口","example":"The stem vulner- runs through the whole family.","exampleCN":"词干 vulner- 贯穿整个词族。"},{"word":"vulnerare","structure":"vulnerare (Latin verb, first conjugation)","meaning":"to wound","meaningCN":"使受伤","example":"The verb supplies the action behind the noun.","exampleCN":"这个动词提供名词背后的动作。"},{"word":"-abilis","structure":"-abilis (Latin suffix, 'able to be')","meaning":"capable of being","meaningCN":"能够被……的","example":"The suffix turns a verb into a possibility.","exampleCN":"这个后缀把动词变成一种可能性。"},{"word":"vulnerable","structure":"vulnerare + -abilis","meaning":"able to be wounded","meaningCN":"能被伤到的","example":"The bridge is vulnerable to corrosion.","exampleCN":"这座桥容易受腐蚀。"},{"word":"-ity","structure":"-ity (Latin suffix, 'state of')","meaning":"the state of being","meaningCN":"……的状态","example":"The suffix makes an abstract noun of the adjective.","exampleCN":"这个后缀把形容词变成抽象名词。"},{"word":"vulnerability","structure":"vulnerable + -ity","meaning":"the state of being woundable","meaningCN":"可被伤到的状态","example":"The audit found one vulnerability.","exampleCN":"审计发现一处漏洞。"},{"word":"vulnerabilities","structure":"vulnerability + -es (plural)","meaning":"several weak points","meaningCN":"多处弱点","example":"The scanner lists known vulnerabilities.","exampleCN":"扫描器列出已知漏洞。"},{"word":"invulnerability","structure":"in- (not) + vulnerability","meaning":"the state of being unassailable","meaningCN":"无懈可击的状态","example":"No system can claim invulnerability.","exampleCN":"没有系统能自称无懈可击。"},{"word":"vulnerary","structure":"vulnus + -ary (belonging to)","meaning":"a remedy for wounds","meaningCN":"伤药","example":"The bark served as a vulnerary.","exampleCN":"这种树皮被用作伤药。"}],"latinEntries":[{"word":"vulnus","structure":"vulnus, vulneris (n., third declension)","meaning":"a wound","meaningCN":"伤口"},{"word":"vulnerare","structure":"vulnerare, vulneravi, vulneratum (verb, first conjugation)","meaning":"to wound","meaningCN":"使受伤"},{"word":"vulnerabilis","structure":"vulnerabilis, vulnerabile (adjective)","meaning":"that can be wounded","meaningCN":"能被伤到的"},{"word":"vulnerabilitas","structure":"vulnerabilitas, vulnerabilitatis (f., third declension)","meaning":"liability to wounds","meaningCN":"易受伤的性质"}]}},{"word":"population growth","ipa_uk":"/ˌpɒpjʊˈleɪʃn ɡrəʊθ/","ipa_us":"/ˌpɑːpjəˈleɪʃən ɡroʊθ/","definition_zh":"人口增长；（生物）种群增长","definition_en":"an increase in the number of people or organisms in a place or group","core_image":"一条曲线从左下角缓缓抬头，随后几乎竖直向上冲出图纸","scene":"Rapid population growth outpaced the city's water supply.","sceneCN":"这里 population growth 指「人口数量的增加」（第 1 个义项：某地人口总数上升）；句意为人口的快速增长超出了城市供水能力。图中可辨识物件：陡升的曲线、拥挤的楼群、见底的水塔、逐年刻度。","pos":[{"tag":"n.","zh":"人口增长；种群增长（不可数，偶作可数指具体一次增长）"}],"collocations":[{"phrase":"rapid population growth","zh":"快速人口增长"},{"phrase":"population growth rate","zh":"人口增长率"},{"phrase":"natural population growth","zh":"人口自然增长"},{"phrase":"zero population growth","zh":"人口零增长"},{"phrase":"slow population growth","zh":"缓慢的人口增长"},{"phrase":"population growth and resources","zh":"人口增长与资源"},{"phrase":"unchecked population growth","zh":"不受约束的人口增长"}],"forms":[{"label":"复数（少见，指多次局部增长）","form":"population growths"},{"label":"相关名词","form":"population（人口）"},{"label":"相关动词","form":"grow（增长）"},{"label":"相关名词","form":"growth（增长）"},{"label":"反义说法","form":"population decline（人口下降）"}],"derivatives":[{"word":"population","pos":"n.","zh":"人口；种群"},{"word":"populous","pos":"adj.","zh":"人口稠密的"},{"word":"populate","pos":"v.","zh":"居住于；使有人口"},{"word":"grow","pos":"v.","zh":"增长；生长"},{"word":"growth","pos":"n.","zh":"增长；生长"}],"senses":[{"no":"01","title":"More people in a place","titleCN":"某地人口数量的增加","definition":"a rise in the number of people living in a place","definitionCN":"某地居住人数的上升","example":"Rapid population growth outpaced the city's water supply.","exampleCN":"人口的快速增长超出了城市供水能力。","why":"population names the people counted together, and growth names increase, so the phrase states a simplest fact: the count is going up.","whyCN":"population 指被一起计数的人，growth 指增加，因此这个短语陈述一件最简单的事：数目在上升。"},{"no":"02","title":"The rate of increase","titleCN":"增长率：单位时间增加多少","definition":"the percentage or number by which a population rises in a given period","definitionCN":"一定时期内人口上升的百分比或数量","example":"The population growth rate fell from three percent to one.","exampleCN":"人口增长率从百分之三降到百分之一。","why":"once demographers wanted to compare places, the phrase needed a denominator, and rate supplies it.","whyCN":"当人口学家需要比较各地，这个短语就需要一个分母，rate 提供了它。"},{"no":"03","title":"Natural increase","titleCN":"自然增长：出生减死亡","definition":"growth produced by births exceeding deaths, without migration","definitionCN":"出生数超过死亡数所带来的增长，不计迁移","example":"Natural population growth turned negative as births fell.","exampleCN":"随着出生数下降，人口自然增长转为负值。","why":"demographers separate the two books that change a population, and natural increase is the one kept without migration.","whyCN":"人口学家把改变人口的两本账分开，自然增长就是不计迁移的那一本。"},{"no":"04","title":"Growth through migration","titleCN":"迁移带来的增长","definition":"growth produced by more people arriving than leaving","definitionCN":"迁入人数多于迁出人数所带来的增长","example":"Most of the city's population growth came from newcomers rather than births.","exampleCN":"这座城市的人口增长多来自外来者，而非出生。","why":"the second book is net migration, and a city can grow through arrivals even when its own birth rate is low.","whyCN":"第二本账是净迁移：即使本地出生率很低，城市也能靠迁入而增长。"},{"no":"05","title":"The steep phase of a curve","titleCN":"指数增长阶段：曲线陡升","definition":"the phase in which numbers rise faster and faster because growth feeds on itself","definitionCN":"数量因增长自身而越来越快地上升的阶段","example":"During the steep phase of population growth, schools were built every year.","exampleCN":"在人口增长的陡升阶段，每年都要新建学校。","why":"growth that feeds on itself bends the curve upward, which is why the phrase is often used with steep and exponential.","whyCN":"自我推动的增长把曲线向上掰弯，因此这个短语常与 steep、exponential 连用。"},{"no":"06","title":"Growth of non-human populations","titleCN":"非人类种群的增长","definition":"an increase in the numbers of animals, plants or microbes rather than people","definitionCN":"指动物、植物或微生物数量的增加，而非人口","example":"Deer population growth followed the removal of predators.","exampleCN":"捕食者消失之后，鹿群数量随之增长。","why":"the same arithmetic governs animals, so population growth is also the standard term in ecology.","whyCN":"同一套算术也管动物，因此 population growth 同样是生态学的标准术语。"},{"no":"07","title":"The end of growth","titleCN":"零增长或负增长：增长的终止","definition":"the condition in which numbers stop rising, as in zero population growth","definitionCN":"数量停止上升的状态，如人口零增长","example":"Zero population growth was reached in the 1990s.","exampleCN":"人口零增长在 1990 年代实现。","why":"once growth became a policy variable, its absence needed a name, and zero growth supplies the target.","whyCN":"一旦增长成为政策变量，它的缺席也需要一个名称，零增长正好提供这个目标。"},{"no":"08","title":"Growth of a market or audience","titleCN":"经济义：市场或受众规模的扩大","definition":"an increase in the number of customers or users seen as a population","definitionCN":"把客户或用户视作人群时的数量扩大","example":"The app's population growth attracted advertisers.","exampleCN":"这款应用用户规模的增长吸引了广告商。","why":"business counts users as a population, so the phrase transfers without changing its arithmetic.","whyCN":"商业把用户当作人群来计数，因此这个短语在转用时算术并未改变。"}],"etymology":{"intro":{"en":"Population comes from Latin populatio 'a peopling', from populus 'people'; growth is native English from grow. The phrase is modern. Dates are approximate.","cn":"population 来自拉丁 populatio「使有人居住、人群」，源自 populus「人民」；growth 是英语本族词，来自 grow。这个短语是近代组合。年代均为约数。"},"items":[{"era":"LATIN POPULUS","en":"Populus meant 'people, nation'. Its own origin is uncertain; the proposal that it came through Etruscan is a hypothesis rather than a demonstrated derivation.","cn":"populus 意为「人民、民族」。其自身来源不确定；认为它经埃特鲁里亚语而来的说法属假说，并非已证实的派生。"},{"era":"LATIN POPULATIO","en":"Populatio named a peopling or a multitude; English took population in the sixteenth century for the people of a place.","cn":"populatio 指使有人居住或人群；英语在 16 世纪以 population 指某地的人口。"},{"era":"OLD ENGLISH GROWAN","en":"Grow descends from Old English growan 'to grow, increase', of Germanic stock, and its noun growth followed in the fourteenth century.","cn":"grow 承自古英语 growan「生长、增加」，属日耳曼语；其名词 growth 于 14 世纪出现。"},{"era":"THE MODERN PHRASE","en":"Population growth became a fixed phrase in the nineteenth century, when censuses made the count comparable across decades.","cn":"population growth 在 19 世纪成为固定短语，当时人口普查使跨年代的计数可以比较。"},{"era":"POLICY DEBATE","en":"The twentieth century turned the phrase into a subject of policy, from Malthus's arithmetic to the population conferences of the 1990s.","cn":"20 世纪把这个短语变成政策议题，从马尔萨斯的算术到 1990 年代的人口会议。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest use of the exact phrase is not precisely recorded, and the origin of Latin populus remains unsettled.","cn":"来源不确定（首见年代）：这一确切短语的最早使用没有精确记录；拉丁 populus 的来源仍无定论。"}]},"similar":{"note":{"en":"Group one holds words of the populus family that are easily confused; group two holds phrases for numbers rising.","cn":"第一组是同出 populus 词族、容易混淆的词；第二组是数量上升的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"population","ipa":"/ˌpɒpjʊˈleɪʃn/","tag":"the count itself","definition":"The number of people or organisms; population growth is the change in that number over time.","definitionCN":"指人或生物的数量；population growth 是这个数量随时间的变化。"},{"word":"populous","ipa":"/ˈpɒpjʊləs/","tag":"adjective of density","definition":"Full of people, as a populous country; it describes a state, not a trend.","definitionCN":"指人口众多，如人口大国；描述状态，不描述趋势。"},{"word":"populate","ipa":"/ˈpɒpjʊleɪt/","tag":"the verb","definition":"To fill a place with people or to enter data into a system; it names an act, not a trend.","definitionCN":"指使人居住于某地或向系统填入数据；命名动作，而非趋势。"},{"word":"depopulation","ipa":"/ˌdiːpɒpjʊˈleɪʃn/","tag":"the opposite","definition":"De- 'away from' plus population: the losing of people from a place, the mirror image of growth.","definitionCN":"de-「离开」加 population：某地失去人口，是增长的镜像。"}]},{"heading":"NEAR MEANING","entries":[{"word":"population increase","ipa":"/ˌpɒpjʊˈleɪʃn ɪnˈkriːs/","tag":"plain synonym","definition":"A neutral statement that the number has risen, without implying a rate or a phase.","definitionCN":"中性说明数量已上升，不含速率或阶段的意味。"},{"word":"demographic growth","ipa":"/ˌdiːməˈɡræfɪk ɡrəʊθ/","tag":"structural view","definition":"Growth described through births, deaths and age structure rather than a single total.","definitionCN":"通过出生、死亡与年龄结构描述的 growth，而非单一总量。"},{"word":"baby boom","ipa":"/ˈbeɪbi buːm/","tag":"one sharp episode","definition":"A short surge in births; it is one cause of population growth, not the general term.","definitionCN":"指出生数的短促激增；它是人口增长的一个原因，而非总称。"},{"word":"carrying capacity","ipa":"/ˈkæriɪŋ kəˈpæsəti/","tag":"the ceiling","definition":"The largest population an environment can support; growth stops when it is reached.","definitionCN":"指环境能支撑的最大人口量；达到它时增长就停止。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"population 'the people counted' + growth 'increase': the count going up.","cn":"population「被计数的人口」+ growth「增加」：数目在上升。"},{"en":"The family runs population, populous, populate, depopulation, growth, grow.","cn":"同族词包括 population、populous、populate、depopulation、growth、grow。"},{"en":"Fixed phrases mark the senses: population growth rate, natural population growth, zero population growth.","cn":"固定搭配标出各义项：人口增长率、人口自然增长、人口零增长。"},{"en":"Demographers split growth into natural increase and net migration.","cn":"人口学家把增长拆成自然增加与净迁移。"},{"en":"Growth without a rate is a fact; growth with a rate is a comparison.","cn":"不带速率的增长是事实；带速率的增长是比较。"}],"abstract":[{"en":"Picture a line on paper that bends upward and will not straighten.","cn":"想象纸上的线向上弯，弯得收不回来。"},{"en":"Picture a lifeboat taking on people faster than it can take on water.","cn":"想象救生艇上人的增加快过它能进水的速度。"},{"en":"Picture a queue that doubles while the door stays one door wide.","cn":"想象队伍不断翻倍，而门始终只有一扇宽。"}]},"examples":[{"en":"Population growth slowed once girls stayed in school longer.","cn":"女孩在校时间延长后，人口增长放缓了。"},{"en":"The graph shows population growth against grain output.","cn":"这张图把人口增长与粮食产量并列显示。"},{"en":"Wildlife population growth can overshoot the food supply.","cn":"野生动物种群的增长可能超过食物供给。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「population（人口）+ growth（增长）」——被计数的人越来越多 → 人口增长","word":"population growth"},"root":"拉丁 populus「人民」（更早来源不确定）+ populatio「人群、使有人居住」+ 古英语 growan「生长、增加」；英语 population growth。","sensesIntro":{"en":"Eight senses follow one movement: a count rises, and that rise is then read as a rate, a natural surplus, a migration effect, a steep curve, a wildlife trend, a halt, and a market.","cn":"八个义项沿同一个变化展开：某个计数上升，这个上升再被读成速率、自然盈余、迁移效应、陡升曲线、野生动物趋势、停止，以及市场。"},"semanticMap":{"core":{"en":"CORE IMAGE: a curve that lifts gently and then shoots upward.","cn":"核心意象：一条先缓抬、后猛冲的曲线。"},"chain":["MORE PEOPLE","COUNT RISES","RATE MEASURED","BIRTHS OVER DEATHS","MIGRANTS ARRIVE","CURVE STEEPENS"],"branches":[{"senses":"S1 · S2","en":"FACT AND RATE: the bare increase, then the same increase divided by time.","cn":"事实与速率：先是不加修饰的增加，再是除以时间后的同一增加。"},{"senses":"S3 · S4","en":"TWO SOURCES: births exceeding deaths, or arrivals exceeding departures.","cn":"两个来源：出生多于死亡，或迁入多于迁出。"},{"senses":"S5 · S6","en":"SELF-FEEDING GROWTH: the steep phase, whether of people or of deer.","cn":"自我推动的增长：陡升阶段，人或鹿皆然。"},{"senses":"S7","en":"THE HALT: zero growth is the phrase turned into a target.","cn":"停止：零增长就是把短语变成目标。"},{"senses":"S8","en":"BORROWED MARKET: users are counted as a population and their rise becomes growth.","cn":"借用的市场：用户被当作人群计数，其上升便成为增长。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of people to a native English noun of increasing; neither half carries a prefix or suffix of its own.","cn":"这个短语把表示人民的拉丁名词与表示增加的本族英语名词并置；两半本身都不带前缀或后缀。"},"latinIntro":{"en":"Latin populus yields population, populous, populate and depopulation; Old English growan yields grow, growth and growing.","cn":"拉丁 populus 衍生 population、populous、populate 与 depopulation；古英语 growan 衍生 grow、growth 与 growing。"},"items":[{"word":"populus","structure":"populus, populi (m., second declension)","meaning":"people, nation","meaningCN":"人民；民族","example":"The Latin noun names a people as a body.","exampleCN":"这个拉丁名词把人民视为一个整体。"},{"word":"population","structure":"populatio (Latin) -> population","meaning":"the people of a place","meaningCN":"某地的人口","example":"The population passed one million.","exampleCN":"人口突破一百万。"},{"word":"populous","structure":"population + -ous (full of)","meaning":"full of people","meaningCN":"人口稠密的","example":"The delta is the most populous region.","exampleCN":"三角洲是人口最稠密的地区。"},{"word":"populate","structure":"populus + -ate (verb)","meaning":"to fill with people","meaningCN":"使有人居住","example":"Settlers populated the valley within a century.","exampleCN":"定居者在一个世纪内住满了这条谷地。"},{"word":"depopulation","structure":"de- (away) + population","meaning":"the loss of people","meaningCN":"人口流失","example":"Depopulation closed the village school.","exampleCN":"人口流失使村校关闭。"},{"word":"grow","structure":"Old English growan (to grow)","meaning":"to increase, to develop","meaningCN":"增长；生长","example":"The town grew along the river.","exampleCN":"这座镇沿着河生长。"},{"word":"growth","structure":"grow + -th (result)","meaning":"increase; development","meaningCN":"增长；生长","example":"Growth slowed after the drought.","exampleCN":"干旱之后增长放缓。"},{"word":"population growth","structure":"population + growth","meaning":"a rise in numbers","meaningCN":"数量的上升","example":"Population growth outpaced the water supply.","exampleCN":"人口增长超出了供水能力。"},{"word":"growing","structure":"grow + -ing (participle)","meaning":"increasing","meaningCN":"不断增长的","example":"A growing population needs more housing.","exampleCN":"不断增长的人口需要更多住房。"}],"latinEntries":[{"word":"populus","structure":"populus, populi (m., second declension)","meaning":"people, nation","meaningCN":"人民；民族"},{"word":"populatio","structure":"populatio, populationis (f., third declension)","meaning":"a peopling; a multitude","meaningCN":"使有人居住；人群"},{"word":"populosus","structure":"populosus, populosa, populosum (adjective)","meaning":"full of people","meaningCN":"人口众多的"}]}},{"word":"population density","ipa_uk":"/ˌpɒpjʊˈleɪʃn ˈdensəti/","ipa_us":"/ˌpɑːpjəˈleɪʃən ˈdensəti/","definition_zh":"人口密度；种群密度","definition_en":"the number of people or organisms in a given area, usually per square kilometre","core_image":"同样大的两格方框，一格挤满小点，另一格只有零星几点","scene":"The district's population density doubled within a decade.","sceneCN":"这里 population density 指「单位面积上的人口数」（第 1 个义项：每平方公里等面积内居住的人数）；句意为该区的人口密度在十年内翻倍。图中可辨识物件：等大的两格方框、密集的小点与稀疏的小点、比例尺、名册计数。","pos":[{"tag":"n.","zh":"人口密度；种群密度（不可数，指具体数值时可有复数 densities）"}],"collocations":[{"phrase":"high population density","zh":"高人口密度"},{"phrase":"low population density","zh":"低人口密度"},{"phrase":"population density map","zh":"人口密度图"},{"phrase":"average population density","zh":"平均人口密度"},{"phrase":"population density per square kilometre","zh":"每平方公里人口密度"},{"phrase":"density-dependent","zh":"密度制约的"}],"forms":[{"label":"复数（不同地区或不同数值）","form":"population densities"},{"label":"相关名词","form":"population（人口）"},{"label":"相关名词","form":"density（密度）"},{"label":"相关形容词","form":"dense（稠密的）"},{"label":"相关副词","form":"densely（稠密地）"},{"label":"反义说法","form":"sparse population（人口稀少）"}],"derivatives":[{"word":"dense","pos":"adj.","zh":"稠密的；浓厚的"},{"word":"densely","pos":"adv.","zh":"稠密地"},{"word":"density","pos":"n.","zh":"密度"},{"word":"densify","pos":"v.","zh":"使稠密化"},{"word":"population","pos":"n.","zh":"人口；种群"}],"senses":[{"no":"01","title":"People per unit of land","titleCN":"单位面积上的人口数","definition":"the number of people living in each unit of land area","definitionCN":"每一单位土地面积上居住的人数","example":"The district's population density doubled within a decade.","exampleCN":"该区的人口密度在十年内翻倍。","why":"population supplies the count and density supplies the division by area, so the phrase is simply people divided by space.","whyCN":"population 提供人数，density 提供按面积相除，因此这个短语就是人数除以空间。"},{"no":"02","title":"The arithmetic measure","titleCN":"算术密度：总人口除以总面积","definition":"total population divided by total land area, the simplest of the measures","definitionCN":"总人口除以总土地面积，是最简单的度量","example":"Arithmetic population density hides the fact that most of the land is desert.","exampleCN":"算术人口密度掩盖了大部分土地是沙漠这一事实。","why":"the plain quotient is easy to compute and easy to mislead, which is why geographers keep naming it separately.","whyCN":"这个朴素商数易算也易误导，因此地理学者要单独给它一个名称。"},{"no":"03","title":"People per farmable land","titleCN":"生理密度：人口除以可耕地","definition":"population divided by the area of arable land, showing pressure on farmland","definitionCN":"人口除以可耕地面积，显示对农田的压力","example":"Physiological population density is far higher than the arithmetic figure.","exampleCN":"生理人口密度远高于算术数字。","why":"swapping total land for arable land shows how many mouths depend on each field, which is the point of the second measure.","whyCN":"把总面积换成可耕地，就能看出每块田养多少张嘴，这正是第二种度量的用意。"},{"no":"04","title":"Farmers per farmland","titleCN":"农业密度：农业人口除以农地","definition":"the number of farmers per unit of farmland, an indicator of labour intensity","definitionCN":"每单位农地上的农民数，用以显示劳动集约程度","example":"Agricultural population density fell as machines replaced hands.","exampleCN":"机器取代人力后，农业人口密度下降。","why":"counting farmers rather than eaters measures labour intensity, so the same word serves a different question.","whyCN":"数农民而不是数吃饭的人，衡量的是劳动强度，因此同一个词服务另一个问题。"},{"no":"05","title":"Organisms per habitat area","titleCN":"生态密度：单位生境面积的个体数","definition":"the number of organisms of a species in each unit of habitat","definitionCN":"某一物种在每单位生境中的个体数","example":"Population density of the frogs peaked in the reed bed.","exampleCN":"这些蛙的种群密度在芦苇丛中达到峰值。","why":"ecologists divide by usable habitat rather than by map area, which is why the animal version often differs sharply from the human one.","whyCN":"生态学者除以可用生境而非地图面积，因此动物版本常与人版本差别很大。"},{"no":"06","title":"Crowding in built-up areas","titleCN":"建成区的拥挤程度","definition":"the intensity of people per built area, used in planning and housing","definitionCN":"每单位建成区的人口强度，用于规划与住房","example":"The city raised building heights to cut population density at ground level.","exampleCN":"这座城市提高建筑高度，以降低地面层的人口密度。","why":"planning divides by the built area rather than the whole municipal area, and vertical growth changes the quotient.","whyCN":"规划除以建成区而非整个市域，而向上生长会改变这个商数。"},{"no":"07","title":"Density-dependent effects","titleCN":"密度制约效应","definition":"the way crowding changes birth rates, death rates or disease spread","definitionCN":"拥挤程度如何改变出生率、死亡率或疾病传播","example":"Disease spreads faster where population density is high.","exampleCN":"人口密度高的地方疾病传播更快。","why":"when the number itself changes survival, biologists call the effect density-dependent, turning the measure into a cause.","whyCN":"当这个数字本身改变了存活，生物学家称之为密度制约，把度量变成了原因。"},{"no":"08","title":"A planning metric","titleCN":"规划指标：用于分区与配建","definition":"a figure used to set zoning, transport and service provision","definitionCN":"用于确定分区、交通与公共服务的指标","example":"The zoning code ties bus frequency to population density.","exampleCN":"分区规范把公交频次与人口密度挂钩。","why":"a number that can be mapped and compared becomes a rule of thumb for services, which is how it ends up in codes.","whyCN":"一个可制图、可比较的数字会成为配建经验法则，于是进入规范条文。"}],"etymology":{"intro":{"en":"Population is Latin populus 'people' through populatio; density comes from Latin densitas, from densus 'thick, crowded'. The phrase is modern. Dates are approximate.","cn":"population 经 populatio 来自拉丁 populus「人民」；density 来自拉丁 densitas，源自 densus「稠密、拥挤」。这个短语是近代组合。年代均为约数。"},"items":[{"era":"LATIN DENSUS","en":"Densus meant 'thick, crowded, close-set'. Its deeper origin is uncertain; the link sometimes drawn to a root meaning 'dense' is a reconstruction.","cn":"densus 意为「稠密、拥挤、排得紧」。其更深来源不确定；把它连到某个表示「稠密」的词根只是重构。"},{"era":"LATIN DENSITAS","en":"Densitas named thickness or closeness; English density entered in the sixteenth century through science.","cn":"densitas 指浓厚或紧密；英语 density 于 16 世纪经科学语境进入。"},{"era":"POPULUS AND POPULATIO","en":"Populus 'people' gave populatio 'a peopling, a multitude', and English population.","cn":"populus「人民」给出 populatio「人群、使有人居住」与英语 population。"},{"era":"MEASUREMENT ERA","en":"The compound population density spread in the nineteenth century, when censuses were mapped onto land area.","cn":"组合 population density 在 19 世纪扩散，当时人口普查结果被叠到土地面积上。"},{"era":"ECOLOGICAL EXTENSION","en":"The twentieth century extended the figure from people to animals and plants, giving the ecological sense.","cn":"20 世纪把这个数值从人扩展到动植物，形成生态义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest use of the exact compound is not precisely recorded, and the origins of densus and populus both remain unsettled.","cn":"来源不确定（首见年代）：这一确切组合的最早使用没有精确记录；densus 与 populus 的来源都仍无定论。"}]},"similar":{"note":{"en":"Group one holds measures of density that are constantly confused in geography; group two holds related spatial ideas.","cn":"第一组是地理学中常被混淆的几种密度度量；第二组是相关的空间概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"arithmetic density","ipa":"/əˈrɪθmətɪk ˈdensəti/","tag":"total over total","definition":"Total population divided by total area; it ignores which land can actually be used.","definitionCN":"总人口除以总面积；不考虑土地是否可用。"},{"word":"physiological density","ipa":"/ˌfɪziəˈlɒdʒɪkl ˈdensəti/","tag":"people over farmland","definition":"Population divided by arable land; it measures pressure on the land that feeds people.","definitionCN":"人口除以可耕地；衡量养活人口的土地承受的压力。"},{"word":"agricultural density","ipa":"/ˌæɡrɪˈkʌltʃərəl ˈdensəti/","tag":"farmers over farmland","definition":"Farmers divided by farmland; it indicates how labour-intensive farming is.","definitionCN":"农民数除以农地；显示农业的劳动集约程度。"},{"word":"ecological density","ipa":"/ˌiːkəˈlɒdʒɪkl ˈdensəti/","tag":"organisms over habitat","definition":"Organisms divided by the area they can actually inhabit; it is the biological form of the measure.","definitionCN":"生物数除以它们实际可栖居的面积；是这一度量的生物学形态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"crowding","ipa":"/ˈkraʊdɪŋ/","tag":"felt pressure","definition":"The experience of too many people in too little space; density is the number, crowding is its effect.","definitionCN":"指空间过小而人过多的体验；density 是数字，crowding 是其效果。"},{"word":"concentration","ipa":"/ˌkɒnsnˈtreɪʃn/","tag":"clustering","definition":"The gathering of things into one area; it names the pattern, not the rate per unit.","definitionCN":"指事物聚到一处；命名格局，而非单位面积比率。"},{"word":"distribution","ipa":"/ˌdɪstrɪˈbjuːʃn/","tag":"where they are","definition":"How a population is spread across space; density is one number from that spread.","definitionCN":"指人口在空间上如何散布；density 是这一散布得出的一个数。"},{"word":"carrying capacity","ipa":"/ˈkæriɪŋ kəˈpæsəti/","tag":"the limit","definition":"The maximum number an area can support; density is where the population actually sits.","definitionCN":"指某地可支撑的最大数量；density 是种群实际所处的位置。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"population 'count' + density 'thickness': how thick people lie on the land.","cn":"population「计数」+ density「浓稠度」：人在地上铺得多厚。"},{"en":"The family runs dense, densely, density, densify, population.","cn":"同族词包括 dense、densely、density、densify、population。"},{"en":"Fixed phrases mark the measures: arithmetic density, physiological density, agricultural density.","cn":"固定搭配标出各种度量：算术密度、生理密度、农业密度。"},{"en":"The unit is always people per area, so the phrase is a division problem.","cn":"单位始终是每面积多少人，因此这个短语就是一道除法。"},{"en":"Ecologists say density-dependent when crowding itself changes survival.","cn":"生态学用 density-dependent 指拥挤本身改变了存活。"}],"abstract":[{"en":"Picture two equal boxes, one packed with dots and one nearly empty.","cn":"想象两个同样大的方框，一个挤满小点，一个几乎空白。"},{"en":"Picture a lift that holds twelve and thirty people get in.","cn":"想象一部限载十二人的电梯挤进三十人。"},{"en":"Picture a map where colour deepens as the dots multiply.","cn":"想象一张地图，小点越多颜色越深。"}]},"examples":[{"en":"Population density is highest along the river mouths.","cn":"人口密度在河口一带最高。"},{"en":"The map shades population density in five bands.","cn":"这幅图用五个色阶表示人口密度。"},{"en":"High population density makes contact tracing harder.","cn":"高人口密度让接触者追踪更困难。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「population（人口）+ density（密度）」——同样大的地方挤了多少人 → 人口密度","word":"population density"},"root":"拉丁 populus「人民」（来源不确定）+ populatio「人群」+ 拉丁 densitas「浓厚」来自 densus「稠密」（更深来源不确定）；英语 population density。","sensesIntro":{"en":"Eight senses follow one division: a count is divided by an area, and the quotient is then read as arithmetic, physiological, agricultural, ecological, urban, epidemiological and finally as a planning number.","cn":"八个义项沿同一次除法展开：用面积去除人数，所得的商再被读成算术、生理、农业、生态、城市、流行病学，最后成为规划数字。"},"semanticMap":{"core":{"en":"CORE IMAGE: two equal boxes, one crowded with dots and one sparse.","cn":"核心意象：两个同样大的方框，一个挤满小点，一个稀疏。"},"chain":["PEOPLE COUNTED","AREA MEASURED","DIVISION MADE","FARMLAND VERSION","HABITAT VERSION","CROWDING EFFECT"],"branches":[{"senses":"S1 · S2","en":"PLAIN DIVISION: total people over total land, the first measure taught.","cn":"朴素除法：总人口除以总土地，最先教的那个度量。"},{"senses":"S3 · S4","en":"LAND THAT FEEDS: divide by arable land, and again by the farmers on it.","cn":"养人的土地：先除以可耕地，再除以地上的农民。"},{"senses":"S5","en":"HABITAT VERSION: the same quotient applied to animals and plants.","cn":"生境版本：同一商数用于动植物。"},{"senses":"S6 · S8","en":"BUILT SPACE AND PLANS: heights, zoning and bus routes respond to the number.","cn":"建成空间与规划：层高、分区与公交线路都随这个数调整。"},{"senses":"S7","en":"DENSITY-DEPENDENT: crowding itself changes births, deaths and contagion.","cn":"密度制约：拥挤本身改变出生、死亡与传染。"}]},"affixes":{"intro":{"en":"The phrase joins two Latin-derived nouns; density carries the suffix -ity, which turns the adjective densus into a measurable noun.","cn":"这个短语把两个源自拉丁的名词并置；density 带后缀 -ity，把形容词 densus 变成可度量的名词。"},"latinIntro":{"en":"Latin densus gives dense, densely, density and densify; populus gives population and populous.","cn":"拉丁 densus 衍生 dense、densely、density 与 densify；populus 衍生 population 与 populous。"},"items":[{"word":"populus","structure":"populus, populi (m., second declension)","meaning":"people","meaningCN":"人民","example":"The noun names a people as a body.","exampleCN":"这个名词把人民视为整体。"},{"word":"population","structure":"populatio (Latin) -> population","meaning":"the people of a place","meaningCN":"某地的人口","example":"Population rose along the coast.","exampleCN":"沿海人口上升。"},{"word":"densus","structure":"densus, densa, densum (adjective)","meaning":"thick, crowded","meaningCN":"稠密的；拥挤的","example":"The Latin adjective describes close packing.","exampleCN":"这个拉丁形容词描述紧密排布。"},{"word":"density","structure":"densus + -ity (state)","meaning":"thickness; amount per unit","meaningCN":"浓厚；单位量","example":"The density of the forest blocks light.","exampleCN":"森林的密度挡住了光。"},{"word":"dense","structure":"densus (adjective) -> dense","meaning":"thickly packed","meaningCN":"稠密的","example":"A dense crowd filled the square.","exampleCN":"密集的人群填满广场。"},{"word":"densely","structure":"dense + -ly (manner)","meaning":"in a crowded way","meaningCN":"稠密地","example":"The valley is densely settled.","exampleCN":"这条谷地人口稠密。"},{"word":"densify","structure":"dense + -ify (to make)","meaning":"to make more crowded","meaningCN":"使稠密化","example":"The plan densifies the inner suburbs.","exampleCN":"该计划使近郊更稠密。"},{"word":"population density","structure":"population + density","meaning":"people per area","meaningCN":"每面积的人数","example":"Population density doubled in a decade.","exampleCN":"人口密度十年翻倍。"},{"word":"densely populated","structure":"densely + populated","meaning":"having many people per area","meaningCN":"人口稠密的","example":"The delta is densely populated.","exampleCN":"三角洲人口稠密。"}],"latinEntries":[{"word":"densus","structure":"densus, densa, densum (adjective)","meaning":"thick, crowded","meaningCN":"稠密的；拥挤的"},{"word":"densitas","structure":"densitas, densitatis (f., third declension)","meaning":"thickness, closeness","meaningCN":"浓厚；紧密"},{"word":"populus","structure":"populus, populi (m., second declension)","meaning":"people","meaningCN":"人民"},{"word":"populatio","structure":"populatio, populationis (f., third declension)","meaning":"a peopling; a multitude","meaningCN":"人群"}]}},{"word":"population decline","ipa_uk":"/ˌpɒpjʊˈleɪʃn dɪˈklaɪn/","ipa_us":"/ˌpɑːpjəˈleɪʃən dɪˈklaɪn/","definition_zh":"人口下降；（生物）种群下降","definition_en":"a fall in the number of people or organisms in a place or group","core_image":"一间村校的窗户一扇扇钉上木板，操场上的草慢慢长高","scene":"Population decline has closed schools across the rural county.","sceneCN":"这里 population decline 指「人口数量的持续减少」（第 1 个义项：某地居民总数下降）；句意为人口下降使这个农业县多所学校关停。图中可辨识物件：钉上木板的校窗、长草的操场、空荡的街道、逐年缩短的柱状图。","pos":[{"tag":"n.","zh":"人口下降；种群下降（不可数，指具体一次下降时偶作可数）"}],"collocations":[{"phrase":"rapid population decline","zh":"人口快速下降"},{"phrase":"population decline rate","zh":"人口下降速率"},{"phrase":"rural population decline","zh":"农村人口下降"},{"phrase":"halt population decline","zh":"遏止人口下降"},{"phrase":"population decline and ageing","zh":"人口下降与老龄化"},{"phrase":"steep population decline","zh":"急剧的人口下降"},{"phrase":"reverse population decline","zh":"扭转人口下降"}],"forms":[{"label":"复数（少见，指多次局部下降）","form":"population declines"},{"label":"相关名词","form":"population（人口）"},{"label":"相关动词","form":"decline（下降；拒绝）"},{"label":"相关名词","form":"decline（下降）"},{"label":"反义说法","form":"population growth（人口增长）"}],"derivatives":[{"word":"decline","pos":"v./n.","zh":"下降；衰退 / 下降"},{"word":"declining","pos":"adj.","zh":"下降中的；衰退的"},{"word":"declination","pos":"n.","zh":"倾斜；偏差"},{"word":"population","pos":"n.","zh":"人口；种群"},{"word":"depopulation","pos":"n.","zh":"人口流失"}],"senses":[{"no":"01","title":"Fewer people in a place","titleCN":"某地人口数量的减少","definition":"a fall in the number of people living in a place","definitionCN":"某地居住人数的下降","example":"Population decline has closed schools across the rural county.","exampleCN":"人口下降使这个农业县多所学校关停。","why":"decline means to bend downward, so the phrase states that the count is going down rather than up.","whyCN":"decline 意为「向下弯」，因此这个短语陈述的是数目在向下走而非向上。"},{"no":"02","title":"Falling below replacement","titleCN":"低于更替水平的长期下降","definition":"a sustained fall in births so that each generation is smaller than the one before","definitionCN":"出生持续减少，使每一代都比上一代更小","example":"Population decline set in once births fell below two per woman.","exampleCN":"出生数降到每名女性不足两个之后，人口下降开始出现。","why":"a population replaces itself only at about two births per woman, so a sustained fall below that line is decline built into the structure.","whyCN":"人口只有在每名女性约生育两个时才能自我更替，长期低于这条线，下降就写进了结构。"},{"no":"03","title":"Loss through emigration","titleCN":"迁出造成的本地下降","definition":"a fall caused by more people leaving than arriving","definitionCN":"迁出多于迁入所造成的下降","example":"Population decline in the uplands followed the closure of the mines.","exampleCN":"矿区关闭后，高地出现了人口下降。","why":"a place can lose people without any fall in births, simply because more leave than arrive.","whyCN":"一个地方即使出生数没有下降，也会因迁出多于迁入而失去人口。"},{"no":"04","title":"A species losing numbers","titleCN":"物种数量的下降","definition":"a fall in the numbers of a wild species","definitionCN":"野生种群数量的减少","example":"The survey recorded a steep population decline among the bees.","exampleCN":"调查记录到蜜蜂数量的急剧下降。","why":"the phrase is not restricted to people, since a population in ecology is any countable group of organisms.","whyCN":"这个短语并不限于人，因为生态学中的种群是任何可计数的生物群体。"},{"no":"05","title":"The measured rate of loss","titleCN":"可测量的下降速率","definition":"the percentage by which numbers fall in a given period","definitionCN":"一定时期内数量下降的百分比","example":"The population decline rate reached two percent a year.","exampleCN":"人口下降速率达到每年百分之二。","why":"once the fall is measured against time, it can be compared with growth rates and with other places.","whyCN":"一旦把下跌按时间计量，就能与增长率及其他地方比较。"},{"no":"06","title":"The economic consequence","titleCN":"经济后果：需求与税基收缩","definition":"the shrinking of demand, tax base and services that follows fewer people","definitionCN":"人口减少带来的需求、税基与服务收缩","example":"Population decline left the region with empty housing and fewer doctors.","exampleCN":"人口下降让这个地区留下空置住房与更少的医生。","why":"fewer residents mean fewer customers, a smaller tax base and services that can no longer be staffed.","whyCN":"居民减少意味着顾客减少、税基缩小，服务也再难配齐人员。"},{"no":"07","title":"A policy worry","titleCN":"政策议题：下降与老龄化","definition":"the framing of falling numbers as a problem for pensions and defence","definitionCN":"把数量下降框定为养老金与国防问题","example":"The white paper treats population decline as a planning risk.","exampleCN":"这份白皮书把人口下降视为规划风险。","why":"governments reframe a demographic fact as a risk to pensions and defence, which is how the phrase enters policy.","whyCN":"政府把一个人口事实重新框定为养老金与国防风险，这个短语便由此进入政策。"},{"no":"08","title":"A sharp crash","titleCN":"剧降：短时间内的崩溃式下跌","definition":"a sudden and severe drop in numbers, as after a disaster","definitionCN":"数量在灾难等之后出现的骤然大幅下跌","example":"The population decline after the eruption was near total.","exampleCN":"火山喷发之后，种群下降几乎是彻底的。","why":"the same noun covers the extreme case, where decline becomes a crash rather than a slow trend.","whyCN":"同一个名词也涵盖极端情形：下降成为崩溃，而非缓慢趋势。"}],"etymology":{"intro":{"en":"Population is Latin populus through populatio; decline comes from Latin declinare, de- 'down' plus clinare 'to bend'. The phrase is modern. Dates are approximate.","cn":"population 经 populatio 来自拉丁 populus；decline 来自拉丁 declinare，由 de-「向下」与 clinare「弯」构成。这个短语是近代组合。年代均为约数。"},"items":[{"era":"LATIN CLINARE","en":"Clinare meant 'to bend, lean', related to Greek klinein 'to lean'; the family also gives incline and recline.","cn":"clinare 意为「弯、倾」，与希腊 klinein「倾靠」相关；同一词族还给出 incline 与 recline。"},{"era":"LATIN DECLINARE","en":"De- 'down' plus clinare gave declinare 'to bend away, turn aside', and figuratively to fall off or worsen.","cn":"de-「向下」加 clinare 得 declinare「弯开、转向一旁」，比喻义为衰退、变坏。"},{"era":"ENGLISH DECLINE","en":"English took decline in the fourteenth century, both as a verb of bending away and as a noun of worsening.","cn":"英语在 14 世纪吸收 decline，既作「偏离、弯开」的动词，也作「变坏」的名词。"},{"era":"POPULATION AND DECLINE","en":"The fixed phrase population decline spread in the twentieth century, as censuses made decades comparable and rural losses visible.","cn":"固定短语 population decline 在 20 世纪扩散，人口普查使跨年代比较与农村流失变得可见。"},{"era":"POLICY ERA","en":"Late twentieth-century debates over ageing societies made the phrase a standard term in economics and planning.","cn":"20 世纪后期关于老龄化社会的辩论，使这个短语成为经济学与规划的标准术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest use of the exact phrase is not precisely recorded, and the deeper origin of clinare is a reconstruction.","cn":"来源不确定（首见年代）：这一确切短语的最早使用没有精确记录；clinare 的更深来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds words of the clinare family that look alike; group two holds terms for numbers falling.","cn":"第一组是同出 clinare 词族、外形相近的词；第二组是表示数量下降的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decline","ipa":"/dɪˈklaɪn/","tag":"the base word","definition":"The verb and noun of going down; it also means to refuse politely, a sense the compound never carries.","definitionCN":"指下降的动词与名词；另有礼貌拒绝义，而这一组合从不带该义。"},{"word":"incline","ipa":"/ɪnˈklaɪn/","tag":"lean toward","definition":"In- 'toward' plus clinare: to lean or to tend toward something, the opposite direction of motion.","definitionCN":"in-「朝向」加 clinare：向某物倾斜或倾向于，方向相反。"},{"word":"recline","ipa":"/rɪˈklaɪn/","tag":"lean back","definition":"Re- 'back' plus clinare: to lean backward, as a seat does. Nothing is falling in number.","definitionCN":"re-「向后」加 clinare：向后靠，如座椅后仰。与数量下降无关。"},{"word":"declination","ipa":"/ˌdek lɪˈneɪʃn/","tag":"angle, not a trend","definition":"A downward angle, as of a magnetic needle; it is a technical measurement, not a fall in population.","definitionCN":"指下倾角，如磁针的偏角；是技术度量，不是人口下降。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decrease","ipa":"/diːˈkriːs/","tag":"plain verb of falling","definition":"A neutral word for becoming less; it lacks the sense of a sustained trend that decline carries.","definitionCN":"指变少的中性词；不像 decline 那样含持续趋势之意。"},{"word":"depopulation","ipa":"/ˌdiːpɒpjʊˈleɪʃn/","tag":"the loss of people","definition":"The process of a place losing its people; it is the human half of population decline.","definitionCN":"指某地失去人口的过程；是人口下降的人的那一半。"},{"word":"shrinkage","ipa":"/ˈʃrɪŋkɪdʒ/","tag":"size getting smaller","definition":"A reduction in physical size or amount; it suits economies and garments as much as populations.","definitionCN":"指体积或数量的缩小；可用于经济、衣物，也可用于人口。"},{"word":"collapse","ipa":"/kəˈlæps/","tag":"sudden failure","definition":"A sudden fall or breakdown; it is the extreme case of decline, not the ordinary one.","definitionCN":"指骤然下跌或崩溃；是下降的极端情形，而非通常情形。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"population 'count' + decline 'bend down': the count bending downward.","cn":"population「计数」+ decline「向下弯」：数目向下弯。"},{"en":"The family runs decline, declining, declination, population, depopulation.","cn":"同族词包括 decline、declining、declination、population、depopulation。"},{"en":"Fixed phrases mark the senses: rural population decline, population decline rate, halt population decline.","cn":"固定搭配标出各义项：农村人口下降、人口下降速率、遏止人口下降。"},{"en":"The verb decline also means to refuse; the noun in this phrase never does.","cn":"动词 decline 也可指拒绝；但这个短语里的名词从不表示拒绝。"},{"en":"The same bend appears in incline and recline, pointing other ways.","cn":"同一个「弯」也出现在 incline 与 recline 中，方向不同。"}],"abstract":[{"en":"Picture a school with boards over every window.","cn":"想象一所每扇窗都钉上木板的学校。"},{"en":"Picture a bar chart where each year is shorter than the last.","cn":"想象一张柱状图，每根柱子都比前一年短。"},{"en":"Picture a village where the only sound is grass growing.","cn":"想象一个村子，唯一的声响是草在长。"}]},"examples":[{"en":"Population decline has emptied half the apartments in the town.","cn":"人口下降使镇上一半公寓空置。"},{"en":"The report links population decline to a falling birth rate.","cn":"报告把人口下降与出生率下滑联系起来。"},{"en":"Fish population decline followed the loss of the shallows.","cn":"浅滩消失之后，鱼群数量出现下降。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「population（人口）+ decline（向下弯）」——数目一路向下 → 人口下降","word":"population decline"},"root":"拉丁 populus「人民」（来源不确定）+ populatio「人群」+ 拉丁 declinare「弯开、下倾」= de-「向下」+ clinare「弯」；英语 population decline。","sensesIntro":{"en":"Eight senses follow one movement: a count bends downward, and that bend is then read as a birth shortfall, an emigration drain, a wildlife loss, a rate, an economic squeeze, a policy problem and a crash.","cn":"八个义项沿同一个动作展开：某个计数向下弯，这个弯再被读成出生不足、迁出流失、野生种群减少、速率、经济收缩、政策难题与崩溃。"},"semanticMap":{"core":{"en":"CORE IMAGE: a village school boarded up while the grass grows in the yard.","cn":"核心意象：村校钉上木板，操场上的草在长。"},"chain":["COUNT FALLS","BIRTHS SHORT","PEOPLE LEAVE","SPECIES LOSE","RATE MEASURED","CRASH ARRIVES"],"branches":[{"senses":"S1 · S5","en":"FALL AND RATE: the bare drop, then the same drop expressed per year.","cn":"下降与速率：先是单纯下跌，再是换算成每年的同一跌幅。"},{"senses":"S2 · S3","en":"TWO DRAINS: too few births, or too many departures.","cn":"两个流失口：出生太少，或离开太多。"},{"senses":"S4","en":"NON-HUMAN LOSS: bees and fish decline by the same grammar.","cn":"非人类的减少：蜜蜂与鱼用同一套说法下降。"},{"senses":"S6 · S7","en":"CONSEQUENCES AND POLICY: empty housing and strained pensions follow the numbers.","cn":"后果与政策：空置住房与吃紧的养老金随数字而来。"},{"senses":"S8","en":"CRASH: decline pushed to its extreme after a disaster.","cn":"崩溃：灾难之后下降被推到极端。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of people to a Latin verb-turned-noun of bending down; de- and -are are visible across the declinare family.","cn":"这个短语把表示人民的拉丁名词与表示「向下弯」的拉丁动名词并置；de- 与 -are 在 declinare 词族中都看得见。"},"latinIntro":{"en":"Latin declinare gives decline, declination, incline and recline; populus gives population and depopulation.","cn":"拉丁 declinare 衍生 decline、declination、incline 与 recline；populus 衍生 population 与 depopulation。"},"items":[{"word":"de-","structure":"de- (Latin prefix, 'down, away')","meaning":"down; away","meaningCN":"向下；离开","example":"The prefix marks a downward motion.","exampleCN":"前缀标记向下的动作。"},{"word":"clinare","structure":"clinare (Latin verb, first conjugation)","meaning":"to bend, lean","meaningCN":"弯；倾","example":"The root supplies the bending image.","exampleCN":"词根提供「弯」的意象。"},{"word":"decline","structure":"de- + clinare","meaning":"to bend down; to worsen","meaningCN":"向下弯；变坏","example":"Sales declined after midsummer.","exampleCN":"仲夏之后销量下滑。"},{"word":"declining","structure":"decline + -ing (participle)","meaning":"falling; worsening","meaningCN":"下降中的","example":"A declining town loses its bus route.","exampleCN":"衰退中的镇子会失去公交线路。"},{"word":"declination","structure":"declinare + -ation (result)","meaning":"a downward angle","meaningCN":"下倾角；偏角","example":"The needle's declination was measured.","exampleCN":"磁针的偏角被测量了。"},{"word":"population","structure":"populatio (Latin) -> population","meaning":"the people of a place","meaningCN":"某地的人口","example":"Population fell for a third year.","exampleCN":"人口连续第三年下降。"},{"word":"depopulation","structure":"de- (away) + population","meaning":"the loss of people from a place","meaningCN":"人口流失","example":"Depopulation emptied the upland farms.","exampleCN":"人口流失使高地农场空置。"},{"word":"population decline","structure":"population + decline","meaning":"a fall in numbers","meaningCN":"数量的下降","example":"Population decline closed the schools.","exampleCN":"人口下降使学校关停。"},{"word":"incline","structure":"in- (toward) + clinare","meaning":"to lean toward","meaningCN":"倾向；倾斜","example":"The path inclines toward the river.","exampleCN":"小路朝河倾斜。"}],"latinEntries":[{"word":"clinare","structure":"clinare, clinavi, clinatum (verb, first conjugation)","meaning":"to bend, lean","meaningCN":"弯；倾"},{"word":"declinare","structure":"declinare, declinavi, declinatum (verb, first conjugation)","meaning":"to bend away, turn aside","meaningCN":"弯开；转向"},{"word":"populus","structure":"populus, populi (m., second declension)","meaning":"people","meaningCN":"人民"},{"word":"populatio","structure":"populatio, populationis (f., third declension)","meaning":"a peopling; a multitude","meaningCN":"人群"}]}},{"word":"demographic","ipa_uk":"/ˌdeməˈɡræfɪk/","ipa_us":"/ˌdeməˈɡræfɪk/","definition_zh":"人口统计的；人口结构的；特定人群（名词义）","definition_en":"relating to the structure and statistics of populations, or a group defined by shared population traits","core_image":"一张人口金字塔图，底层宽、顶层窄，每条横杠代表一个年龄组","scene":"The survey split respondents by demographic group before comparing answers.","sceneCN":"这里 demographic 作定语，指「按人口特征划分的」（第 3 个义项：由年龄、收入等共同特征界定的人群）；句意为调查先把受访者按人口特征分组，再比较答案。图中可辨识物件：金字塔图、年龄横杠、分组标签、统计表。","pos":[{"tag":"adj.","zh":"人口统计的；人口结构的；人口特征的"},{"tag":"n.","zh":"特定人群；人口群体（如某年龄或收入层）"}],"collocations":[{"phrase":"demographic group","zh":"人口群体"},{"phrase":"demographic change","zh":"人口结构变化"},{"phrase":"demographic data","zh":"人口统计数据"},{"phrase":"demographic transition","zh":"人口转变"},{"phrase":"demographic dividend","zh":"人口红利"},{"phrase":"target demographic","zh":"目标人群"},{"phrase":"demographic profile","zh":"人口特征画像"}],"forms":[{"label":"名词（人口统计数据）","form":"demographics（常用复数）"},{"label":"单数名词（较少用）","form":"demographic（一个群体或一份统计）"},{"label":"副词","form":"demographically（从人口结构上看）"},{"label":"名词（人口学）","form":"demography（人口学）"},{"label":"名词（人口学家）","form":"demographer（人口学家）"}],"derivatives":[{"word":"demography","pos":"n.","zh":"人口学；人口统计"},{"word":"demographer","pos":"n.","zh":"人口学家"},{"word":"demographics","pos":"n.","zh":"人口统计数据；人群构成"},{"word":"demographically","pos":"adv.","zh":"从人口结构上看"},{"word":"demos","pos":"n.","zh":"（希腊语）民众；人民"}],"senses":[{"no":"01","title":"Relating to population structure","titleCN":"与人口结构有关的","definition":"connected with the size, age and make-up of a population","definitionCN":"与人口的规模、年龄与构成有关","example":"Demographic change has left more pensioners than children.","exampleCN":"人口结构变化使领取养老金的人多于儿童。","why":"dēmos 'people' plus graphein 'write' gives the study of populations, and the adjective simply describes whatever belongs to that study.","whyCN":"dēmos「民众」加 graphein「书写」构成对人口的研究，形容词就描述属于这项研究的一切。"},{"no":"02","title":"Relating to population statistics","titleCN":"与人口统计有关的","definition":"connected with the numbers collected about births, deaths, migration and age","definitionCN":"与出生、死亡、迁移与年龄等收集到的数字有关","example":"The report opens with a demographic table by region.","exampleCN":"报告开头是一张分地区的人口统计表。","why":"the adjective covers both the structure and the figures, so it can sit before data as easily as before change.","whyCN":"这个形容词同时涵盖结构与数字，因此既能修饰 change，也能修饰 data。"},{"no":"03","title":"A group with shared traits","titleCN":"由共同特征界定的人群（名词义）","definition":"a section of a population defined by age, income, education or similar traits","definitionCN":"按年龄、收入、教育等特征划分出来的一部分人口","example":"The survey split respondents by demographic group before comparing answers.","exampleCN":"调查先把受访者按人口特征分组，再比较答案。","why":"marketers needed a countable slice of the population, so the adjective became a noun naming that slice.","whyCN":"营销需要人口中可数的一块，于是形容词转为名词，命名那一块。"},{"no":"04","title":"The collected figures","titleCN":"收集起来的统计数据","definition":"the statistics themselves, usually in the plural demographics","definitionCN":"指统计数字本身，通常用复数 demographics","example":"The demographics show a young city growing older.","exampleCN":"统计数据显示，一座年轻的城市正在变老。","why":"once the figures are habitually referred to in the plural, demographics becomes a noun in its own right.","whyCN":"当这些数字习惯上用复数指称，demographics 就独立成为名词。"},{"no":"05","title":"The transition model","titleCN":"人口转变模型中的用法","definition":"belonging to the model that traces a society from high to low birth and death rates","definitionCN":"属于描述社会由高出生高死亡转向低出生低死亡的模式","example":"Demographic transition explains the lag between falling deaths and falling births.","exampleCN":"人口转变解释了死亡下降与出生下降之间的时间差。","why":"the model needed a fixed name, and the adjective supplied one that fits every stage of the shift.","whyCN":"模式需要一个固定名称，这个形容词正好提供一个能套住各阶段的名称。"},{"no":"06","title":"A dividend from age structure","titleCN":"人口红利：劳动年龄人口占比高带来的增益","definition":"the economic gain a country receives when working-age adults outnumber dependants","definitionCN":"劳动年龄成年人多于受抚养者时，国家获得的经济增益","example":"The demographic dividend lasted two decades.","exampleCN":"人口红利持续了二十年。","why":"economists priced the age structure, so a bulge of workers became a dividend to be spent.","whyCN":"经济学家给年龄结构定了价，于是劳动力高峰成了一份可以花掉的红利。"},{"no":"07","title":"Ageing and shrinking","titleCN":"人口老龄化与收缩","definition":"belonging to the trend of older populations and fewer births","definitionCN":"属于人口老化、出生减少的趋势","example":"Demographic ageing is reshaping the labour market.","exampleCN":"人口老龄化正在重塑劳动力市场。","why":"the adjective attaches to any trend defined by the age profile, and ageing is now the dominant one.","whyCN":"这个形容词可接任何由年龄结构定义的走势，而老龄化如今是主要那一个。"},{"no":"08","title":"A market segment label","titleCN":"市场细分标签","definition":"used by business to describe the slice of customers a product is aimed at","definitionCN":"商业用来描述产品针对的那一部分顾客","example":"The app was built for a younger demographic.","exampleCN":"这款应用是为更年轻的人群打造的。","why":"segmentation turned the adjective into a targeting word, and the noun became shorthand for the audience itself.","whyCN":"市场细分把这个形容词变成定向用词，名词则成了受众本身的简称。"}],"etymology":{"intro":{"en":"Demographic combines Greek dēmos 'the people' with -graphic from graphein 'to write'. Demography was coined in 1855 by Achille Guillard. Dates are approximate.","cn":"demographic 把希腊 dēmos「民众」与来自 graphein「书写」的 -graphic 结合。demography 由 Achille Guillard 于 1855 年造出。年代均为约数。"},"items":[{"era":"GREEK DEMOS","en":"Dēmos meant 'the people, the common people' and also named a district; it is the root of democracy as well as demography.","cn":"dēmos 意为「民众、平民」，也指一个行政区；它既是 demography 的词根，也是 democracy 的词根。"},{"era":"GREEK GRAPHEIN","en":"Graphein meant 'to write, to draw'; with -ia it made words for a field of writing or study, as in geography.","cn":"graphein 意为「书写、刻画」；加 -ia 构成表示某一书写或研究领域的词，如 geography。"},{"era":"COINAGE OF DEMOGRAPHY","en":"The noun demography is generally credited to Achille Guillard, who used démographie in a work of 1855.","cn":"名词 demography 一般归功于 Achille Guillard，他在 1855 年的一部著作中使用了 démographie。"},{"era":"THE ADJECTIVE","en":"The adjective demographic followed in the later nineteenth century, and the plural noun demographics spread in the twentieth as market research grew.","cn":"形容词 demographic 在 19 世纪后期出现；复数名词 demographics 随 20 世纪市场研究的发展而扩散。"},{"era":"POLICY USE","en":"The twentieth century added fixed phrases such as demographic transition and demographic dividend, turning the word into a policy instrument.","cn":"20 世纪又增添了 demographic transition 与 demographic dividend 等固定说法，使这个词成为政策工具。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest English use of the adjective is not precisely recorded, and the exact month of Guillard's coinage is not established.","cn":"来源不确定（首见年代）：该形容词在英语中的最早使用没有精确记录；Guillard 造词的确切月份亦无定论。"}]},"similar":{"note":{"en":"Group one holds words of the same demo- and -graphy stock that are constantly swapped; group two holds terms for describing groups of people.","cn":"第一组是同出 demo- 与 -graphy 词干、常被互换的词；第二组是描述人群的其他术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"demography","ipa":"/dɪˈmɒɡrəfi/","tag":"the field","definition":"The discipline that studies populations; demographic is the adjective belonging to it.","definitionCN":"指研究人口的学科；demographic 是属于它的形容词。"},{"word":"demographics","ipa":"/ˌdeməˈɡræfɪks/","tag":"the data or the slices","definition":"The plural noun for population statistics or for the groups they describe, as in the demographics of a city.","definitionCN":"复数名词，指人口统计数据或其所描述的群体，如一座城市的人群构成。"},{"word":"demographer","ipa":"/dɪˈmɒɡrəfə/","tag":"the person","definition":"A person who studies populations; the word names a profession, not a statistic.","definitionCN":"指研究人口的人；命名一种职业，而非一项统计。"},{"word":"demographic","ipa":"/ˌdeməˈɡræfɪk/","tag":"adjective and segment","definition":"The form used before a noun, as in demographic data, and also a countable market segment.","definitionCN":"用于名词前的形式，如人口统计数据；也可作可数的市场细分人群。"}]},{"heading":"NEAR MEANING","entries":[{"word":"population","ipa":"/ˌpɒpjʊˈleɪʃn/","tag":"the people themselves","definition":"The people counted; demographic describes their structure rather than naming them.","definitionCN":"指被计数的人；demographic 描述其结构，而非命名其人。"},{"word":"statistical","ipa":"/stəˈtɪstɪkl/","tag":"about numbers","definition":"Relating to statistics in general; demographic narrows this to population figures.","definitionCN":"泛指与统计有关；demographic 把它限定到人口数字。"},{"word":"socio-economic","ipa":"/ˌsəʊsiəʊ ˌiːkəˈnɒmɪk/","tag":"class and income","definition":"Combining social and economic position; demographic covers age and household too.","definitionCN":"结合社会与经济地位；demographic 还涵盖年龄与家庭。"},{"word":"census","ipa":"/ˈsensəs/","tag":"the count itself","definition":"The official counting of a population; demographic work uses it but is not identical with it.","definitionCN":"指官方的人口清点；人口统计工作会使用它，但并不等同于它。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"demo- 'people' + -graphic 'written': written down about the people.","cn":"demo-「民众」+ -graphic「书写」：关于民众的记录。"},{"en":"The family runs demography, demographer, demographic, demographics, demographically.","cn":"同族词包括 demography、demographer、demographic、demographics、demographically。"},{"en":"Fixed phrases mark the policy sense: demographic transition, demographic dividend, demographic ageing.","cn":"固定搭配标出政策义：人口转变、人口红利、人口老龄化。"},{"en":"The plural demographics usually means the figures, the singular a segment.","cn":"复数 demographics 多指数据，单数多指某一人群。"},{"en":"The same dēmos root appears in democracy and in epidemic's cousin epidemiology.","cn":"同一 dēmos 词根也出现在 democracy 与 epidemiology 中。"}],"abstract":[{"en":"Picture a pyramid standing on a wide base and narrowing to a point.","cn":"想象一座金字塔底宽顶尖。"},{"en":"Picture a crowd sorted into coloured bands by age.","cn":"想象人群按年龄被分成不同颜色的带。"},{"en":"Picture a shop that knows exactly which age buys its bread.","cn":"想象一家店清楚哪个年龄层买它的面包。"}]},"examples":[{"en":"Demographic data show a sharp fall in the number of children.","cn":"人口统计数据表明儿童数量大幅下降。"},{"en":"The party's demographic base is older than it was a decade ago.","cn":"该党的人口基础比十年前更老。"},{"en":"Advertisers pay more for a young demographic.","cn":"广告商为年轻人群付更高的价。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「demo（人民）+ graphic（描绘）」——把人群按年龄收入画出来 → 人口统计的、人群的","word":"demographic"},"root":"希腊 dēmos「民众、平民」+ graphein「书写」（经 -graphic）；demography 由 Achille Guillard 于 1855 年造出。英语 demographic。","sensesIntro":{"en":"Eight senses follow one view: a population is drawn as a chart, and that view is then read as structure, statistics, a targeted segment, a data set, a transition, a dividend, an ageing trend and a market label.","cn":"八个义项沿同一种视角展开：把人口画成图表，这个视角再被读成结构、统计、定向人群、数据集、转变、红利、老化趋势与市场标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: a population pyramid, wide at the base and narrow at the top.","cn":"核心意象：一座底宽顶尖的人口金字塔。"},"chain":["PEOPLE COUNTED","DRAWN AS A CHART","STRUCTURE SEEN","FIGURES COLLECTED","SEGMENT NAMED","MARKET TARGETED"],"branches":[{"senses":"S1 · S2","en":"THE VIEW ITSELF: what belongs to population structure and to its figures.","cn":"视角本身：属于人口结构与统计数字的东西。"},{"senses":"S3 · S8","en":"A SLICE OF PEOPLE: the adjective becomes a countable segment and then a market target.","cn":"人群的一小块：形容词变成可数的人群，再变成市场目标。"},{"senses":"S4","en":"THE NUMBERS: demographics as a plural noun for collected figures.","cn":"数字本身：demographics 作复数名词指收集到的数据。"},{"senses":"S5 · S6","en":"MODEL AND GAIN: the transition describes change, the dividend prices it.","cn":"模型与增益：转变描述变化，红利为其定价。"},{"senses":"S7","en":"AGEING TREND: older populations and fewer births become a standing phrase.","cn":"老化趋势：人口变老与出生减少成为固定说法。"}]},"affixes":{"intro":{"en":"Demographic is built from two Greek elements; demo- is a combining form and -graphic a suffix meaning 'written or described'.","cn":"demographic 由两个希腊成分构成；demo- 是组合形式，-graphic 是表示「书写、描绘」的后缀。"},"latinIntro":{"en":"The elements are Greek rather than Latin: dēmos 'people' and graphein 'to write', the second also giving geography and biography.","cn":"这两个成分属希腊语而非拉丁语：dēmos「民众」与 graphein「书写」，后者还构成 geography 与 biography。"},"items":[{"word":"demo-","structure":"Greek dēmos (people) as a combining form","meaning":"people; population","meaningCN":"民众；人口","example":"Democracy and demography share this element.","exampleCN":"democracy 与 demography 共享这一成分。"},{"word":"-graphy","structure":"Greek graphein (to write) + -ia","meaning":"writing; a field of study","meaningCN":"书写；某研究领域","example":"Geography writes the earth, demography writes the people.","exampleCN":"地理学书写大地，人口学书写人群。"},{"word":"demography","structure":"demo- + -graphy","meaning":"the study of populations","meaningCN":"人口学","example":"Demography tracks births and deaths.","exampleCN":"人口学追踪出生与死亡。"},{"word":"demographer","structure":"demography + -er (person)","meaning":"one who studies populations","meaningCN":"人口学家","example":"The demographer projected the 2050 population.","exampleCN":"人口学家预测了 2050 年的人口。"},{"word":"demographic","structure":"demo- + -graphic (described)","meaning":"of population structure","meaningCN":"人口结构的","example":"Demographic change reshapes the workforce.","exampleCN":"人口结构变化重塑劳动力。"},{"word":"demographics","structure":"demographic + -s (plural)","meaning":"population statistics","meaningCN":"人口统计数据","example":"The demographics of the town are shifting.","exampleCN":"这座镇的人口构成在变化。"},{"word":"demographically","structure":"demographic + -ally (manner)","meaning":"in demographic terms","meaningCN":"从人口结构上看","example":"The two cities differ demographically.","exampleCN":"这两座城市在人口结构上不同。"},{"word":"epidemic","structure":"epi- (upon) + dēmos (people)","meaning":"a disease upon the people","meaningCN":"流行病","example":"An epidemic spreads through a population.","exampleCN":"流行病在人群中传播。"},{"word":"democratic","structure":"dēmos + kratos (power)","meaning":"rule by the people","meaningCN":"民主的","example":"The same dēmos root underlies democratic.","exampleCN":"同一 dēmos 词根也支撑 democratic。"}],"latinEntries":[]}},{"word":"demography","ipa_uk":"/dɪˈmɒɡrəfi/","ipa_us":"/dɪˈmɑːɡrəfi/","definition_zh":"人口学；人口统计","definition_en":"the statistical study of populations, especially births, deaths and migration","core_image":"一本登记册上并排列着出生、死亡、迁入、迁出四栏，数字逐年累积","scene":"Demography tracks births, deaths and migration across a whole region.","sceneCN":"这里 demography 指「以统计方法研究人口的学科」（第 1 个义项：系统记录与分析出生、死亡与迁移）；句意为人口学追踪整个地区的出生、死亡与迁移。图中可辨识物件：四栏登记册、逐年累积的数字、区域地图、统计笔。","pos":[{"tag":"n.","zh":"人口学；人口统计（不可数；指数据时偶用复数 demographics）"}],"collocations":[{"phrase":"formal demography","zh":"形式人口学"},{"phrase":"social demography","zh":"社会人口学"},{"phrase":"historical demography","zh":"历史人口学"},{"phrase":"applied demography","zh":"应用人口学"},{"phrase":"the demography of ageing","zh":"老龄化人口学"},{"phrase":"global demography","zh":"全球人口统计"}],"forms":[{"label":"复数（较少用，指数据）","form":"demographies"},{"label":"形容词","form":"demographic（人口统计的）"},{"label":"名词（人口学家）","form":"demographer（人口学家）"},{"label":"名词（统计数据）","form":"demographics（人口统计数据）"},{"label":"副词","form":"demographically（从人口结构上看）"}],"derivatives":[{"word":"demographic","pos":"adj./n.","zh":"人口统计的 / 特定人群"},{"word":"demographer","pos":"n.","zh":"人口学家"},{"word":"demographics","pos":"n.","zh":"人口统计数据"},{"word":"demographically","pos":"adv.","zh":"从人口结构上看"},{"word":"demos","pos":"n.","zh":"（希腊语）民众"}],"senses":[{"no":"01","title":"The statistical study of populations","titleCN":"研究人口的统计学科","definition":"the discipline that measures and analyses the size, structure and change of populations","definitionCN":"测量与分析人口规模、结构与变化的学科","example":"Demography tracks births, deaths and migration across a whole region.","exampleCN":"人口学追踪整个地区的出生、死亡与迁移。","why":"dēmos 'people' plus graphein 'write' names a field defined by writing down the people, and the modern discipline is exactly that.","whyCN":"dēmos「民众」加 graphein「书写」命名了一个「把民众写下来」的领域，现代学科正是如此。"},{"no":"02","title":"The data it produces","titleCN":"该学科产出的统计数据","definition":"the body of figures about a population produced by that study","definitionCN":"该研究产生的关于人口的整套数字","example":"The demography of the valley is recorded parish by parish.","exampleCN":"这条谷地的人口数据按教区逐一记录。","why":"the discipline and its output share one name, so demography can mean either the study or the record it keeps.","whyCN":"学科与产物共用一个名称，因此 demography 既可指研究，也可指它留下的记录。"},{"no":"03","title":"Formal demography","titleCN":"形式人口学：只算出生死亡迁移","definition":"the branch that works with births, deaths and migration alone, without social explanation","definitionCN":"只处理出生、死亡与迁移、不作社会解释的分支","example":"Formal demography can show the change but not why it happened.","exampleCN":"形式人口学能显示变化，却不能说明原因。","why":"counting needs a boundary, and the formal branch draws it at births, deaths and migration only.","whyCN":"计数需要一条边界，形式分支就把它画在出生、死亡与迁移这三处。"},{"no":"04","title":"Social demography","titleCN":"社会人口学：把人口与社会结构连起来","definition":"the branch that connects population patterns with class, family and culture","definitionCN":"把人口格局与阶层、家庭、文化联系起来的分支","example":"Social demography asks who can afford to have children.","exampleCN":"社会人口学问的是谁养得起孩子。","why":"once the counting is secure, the next question is explanation, and social demography brings class and family back in.","whyCN":"一旦计数可靠，下一个问题就是解释，社会人口学把阶层与家庭带回来。"},{"no":"05","title":"Historical demography","titleCN":"历史人口学：重建过去的人口","definition":"the branch that reconstructs past populations from registers and records","definitionCN":"从登记簿与档案重建过去人口的分支","example":"Historical demography rebuilt the parish from baptism records.","exampleCN":"历史人口学靠洗礼记录重建了这个教区的人口。","why":"where no census survives, registers become the data, and the same methods are applied backwards in time.","whyCN":"在没有普查留存的年代，登记簿成了数据，同一套方法被倒推回过去。"},{"no":"06","title":"Business demography","titleCN":"商业人口分析","definition":"the use of population analysis to describe customers and markets","definitionCN":"用人口分析描述顾客与市场","example":"Business demography showed the brand ageing with its buyers.","exampleCN":"商业人口分析显示这个品牌随顾客一起变老。","why":"customers can be counted like a population, so market research borrows the field without changing its methods.","whyCN":"顾客可以像人口一样计数，因此市场研究借用了这门学科而不改其方法。"},{"no":"07","title":"Applied demography","titleCN":"应用人口学：服务规划与政策","definition":"the use of demographic methods for planning schools, housing and pensions","definitionCN":"把人口方法用于学校、住房与养老金规划","example":"Applied demography projected how many classrooms the county needs.","exampleCN":"应用人口学预测了这个县需要多少间教室。","why":"planning needs projections rather than descriptions, so the applied branch turns the method into a forecast.","whyCN":"规划需要预测而非描述，应用分支就把方法变成一份预报。"},{"no":"08","title":"Demography of other species","titleCN":"生态学义：其他物种的种群统计","definition":"the study of births, deaths and movement in non-human populations","definitionCN":"研究非人类种群的出生、死亡与移动","example":"The demography of the wolves is followed by radio collars.","exampleCN":"狼群的种群统计靠无线电项圈追踪。","why":"the four columns work for any species, so ecology uses the same word for packs and herds.","whyCN":"那四栏账对任何物种都适用，因此生态学用同一个词指兽群与畜群。"}],"etymology":{"intro":{"en":"Demography joins Greek dēmos 'people' to -graphy from graphein 'to write'; the word was coined in 1855 by Achille Guillard. Dates are approximate.","cn":"demography 把希腊 dēmos「民众」与来自 graphein「书写」的 -graphy 结合；该词由 Achille Guillard 于 1855 年造出。年代均为约数。"},"items":[{"era":"GREEK DEMOS","en":"Dēmos named the people of a town or district; it survives in democracy, epidemic and demography.","cn":"dēmos 指一城或一区的民众；它留存于 democracy、epidemic 与 demography 中。"},{"era":"GREEK GRAPHEIN","en":"Graphein 'to write' produced -graphia, a suffix for description or a field of study, as in geography.","cn":"graphein「书写」产生 -graphia，即表示描述或研究领域的后缀，如 geography。"},{"era":"GUILLARD 1855","en":"Achille Guillard introduced démographie in 1855 in a work on human statistics, defining it as the natural and social history of the human species.","cn":"Achille Guillard 于 1855 年在一部人类统计著作中提出 démographie，并把它界定为人类的自然史与社会史。"},{"era":"ENGLISH ADOPTION","en":"English adopted demography in the later nineteenth century, and the adjective demographic followed.","cn":"英语在 19 世纪后期吸收 demography，形容词 demographic 随后出现。"},{"era":"BRANCHING","en":"The twentieth century split the field into formal, social, historical and applied branches with their own methods.","cn":"20 世纪该领域分为形式、社会、历史与应用等分支，各有方法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest English citation of demography is not precisely recorded, and the exact wording of Guillard's definition has variant translations.","cn":"来源不确定（首见年代）：demography 在英语中的最早书证没有精确记录；Guillard 定义的确切措辞存在不同译本。"}]},"similar":{"note":{"en":"Group one holds the demo- family members that are routinely confused; group two holds neighbouring fields and instruments.","cn":"第一组是 demo- 词族中常被混淆的成员；第二组是相邻的学科与工具。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"demographics","ipa":"/ˌdeməˈɡræfɪks/","tag":"data, not discipline","definition":"The plural noun for population figures or segments; demography is the field that produces them.","definitionCN":"复数名词，指人口数字或人群构成；demography 是产出它们的学科。"},{"word":"demographic","ipa":"/ˌdeməˈɡræfɪk/","tag":"adjective","definition":"The adjective belonging to the field, also used as a countable noun for a segment.","definitionCN":"属于该领域的形容词，也可作可数名词指某一人群。"},{"word":"demographer","ipa":"/dɪˈmɒɡrəfə/","tag":"the practitioner","definition":"A person who practises demography; the word names a profession.","definitionCN":"指从事人口学工作的人；命名一种职业。"},{"word":"demographic","ipa":"/ˌdeməˈɡræfɪk/","tag":"spelling trap","definition":"Demography ends in -graphy, its adjective in -graphic; mixing the endings produces forms that do not exist.","definitionCN":"demography 以 -graphy 结尾，其形容词以 -graphic 结尾；混用会造出不存在的形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"population studies","ipa":"/ˌpɒpjʊˈleɪʃn ˈstʌdiz/","tag":"broader umbrella","definition":"An umbrella term covering demography together with sociology and economics of population.","definitionCN":"涵盖人口学及人口社会学、人口经济学的总称。"},{"word":"census","ipa":"/ˈsensəs/","tag":"one instrument","definition":"The periodic official count; demography uses census data along with registers and surveys.","definitionCN":"指定期官方清点；人口学除普查外还使用登记与抽样。"},{"word":"statistics","ipa":"/stəˈtɪstɪks/","tag":"the method","definition":"The general mathematics of data; demography applies it to populations specifically.","definitionCN":"泛指数据数学方法；人口学把它专门用于人口。"},{"word":"epidemiology","ipa":"/ˌepiˌdiːmiˈɒlədʒi/","tag":"shared root, other target","definition":"The study of disease in populations; it shares dēmos with demography but tracks illness, not births.","definitionCN":"研究人群中疾病的学科；与人口学共享 dēmos，但追踪疾病而非出生。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"demo- 'people' + -graphy 'writing': writing down the people.","cn":"demo-「民众」+ -graphy「书写」：把民众写下来。"},{"en":"The family runs demography, demographer, demographic, demographics, demographically.","cn":"同族词包括 demography、demographer、demographic、demographics、demographically。"},{"en":"The branches are formal, social, historical and applied.","cn":"分支包括形式、社会、历史与应用四类。"},{"en":"Coined in 1855 by Achille Guillard, which is why the word feels nineteenth-century.","cn":"由 Achille Guillard 于 1855 年造出，因此这个词带着 19 世纪的气息。"},{"en":"Formal demography counts; social demography explains.","cn":"形式人口学负责计数，社会人口学负责解释。"}],"abstract":[{"en":"Picture a ledger with four columns: born, died, arrived, left.","cn":"想象一本四栏账簿：出生、死亡、迁入、迁出。"},{"en":"Picture a village reconstructed from baptism ink.","cn":"想象一个靠洗礼墨水重建起来的村庄。"},{"en":"Picture a school board asking how many desks in ten years.","cn":"想象校董会在问十年后要多少张课桌。"}]},"examples":[{"en":"Demography shows the parish losing a generation.","cn":"人口统计显示这个教区正在失去一代人。"},{"en":"She teaches demography at the university.","cn":"她在大学教人口学。"},{"en":"The demography of the forest changed after the fire.","cn":"火灾之后，这片森林的种群统计发生了变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「demo（人民）+ graphy（书写）」——把人口出生死亡一笔笔记下 → 人口学","word":"demography"},"root":"希腊 dēmos「民众」+ graphein「书写」（经 -graphy）；1855 年由 Achille Guillard 造出，属希腊语复合，非拉丁词根。英语 demography。","sensesIntro":{"en":"Eight senses follow one practice: births, deaths and movement are written down, and the practice is then read as a discipline, a body of data, four branches and an ecological tool.","cn":"八个义项沿同一种做法展开：把出生、死亡与移动写下来，这个做法再被读成学科、数据集、四个分支与一种生态工具。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ledger with four columns filling year by year.","cn":"核心意象：一本四栏账簿逐年填满。"},"chain":["PEOPLE RECORDED","BIRTHS AND DEATHS","MIGRATION ADDED","FIELD FORMALIZED","BRANCHES SPLIT","APPLIED ELSEWHERE"],"branches":[{"senses":"S1 · S3","en":"FIELD AND FORMAL CORE: the discipline first, then its narrowest counting branch.","cn":"学科与形式核心：先是学科，再是最窄的计数分支。"},{"senses":"S2","en":"THE RECORD: the word also names the data written down.","cn":"记录本身：这个词也指被写下的数据。"},{"senses":"S4 · S5","en":"SOCIAL AND HISTORICAL: explanation and reconstruction are the two wider branches.","cn":"社会与历史：解释与重建是两个更宽的分支。"},{"senses":"S6 · S7","en":"APPLIED USE: business and planning both borrow the methods.","cn":"应用：商业与规划都借用这套方法。"},{"senses":"S8","en":"OTHER SPECIES: wolves get the same four columns.","cn":"其他物种：狼也用同样的四栏账。"}]},"affixes":{"intro":{"en":"Demography is a Greek compound of a combining form and a suffix, with no Latin elements in its base.","cn":"demography 是希腊语的组合形式加后缀构成的复合词，基底不含拉丁成分。"},"latinIntro":{"en":"There is no Latin element here: dēmos 'people' and graphein 'to write' are Greek, and the same suffix built geography and biography.","cn":"这里没有拉丁成分：dēmos「民众」与 graphein「书写」都是希腊语，同一后缀还构成 geography 与 biography。"},"items":[{"word":"demo-","structure":"Greek dēmos (people) as a combining form","meaning":"people; population","meaningCN":"民众；人口","example":"The element also opens democracy and epidemic.","exampleCN":"这一成分也出现在 democracy 与 epidemic 开头。"},{"word":"-graphy","structure":"Greek graphein (to write) + -ia","meaning":"writing; description","meaningCN":"书写；描述","example":"Biography writes a life, geography writes the earth.","exampleCN":"传记写一生，地理写大地。"},{"word":"demography","structure":"demo- + -graphy","meaning":"the study of populations","meaningCN":"人口学","example":"Demography tracks births and migration.","exampleCN":"人口学追踪出生与迁移。"},{"word":"demographer","structure":"demography + -er (person)","meaning":"one who studies populations","meaningCN":"人口学家","example":"The demographer rebuilt the parish rolls.","exampleCN":"人口学家重建了教区名册。"},{"word":"demographic","structure":"demo- + -graphic (described)","meaning":"of population structure","meaningCN":"人口结构的","example":"Demographic data guide the plan.","exampleCN":"人口数据为规划提供依据。"},{"word":"demographics","structure":"demographic + -s (plural)","meaning":"population statistics","meaningCN":"人口统计数据","example":"The demographics of the county are changing.","exampleCN":"这个县的人口构成在变化。"},{"word":"demographically","structure":"demographic + -ally (manner)","meaning":"in population terms","meaningCN":"从人口结构上看","example":"The region is demographically older.","exampleCN":"这个地区在人口结构上更老。"},{"word":"epidemiology","structure":"epi- (upon) + dēmos + -logia (study)","meaning":"the study of disease in populations","meaningCN":"流行病学","example":"Epidemiology shares the people root.","exampleCN":"流行病学共享「民众」词根。"},{"word":"geography","structure":"gē (earth) + graphein (write)","meaning":"writing about the earth","meaningCN":"地理学","example":"Geography uses the same writing suffix.","exampleCN":"地理学使用同一「书写」后缀。"}],"latinEntries":[]}},{"word":"migration pattern","ipa_uk":"/ˌmaɪˈɡreɪʃn ˈpætən/","ipa_us":"/ˌmaɪˈɡreɪʃən ˈpætərn/","definition_zh":"迁移模式；迁徙规律","definition_en":"the regular route, direction and timing along which people or animals move","core_image":"一张地图上画着几条同向箭头，每年在同一季节出现，线路几乎不变","scene":"Satellite tags revealed a migration pattern that crosses three countries.","sceneCN":"这里 migration pattern 指「迁徙的固定路线与时间规律」（第 2 个义项：动物逐年沿同一路径移动的规律）；句意为卫星标签揭示出一条横跨三国的迁徙模式。图中可辨识物件：同向箭头、季节标记、国界线、卫星轨迹点。","pos":[{"tag":"n.","zh":"迁移模式；迁徙规律（可数，复数 migration patterns）"}],"collocations":[{"phrase":"seasonal migration pattern","zh":"季节性迁徙模式"},{"phrase":"migration pattern of birds","zh":"鸟类的迁徙规律"},{"phrase":"rural-urban migration pattern","zh":"城乡迁移模式"},{"phrase":"changing migration pattern","zh":"变化中的迁移模式"},{"phrase":"migration pattern data","zh":"迁移模式数据"},{"phrase":"circular migration pattern","zh":"循环迁移模式"}],"forms":[{"label":"复数","form":"migration patterns"},{"label":"相关动词","form":"migrate（迁移）"},{"label":"相关名词","form":"migration（迁移）"},{"label":"相关形容词","form":"migratory（迁徙的）"},{"label":"相关名词","form":"migrant（迁徙者；移民）"},{"label":"相关名词","form":"pattern（模式；图案）"}],"derivatives":[{"word":"migrate","pos":"v.","zh":"迁移；迁徙"},{"word":"migration","pos":"n.","zh":"迁移；迁徙"},{"word":"migratory","pos":"adj.","zh":"迁徙的"},{"word":"migrant","pos":"n./adj.","zh":"移民；候鸟 / 迁徙的"},{"word":"pattern","pos":"n.","zh":"模式；图案；样式"}],"senses":[{"no":"01","title":"A regular route for people","titleCN":"人口迁移的固定路线","definition":"the repeated direction and timing of people moving from one place to another","definitionCN":"人们从一地迁往另一地时重复出现的方向与时间","example":"The census records the migration pattern from farm to factory town.","exampleCN":"人口普查记录了从农场到工厂镇的迁移模式。","why":"migration names the movement and pattern names its repeated shape, so the phrase describes movement that is not random.","whyCN":"migration 命名移动，pattern 命名其重复的形状，因此这个短语描述的是非随机的移动。"},{"no":"02","title":"A seasonal animal route","titleCN":"动物的季节性迁徙规律","definition":"the yearly route and timing followed by animals between breeding and wintering grounds","definitionCN":"动物在繁殖地与越冬地之间逐年遵循的路线与时间","example":"Satellite tags revealed a migration pattern that crosses three countries.","exampleCN":"卫星标签揭示出一条横跨三国的迁徙模式。","why":"because animals repeat the same path each year, their movement is the clearest case of a pattern.","whyCN":"动物每年重复同一条路，因此它们的移动是最典型的「模式」。"},{"no":"03","title":"A rural-urban flow","titleCN":"城乡迁移模式","definition":"the movement of people from countryside to cities, often in stages","definitionCN":"人口由乡村流向城市、常分阶段进行的移动","example":"The rural-urban migration pattern emptied the villages first and the towns later.","exampleCN":"城乡迁移模式先抽空村庄，之后才轮到小镇。","why":"a direction that repeats across a whole society is a pattern, and the countryside-to-city flow is the classic one.","whyCN":"在整个社会中重复出现的流向就是模式，而由乡到城的流动正是经典一例。"},{"no":"04","title":"Circular movement","titleCN":"循环迁移模式：往返而不定居","definition":"repeated going and returning between two places without permanent settlement","definitionCN":"在两处之间反复往返而不永久定居","example":"Seasonal work produced a circular migration pattern across the border.","exampleCN":"季节性工作造成了跨境往返的循环迁移模式。","why":"when movement returns to its start, the pattern closes into a loop, which is why it is named separately.","whyCN":"当移动回到起点，模式就闭合成一个环，因此它被单独命名。"},{"no":"05","title":"Movement in steps","titleCN":"阶梯式迁移模式：逐级向城市靠近","definition":"movement toward a city in successive stages rather than one leap","definitionCN":"分几个阶段逐步向城市靠近，而非一步到位","example":"The step migration pattern moved families to the county town before the capital.","exampleCN":"阶梯式迁移模式让家庭先进县城，再进首都。","why":"family migration often proceeds by stages, so the staircase is a pattern in its own right.","whyCN":"家庭迁移常分阶段推进，因此这种阶梯本身就是一种模式。"},{"no":"06","title":"A measurable series","titleCN":"可测量的数据序列","definition":"the sequence of movements recorded over time and plotted as data","definitionCN":"随时间记录并绘制成数据的移动序列","example":"The migration pattern data show a peak every October.","exampleCN":"迁移模式数据显示每年十月出现峰值。","why":"once the route is counted year after year, it becomes a series with a shape that can be plotted.","whyCN":"一旦路线被年复一年地计数，它就变成一条可绘出形状的序列。"},{"no":"07","title":"A bird flyway","titleCN":"鸟类迁飞通道","definition":"the corridor along which a population of birds travels each year","definitionCN":"某一鸟群每年行经的走廊地带","example":"The flyway is the migration pattern written on the map.","exampleCN":"迁飞通道就是画在地图上的迁徙模式。","why":"geographers name the corridor, and the corridor is simply the pattern given a boundary.","whyCN":"地理学者给走廊命名，而走廊不过是给模式画了边界。"},{"no":"08","title":"A route shifting with climate","titleCN":"随气候变化而改变的路线","definition":"a route whose timing or direction changes as temperatures and seasons shift","definitionCN":"随气温与季节变化而改变时间或方向的路线","example":"Warming seas have altered the migration pattern of the whales.","exampleCN":"海水变暖改变了鲸的迁徙模式。","why":"a pattern held in place by climate can move when the climate moves, which is why the phrase pairs with changing.","whyCN":"被气候固定的模式会随气候变化而移动，因此这个短语常与 changing 搭配。"}],"etymology":{"intro":{"en":"Migration comes from Latin migratio, from migrare 'to move'; pattern comes through Old French patron from Latin patronus 'protector'. Dates are approximate.","cn":"migration 来自拉丁 migratio，源于 migrare「移动」；pattern 经古法语 patron 来自拉丁 patronus「保护人」。年代均为约数。"},"items":[{"era":"LATIN MIGRARE","en":"Migrare meant 'to move from one place to another'. Its deeper origin is uncertain; a link to meare 'to go, pass' is a hypothesis, not an established derivation.","cn":"migrare 意为「从一处迁往另一处」。其更深来源不确定；把它与 meare「行走、经过」联系只是假说，并非已证实的派生。"},{"era":"LATIN MIGRATIO","en":"Migratio named a removal or change of abode; English took migration in the seventeenth century.","cn":"migratio 指迁居或更换住所；英语于 17 世纪吸收 migration。"},{"era":"LATIN PATRONUS","en":"Patronus meant 'protector, patron', from pater 'father'; Old French patron gained the sense of a model or example.","cn":"patronus 意为「保护人、赞助人」，源自 pater「父亲」；古法语 patron 又获得「范本、样式」之义。"},{"era":"ENGLISH PATTERN","en":"English pattern, from the same French word, first meant a model to copy and later a repeated arrangement.","cn":"英语 pattern 出自同一法语词，最初指供模仿的范本，后来指重复出现的排列。"},{"era":"THE MODERN PHRASE","en":"The compound migration pattern became common in the twentieth century with bird banding and census mapping.","cn":"组合 migration pattern 在 20 世纪随鸟类环志与普查制图而普及。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest use of the exact phrase is not precisely recorded, and the origins of Latin migrare and of the 'model' sense of pattern both remain debated.","cn":"来源不确定（首见年代）：这一确切短语的最早使用没有精确记录；拉丁 migrare 的来源与 pattern 的「范本」义来源都仍有争议。"}]},"similar":{"note":{"en":"Group one holds migration words that are easily mixed; group two holds terms for routes and repeated movement.","cn":"第一组是容易混淆的 migration 词族；第二组是路线与重复移动的相关词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"migration","ipa":"/maɪˈɡreɪʃn/","tag":"the movement","definition":"The act of moving; a migration pattern is the repeated shape that movement takes.","definitionCN":"指移动本身；migration pattern 是这种移动反复呈现的形状。"},{"word":"migratory","ipa":"/ˈmaɪɡrətəri/","tag":"adjective","definition":"Describes a species or person that migrates, as in migratory birds; it does not name the route.","definitionCN":"描述会迁徙的物种或人，如候鸟；不命名路线。"},{"word":"migrant","ipa":"/ˈmaɪɡrənt/","tag":"the mover","definition":"A person or animal that moves; migrant workers are the human case of the same word.","definitionCN":"指移动的人或动物；migrant workers 是这个词的人的例子。"},{"word":"emigration","ipa":"/ˌemɪˈɡreɪʃn/","tag":"one direction","definition":"E- 'out' plus migration: leaving a country, seen from the place left behind.","definitionCN":"e-「向外」加 migration：离开一国，从被离开之地的视角看。"}]},{"heading":"NEAR MEANING","entries":[{"word":"flyway","ipa":"/ˈflaɪweɪ/","tag":"bird corridor","definition":"The fixed corridor used by migrating birds; it is the geographic name for one kind of pattern.","definitionCN":"指候鸟使用的固定走廊；是某一类模式在地理上的名称。"},{"word":"route","ipa":"/ruːt/","tag":"a path","definition":"The path taken; a route can be travelled once, while a pattern implies repetition.","definitionCN":"指所走的路径；路线可以只走一次，而模式含重复之意。"},{"word":"movement pattern","ipa":"/ˈmuːvmənt ˈpætən/","tag":"wider term","definition":"Any repeated shape of movement, from traffic to troops; it is not tied to long-distance relocation.","definitionCN":"泛指任何重复的移动形状，从交通到部队；不限于长途迁居。"},{"word":"trend","ipa":"/trend/","tag":"direction of change","definition":"A general direction in which something is changing; a pattern may persist without any trend.","definitionCN":"指某事物变化的大方向；模式可以持续存在而不构成趋势。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"migration 'moving' + pattern 'repeated shape': movement that repeats.","cn":"migration「移动」+ pattern「重复形状」：重复发生的移动。"},{"en":"The family runs migrate, migration, migratory, migrant, pattern.","cn":"同族词包括 migrate、migration、migratory、migrant、pattern。"},{"en":"Fixed phrases mark the senses: seasonal migration pattern, rural-urban migration pattern, circular migration pattern.","cn":"固定搭配标出各义项：季节性迁徙模式、城乡迁移模式、循环迁移模式。"},{"en":"Bird banding and satellite tags are how such patterns are proved.","cn":"鸟类环志与卫星标签是证实这类模式的手段。"},{"en":"Pattern came from a word for a model to copy, which is why a route that repeats is a pattern.","cn":"pattern 出自「供模仿的范本」，因此重复的路线才叫模式。"}],"abstract":[{"en":"Picture arrows on a map that reappear every autumn in the same places.","cn":"想象地图上的箭头每年秋天在同一处重新出现。"},{"en":"Picture a river of birds following a line no one drew.","cn":"想象一条鸟的河流沿着无人画过的线走。"},{"en":"Picture a family moving one town closer each decade.","cn":"想象一家人每十年往城市靠近一镇。"}]},"examples":[{"en":"The migration pattern of the geese follows four river valleys.","cn":"这些雁的迁徙模式沿四条河谷展开。"},{"en":"Census data reveal a migration pattern toward the coast.","cn":"普查数据揭示出向沿海迁移的模式。"},{"en":"Dams can break a migration pattern built over centuries.","cn":"水坝能打断延续数百年的迁徙模式。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「migration（迁移）+ pattern（图案）」——每年在同一张图上画同样的箭头 → 迁移模式","word":"migration pattern"},"root":"拉丁 migrare「迁移」（更深来源不确定）+ migratio「迁居」；pattern 经古法语 patron 来自拉丁 patronus「保护人」（源自 pater「父亲」），后引申为「范本、样式」。英语 migration pattern。","sensesIntro":{"en":"Eight senses follow one shape: movement repeats, and that repetition is then read as a human route, an animal season, a rural flow, a loop, a staircase, a data series, a flyway and a route that is now shifting.","cn":"八个义项沿同一个形状展开：移动反复发生，这个重复再被读成人的路线、动物的季节、乡村流向、环线、阶梯、数据序列、迁飞通道，以及正在改变的路线。"},"semanticMap":{"core":{"en":"CORE IMAGE: arrows that reappear in the same places every season.","cn":"核心意象：每个季节都在同一处重新出现的箭头。"},"chain":["MOVEMENT","REPETITION","DIRECTION FIXED","TIMING FIXED","RECORDED AS DATA","SHAPE CHANGES"],"branches":[{"senses":"S1 · S3","en":"HUMAN ROUTES: farm to city, and the stages in between.","cn":"人的路线：从乡村到城市，以及其间的阶段。"},{"senses":"S2 · S7","en":"ANIMAL SEASONS: the same shape drawn as a flyway on a map.","cn":"动物的季节：同一形状在地图上画成迁飞通道。"},{"senses":"S4 · S5","en":"LOOPS AND STAIRS: movement without settlement, and movement in steps.","cn":"环线与阶梯：不定居的往返，与分步靠近。"},{"senses":"S6","en":"DATA SERIES: the pattern becomes a curve with peaks.","cn":"数据序列：模式变成带峰值的曲线。"},{"senses":"S8","en":"SHIFTING SHAPE: warming seas redraw the same arrows.","cn":"变化的形状：海水变暖把同样的箭头重画。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin-derived noun of moving to an English noun of repeated shape that came through French from a word for a patron.","cn":"这个短语把源自拉丁的「移动」名词，接到一个表示「重复形状」的英语名词上，后者经法语来自表示「保护人」的词。"},"latinIntro":{"en":"Latin migrare gives migrate, migration, migratory and migrant; Latin patronus gives patron, pattern and patronize.","cn":"拉丁 migrare 衍生 migrate、migration、migratory 与 migrant；拉丁 patronus 衍生 patron、pattern 与 patronize。"},"items":[{"word":"migrare","structure":"migrare, migravi, migratum (Latin verb, first conjugation)","meaning":"to move, change abode","meaningCN":"迁移；迁居","example":"The root supplies the movement itself.","exampleCN":"词根提供移动本身。"},{"word":"migration","structure":"migrare + -ation (action)","meaning":"a moving from place to place","meaningCN":"迁移","example":"Migration peaks in early autumn.","exampleCN":"迁移在初秋达到高峰。"},{"word":"migrate","structure":"migrare -> migrate","meaning":"to move to another place","meaningCN":"迁往他处","example":"The birds migrate along the coast.","exampleCN":"这些鸟沿海南迁。"},{"word":"migratory","structure":"migrate + -ory (tending to)","meaning":"given to migrating","meaningCN":"有迁徙习性的","example":"The marsh is a stop for migratory birds.","exampleCN":"这片沼泽是候鸟的停歇地。"},{"word":"migrant","structure":"migrate + -ant (one who)","meaning":"one who moves","meaningCN":"迁移者","example":"Migrant workers followed the harvest.","exampleCN":"流动工人跟着收成走。"},{"word":"patronus","structure":"patronus, patroni (m., second declension)","meaning":"protector, patron","meaningCN":"保护人；赞助人","example":"The Latin noun named a protector.","exampleCN":"这个拉丁名词指保护人。"},{"word":"pattern","structure":"Old French patron -> English pattern","meaning":"a model; a repeated arrangement","meaningCN":"范本；重复的排列","example":"The tiles form a pattern.","exampleCN":"这些砖排成一个图案。"},{"word":"migration pattern","structure":"migration + pattern","meaning":"a repeated route of movement","meaningCN":"重复的迁移路线","example":"Satellite tags revealed the migration pattern.","exampleCN":"卫星标签揭示了迁徙模式。"},{"word":"emigration","structure":"e- (out) + migration","meaning":"leaving a country","meaningCN":"移居国外","example":"Emigration emptied the island.","exampleCN":"向外移民使这座岛空了。"}],"latinEntries":[{"word":"migrare","structure":"migrare, migravi, migratum (verb, first conjugation)","meaning":"to move, change abode","meaningCN":"迁移；迁居"},{"word":"migratio","structure":"migratio, migrationis (f., third declension)","meaning":"a removal, change of abode","meaningCN":"迁居；迁移"},{"word":"patronus","structure":"patronus, patroni (m., second declension)","meaning":"protector, patron","meaningCN":"保护人；赞助人"}]}}]);
